INSERT OR REPLACE INTO channels (id, status, is_primary, data, created_at, updated_at, genre) VALUES ('XNK0VFX39Xv', 1, NULL, '{"title":"伤寒论・(人纪)","description":"","_microfeed":{"author":"张仲景(倪・注)","chengShu":"汉朝","chapterCount":398,"hot":1,"comment":"","sourceImagePath":"","case":"9"}}', '2024-03-21T05:51:53.000Z', '2024-03-21T05:51:53.000Z', 'cat_renji01');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2ZIcGW6v9Qg', 1, '{"title":"伤寒论原序","description":"<p>        经方在我国汉朝以前其实就已经存在，应该是来自西域，而且已经在我国流传千年，只是经方在汉朝之前没有正式的辨症依据，用来指导如何使用经方。知道如何正确使用经方的医师非常之少，一直等到汉朝出现一位名医张仲景，他是利用内经热论中的六经辨证将经方如何使用系统化的第一人，也因此他至今仍被历代中医尊称为医圣。最初他的经方著作书名叫做伤寒杂病论，而张仲景在此书的前言中就有说明，他的草药知识是来自胎胪药录，到了宋朝以后政府开始成立所谓制版局，当时以林亿为主的一群人将这伤寒杂病论区分为二书，一名伤寒论，一名金匮，自此以后就有这二本书在民间流传至今，本文伤寒教学课程就是指这第一本书伤寒论的教学，其中所有的处方就是所谓的经方，原书结尾有所谓霍乱病脉症治等篇。我将之编入金匮的第一篇，历代对这篇都有许多争议，有些名经方家认为应该留在伤寒论中，有些认为应该编入金匮中，我个人对此的认定是伤寒论只讨论六经辨症，可以讨论到厥阴篇就结束，其它的可以都放在金匮中，因为金匮本来就是分门别类的一个杂病论，从内科到肠胃科到妇科等等都有，如此后来的学者就比较容易做一简单的区隔，先研究伤寒论，等到所有伤寒论的六经辨症条辨都能够很纯熟的运用之后再进入金匮时，就可以很迅速的进入这经方的殿堂。读了伤寒论的好处在哪里呢？有心研究经方的有志之士必须知道一点，就是因为有了伤寒论的六经辨证法则的基础，我们经方家就敢大剂的、大量的使用经方绝对不会出一点错，由于经方都是使用极峻的药，讲究的是一剂就知，二剂就已的效果，也由于药物的力道强劲有力，而且很多都是有毒的天然药物。过去许多医家就是因为无法透彻了解伤寒论的六经辨证法则，于是自然而然就不敢轻易使用经方，同时由于胎胪药录的失传，造成许多医家对于伤寒论更是一知半解，也就是因为如此，所以自汉朝张仲景医圣至今，历代所出现的经方名家并不多，所以千年以来真正懂得伤寒论的医家是屈指可数的，温病派也同时因为一些医家对伤寒的误解因而应运而生，由于温病方使用的药物不像经方那样的剽悍，都是讲究温和滋阴调养进补等等方式来治病，与经方是完全不同的境界，因为温病方少用峻药，就算吃错药物，也无多大不良的反应，于是就受到一般医师的喜欢，也由于绝大多数的中医都是温病派中医，终于导致千年以后造成人们对于中医的误解，都认为中医就是慢慢来，中药是吃不死，但是也无法治病的错误观念。这都是历代温病派的中医累积传承错误的中医知识所造成的结果，本次伤寒论的教学就是希望能给有心学习正统中医的后起之秀一个研究经方的机会，伤寒论的六经辨症法则就是进入经方大门的唯一方法，娴熟于伤寒论后，之后再进入金匮时就能很灵活的使用金匮中的经方。</p>\n<p>        附上一重要见证案例：于传授期间，讨论到大陷胸汤时，适逢同学中一位在急诊处服务多年的刘医师存厚，他提及此症之心下痞鞕就发生在急性胰脏炎病人身上，在腹部计算机断层扫描片子上可以看到其中积有许多痰水，西医称之为（edema）跟伤寒论所述的大陷胸汤证完全一样的。使本次教学增色不少，也由于他的宝贵经验，必能使后之学者能救病人于危急之中，其功不可没，特于此序文中说明，以传后世。</p>\n<p>                                                                                                                                                                                                                                                 汉唐中医 倪海厦 谨记 01／06／2007</p><p>          论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外而悴其内。皮之不存，毛将安附焉？卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，赍百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为涕泣。痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，蠢若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也！余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救。乃勤求古训，博采众方，撰用《素问》 、《九卷》 、 《八十一难》 、 《阴阳大论》 、 《胎胪药录》 ，并《平脉辨证》 ，为《伤寒杂病论》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络腑俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文，中世有长桑、扁鹊，汉有公乘阳庆及仓公，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。孔子云：生而知之者上，学则亚之，多闻博识知之次也。余宿尚方术，请事斯语</p>\n<p>                                                                                                               汉 长沙太守南阳张机 序</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040001}}', '2024-09-19T16:46:31.000Z', '2024-09-19T16:46:31.000Z', '2024-09-19T16:46:31.000Z', '经方在我国汉朝以前其实就已经存在，应该是来自西域，而且已经在我国流传千年，只是经方在汉朝之前没有正式的辨症依据，用来指导如何使用经方。知道如何正确使用经方的医师非常之少，一直等到汉朝出现一位名医张仲景，他是利用内经热论中的六经辨证将经方如何使用系统化的第一人，也因此他至今仍被历代中医尊称为医圣。最初他的经方著作书名叫做伤寒杂病论，而张仲景在此书的前言中就有说明，他的草药知识是来自胎胪药录，到了宋朝以后政府开始成立所谓制版局，当时以林亿为主的一群人将这伤寒杂病论区分为二书，一名伤寒论，一名金匮，自此以后就有这二本书在民间流传至今，本文伤寒教学课程就是指这第一本书伤寒论的教学，其中所有的处方就是所谓的经方，原书结尾有所谓霍乱病脉症治等篇。我将之编入金匮的第一篇，历代对这篇都有许多争议，有些名经方家认为应该留在伤寒论中，有些认为应该编入金匮中，我个人对此的认定是伤寒论只讨论六经辨症，可以讨论到厥阴篇就结束，其它的可以都放在金匮中，因为金匮本来就是分门别类的一个杂病论，从内科到肠胃科到妇科等等都有，如此后来的学者就比较容易做一简单的区隔，先研究伤寒论，等到所有伤寒论的六经辨症条辨都能够很纯熟的运用之后再进入金匮时，就可以很迅速的进入这经方的殿堂。读了伤寒论的好处在哪里呢？有心研究经方的有志之士必须知道一点，就是因为有了伤寒论的六经辨证法则的基础，我们经方家就敢大剂的、大量的使用经方绝对不会出一点错，由于经方都是使用极峻的药，讲究的是一剂就知，二剂就已的效果，也由于药物的力道强劲有力，而且很多都是有毒的天然药物。过去许多医家就是因为无法透彻了解伤寒论的六经辨证法则，于是自然而然就不敢轻易使用经方，同时由于胎胪药录的失传，造成许多医家对于伤寒论更是一知半解，也就是因为如此，所以自汉朝张仲景医圣至今，历代所出现的经方名家并不多，所以千年以来真正懂得伤寒论的医家是屈指可数的，温病派也同时因为一些医家对伤寒的误解因而应运而生，由于温病方使用的药物不像经方那样的剽悍，都是讲究温和滋阴调养进补等等方式来治病，与经方是完全不同的境界，因为温病方少用峻药，就算吃错药物，也无多大不良的反应，于是就受到一般医师的喜欢，也由于绝大多数的中医都是温病派中医，终于导致千年以后造成人们对于中医的误解，都认为中医就是慢慢来，中药是吃不死，但是也无法治病的错误观念。这都是历代温病派的中医累积传承错误的中医知识所造成的结果，本次伤寒论的教学就是希望能给有心学习正统中医的后起之秀一个研究经方的机会，伤寒论的六经辨症法则就是进入经方大门的唯一方法，娴熟于伤寒论后，之后再进入金匮时就能很灵活的使用金匮中的经方。 附上一重要见证案例：于传授期间，讨论到大陷胸汤时，适逢同学中一位在急诊处服务多年的刘医师存厚，他提及此症之心下痞鞕就发生在急性胰脏炎病人身上，在腹部计算机断层扫描片子上可以看到其中积有许多痰水，西医称之为（edema）跟伤寒论所述的大陷胸汤证完全一样的。使本次教学增色不少，也由于他的宝贵经验，必能使后之学者能救病人于危急之中，其功不可没，特于此序文中说明，以传后世。 汉唐中医 倪海厦 谨记 01／06／2007 论曰：余每览越人入虢之诊，望齐侯之色，未尝不慨然叹其才秀也。怪当今居世之士，曾不留神医药，精究方术，上以疗君亲之疾，下以救贫贱之厄，中以保身长全，以养其生，但竞逐荣势，企踵权豪，孜孜汲汲，惟名利是务，崇饰其末，忽弃其本，华其外而悴其内。皮之不存，毛将安附焉？卒然遭邪风之气，婴非常之疾，患及祸至，而方震栗，降志屈节，钦望巫祝，告穷归天，束手受败，赍百年之寿命，持至贵之重器，委付凡医，恣其所措，咄嗟呜呼！厥身已毙，神明消灭，变为异物，幽潜重泉，徒为涕泣。痛夫！举世昏迷，莫能觉悟，不惜其命，若是轻生，彼何荣势之足云哉！而进不能爱人知人，退不能爱身知己，遇灾值祸，身居厄地，蒙蒙昧昧，蠢若游魂。哀乎！趋势之士，驰竞浮华，不固根本，忘躯徇物，危若冰谷，至于是也！余宗族素多，向余二百，建安纪元以来，犹未十稔，其死亡者，三分有二，伤寒十居其七。感往昔之沦丧，伤横夭之莫救。乃勤求古训，博采众方，撰用《素问》 、《九卷》 、 《八十一难》 、 《阴阳大论》 、 《胎胪药录》 ，并《平脉辨证》 ，为《伤寒杂病论》合十六卷，虽未能尽愈诸病，庶可以见病知源，若能寻余所集，思过半矣。夫天布五行，以运万类，人禀五常，以有五脏，经络腑俞，阴阳会通，玄冥幽微，变化难极，自非才高识妙，岂能探其理致哉！上古有神农、黄帝、歧伯、伯高、雷公、少俞、少师、仲文，中世有长桑、扁鹊，汉有公乘阳庆及仓公，下此以往，未之闻也。观今之医，不念思求经旨，以演其所知，各承家技，终始顺旧，省疾问病，务在口给。相对须臾，便处汤药，按寸不及尺，握手不及足，人迎趺阳，三部不参，动数发息，不满五十，短期未知决诊，九候曾无仿佛，明堂阙庭，尽不见察，所谓窥管而已。夫欲视死别生，实为难矣。孔子云：生而知之者上，学则亚之，多闻博识知之次也。余宿尚方术，请事斯语 汉 长沙太守南阳张机 序', '2024-09-19T16:46:31.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('23iawSA6Ryt', 1, '{"title":"前言","description":"<p>         在难经中有“五十八难曰：伤寒有几？其脉有变否？然：伤寒有五，有中风，有伤寒，有湿温，有热病，有温病，其所苦各不同。</p>\n<p>         ”伤寒这两字，就广义的定义来说，应该说是“伤于寒”。</p>\n<p>         以上五种病，广义地来说，都是伤于寒之后所引起的。另一种外感病我们称为时疫，也就是不管体质如何，男女老少感染时疫之后，都是同一种症状，所以我们可以分为伤寒、时疫这两类，在治病的时候，处方用药的思路略有不同。医圣张仲景为集经方之大成者，以内经热论中六经辨症的思路，很适当地将古人传下的经典汤方，用六经辨症的法则，来让后学者都能很精准地使用经方。</p>\n<p>         在讲六经之前，我们用一个图来给诸位一个概念，所谓的五运六气中的六气，在一天的十二个时辰，我们分为六气，$g{六气图} 如图所示：</p>\n<p>如果是一般常人正气的运行，是顺时针运行，这是无病的状态，医生必须知道什么健康状态，中医是健康专家，不像西医是疾病专家，病人如果得到肝病，去找西医的肝病专家，结果病人与医生都死在肝病。如果是病情在恶化，往内传，则是由太阳进入阳明或少阳；若进入阳明则不再传，停在阳明；若是进入少阳，则可能进入太阴、少阴、厥阴。学伤寒论必须学好条辨，伤寒论的条辨是“言简刚中”，中国的相书上讲到“言简刚中”的人是君子，是人才，讲话扼要有条理。张仲景就是一位“言简刚中”的人，也因为他的“言简刚中”，让很多人看不懂伤寒论。因此学完伤寒论的条辨以后，必须做整理，而我的工作，就是已经帮诸位做好整理的工作，不然学完伤寒论，就算整个背下来，没有整理的功夫，还是不会用</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":904000203}}', '2024-09-19T16:54:02.000Z', '2024-09-19T16:54:02.000Z', '2024-09-19T16:54:02.000Z', '在难经中有“五十八难曰：伤寒有几？其脉有变否？然：伤寒有五，有中风，有伤寒，有湿温，有热病，有温病，其所苦各不同。 ”伤寒这两字，就广义的定义来说，应该说是“伤于寒”。 以上五种病，广义地来说，都是伤于寒之后所引起的。另一种外感病我们称为时疫，也就是不管体质如何，男女老少感染时疫之后，都是同一种症状，所以我们可以分为伤寒、时疫这两类，在治病的时候，处方用药的思路略有不同。医圣张仲景为集经方之大成者，以内经热论中六经辨症的思路，很适当地将古人传下的经典汤方，用六经辨症的法则，来让后学者都能很精准地使用经方。 在讲六经之前，我们用一个图来给诸位一个概念，所谓的五运六气中的六气，在一天的十二个时辰，我们分为六气，$g{六气图} 如图所示： 如果是一般常人正气的运行，是顺时针运行，这是无病的状态，医生必须知道什么健康状态，中医是健康专家，不像西医是疾病专家，病人如果得到肝病，去找西医的肝病专家，结果病人与医生都死在肝病。如果是病情在恶化，往内传，则是由太阳进入阳明或少阳；若进入阳明则不再传，停在阳明；若是进入少阳，则可能进入太阴、少阴、厥阴。学伤寒论必须学好条辨，伤寒论的条辨是“言简刚中”，中国的相书上讲到“言简刚中”的人是君子，是人才，讲话扼要有条理。张仲景就是一位“言简刚中”的人，也因为他的“言简刚中”，让很多人看不懂伤寒论。因此学完伤寒论的条辨以后，必须做整理，而我的工作，就是已经帮诸位做好整理的工作，不然学完伤寒论，就算整个背下来，没有整理的功夫，还是不会用', '2024-09-19T16:54:02.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bhWEyfQihqy', 1, '{"title":"校勘序","description":"<p>  《伤寒杂病论》是一部阐述外感及其杂病治疗规律的专著。东汉末年张仲景撰于公元200-205。张仲景原著《伤寒杂病论》，在流传的过程中，经后人整理编纂将其中外感热病内容结集为《伤寒论》，另一部分主要是论述内科杂病的《金匮要略》 。《伤寒论》全书共 12卷，22 篇，397 法。除去重复之外共有药方 112 个。全书重点论述人体感受风寒之邪而引起的一系列病理变化及如何进行辩证施治的方法。他把病症分为太阳、阳明、少阳、太阴、少阴、厥阴六种，即所谓“六经”。根据人体抗病力的强弱，病势的进退缓急等方面的因素，将外感疾病演变过程中所表现的各种症候归纳出症候特点、病变部位、损及何脏何腑，以及寒热趋向、邪正盛衰等作为诊断治疗的依据。 </p>\n<p>      中华民族文化博大精深、渊远流长，中医更是中华民族的瑰宝，几千年来一直守护着炎黄子孙的健康。继承和发扬中医，本是我们与生俱来的使命。可是由于种种原因，使得中医的许多典籍在流传上产生问题：或已出版而校对欠佳，或印量稀少而极难购得，甚或已经绝版而失传。使得这份本应属于整个中华民族所共有共享的珍贵智慧，无法让更多需要的人学习他，大非往圣之本意！ 此《伤寒论》是由民间的中医爱好者搜集与校正，我们在校正的过程中，仅对明显的错别字给予了修改，对于无法确定者则保留原样。我们力图提供正确无误的电子版，但限于能力，自知错误在所难免。 </p>\n<p></p>\n<p>           $h{本书的原始材料来自于网络，为网络中善心人士传播之电子版本。本书的校正，属于无偿的自发行为，不收取任何费用，亦不得将本书内容用于商业行为。} </p>\n<p>           $m{根据相关法律，本电子书仅供网络测试，不收取任何费用。请您下载后 24 小时内删除， 如果您喜欢本书，请购买原版。任何人不得将本书用于商业行为，否则由此直接或间接引发的任何法律问题，我们不承担责任。} </p>\n<p>                                                                                                                                                                                                         民間中醫愛好者 敬校 </p>\n<p> </p>\n<p>                                                                                                                                                                                                          庚寅年 庚辰月 已未日</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040002}}', '2024-09-19T16:52:11.000Z', '2024-09-19T16:52:11.000Z', '2024-09-19T16:52:11.000Z', '《伤寒杂病论》是一部阐述外感及其杂病治疗规律的专著。东汉末年张仲景撰于公元200-205。张仲景原著《伤寒杂病论》，在流传的过程中，经后人整理编纂将其中外感热病内容结集为《伤寒论》，另一部分主要是论述内科杂病的《金匮要略》 。《伤寒论》全书共 12卷，22 篇，397 法。除去重复之外共有药方 112 个。全书重点论述人体感受风寒之邪而引起的一系列病理变化及如何进行辩证施治的方法。他把病症分为太阳、阳明、少阳、太阴、少阴、厥阴六种，即所谓“六经”。根据人体抗病力的强弱，病势的进退缓急等方面的因素，将外感疾病演变过程中所表现的各种症候归纳出症候特点、病变部位、损及何脏何腑，以及寒热趋向、邪正盛衰等作为诊断治疗的依据。 中华民族文化博大精深、渊远流长，中医更是中华民族的瑰宝，几千年来一直守护着炎黄子孙的健康。继承和发扬中医，本是我们与生俱来的使命。可是由于种种原因，使得中医的许多典籍在流传上产生问题：或已出版而校对欠佳，或印量稀少而极难购得，甚或已经绝版而失传。使得这份本应属于整个中华民族所共有共享的珍贵智慧，无法让更多需要的人学习他，大非往圣之本意！ 此《伤寒论》是由民间的中医爱好者搜集与校正，我们在校正的过程中，仅对明显的错别字给予了修改，对于无法确定者则保留原样。我们力图提供正确无误的电子版，但限于能力，自知错误在所难免。 $h{本书的原始材料来自于网络，为网络中善心人士传播之电子版本。本书的校正，属于无偿的自发行为，不收取任何费用，亦不得将本书内容用于商业行为。} $m{根据相关法律，本电子书仅供网络测试，不收取任何费用。请您下载后 24 小时内删除， 如果您喜欢本书，请购买原版。任何人不得将本书用于商业行为，否则由此直接或间接引发的任何法律问题，我们不承担责任。} 民間中醫愛好者 敬校 庚寅年 庚辰月 已未日', '2024-09-19T16:52:11.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sf2su7oyycM', 1, '{"title":"辨厥阴病脉证并治法","description":"<p>340、厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蚘，下之，利不止。  </p><p>341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也。  </p><p>342、厥阴病，欲解时，从丑至卯上。 </p><p>343、厥阴病，渴欲饮水者，少少与之，愈。</p><p>344、诸四逆厥者，不可下之，虚家亦然。</p><p>345、伤寒，先厥，后发热而利者，必自止，见厥复利。  </p><p>346、伤寒，始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中。食以素饼，微发热者，知胃气尚在，必愈；恐暴热来出而复去 也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。  </p><p>347、伤寒：脉迟，六七日，而反与$f{黄芩汤}彻其热。脉迟为寒，今与黄芩汤，腹中应冷，当不能食，今反能食，此为除中，必死。  </p><p>348、349、伤寒：先厥后发热，下利必自止。而反汗出，咽中痛者，其喉为痹，发热，无汗，利必自止。若不止，便脓血。便脓血，其喉不痹。  </p><p>350、伤寒，一二日，至四五日，前厥者，必发热；前热后厥者，必厥深热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。</p><p>351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。</p><p>352、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。  </p><p>353、354、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为藏厥，非若蛔厥也。蛔厥者，其人常自吐蛔。今病者静，而复时烦，此为蛔厥。蛔上入膈，故烦。须臾复止，得食而呕又烦者，蛔闻食臭出，其人当吐蛔也，蛔厥者，$f{乌梅丸}主之，又主久利。  </p><p>355、伤寒，热少，厥微，指头寒，默默不欲食，烦躁，数日小便利色白者，此热除也；欲得食，其病为愈；若厥多而呕，胸胁烦满者，其后必便血。</p><p>356、病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。  </p><p>357、伤寒发热四日，厥反三日，复热四日，厥少热多，其病当愈。四日至七日，热不除者，其后必便脓血。</p><p>358、伤寒厥四日，热反三日，复厥五日。其病为进；寒多热少，阳气退，故为进也。</p><p>359、伤寒六七日，脉微，手足厥冷，烦燥，灸厥阴，厥不还者，死。 </p><p>360、伤寒发热，下利，厥逆，躁不得卧者，死。</p><p>361、伤寒，发热，下利至甚，厥不止者，死。</p><p>362、伤寒，六七日下利，又发热，其人汗出不止者，死，有阴无阳故也。 </p><p>363、伤寒，五六日，不结胸，腹濡，脉虚，复厥者，不可下，此为亡血，下之死。</p><p>364、发热而厥，七日，下利者，为难治。</p><p>365、伤寒，脉促，手足厥逆者，可灸之。</p><p>366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之。</p><p>367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之。若其人内有久寒者，宜$f{当归四逆加吴茱萸生姜汤}主之。  </p><p>368、大汗出，热不去，四肢痛而拘急，又下利，厥逆而恶寒者，$f{四逆汤}主之。  </p><p>369、大汗，若大下利而厥冷者，$f{四逆汤}主之。</p><p>370、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜用$f{瓜蒂散}。  </p><p>371、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔，水渍入胃，必作利也。</p><p>382、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{麻黄升麻汤}主之。  </p><p>373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。  </p><p>374、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，$f{干姜黄连黄芩人参汤}主之。 </p><p>375、下利，有微热而渴，脉弱者，令自愈。  </p><p>376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解。  </p><p>377、下利，手足厥冷，无脉者，灸之不温，若脉不还，反微喘者，死。 </p><p>379、下利，寸脉反浮数，尺中自涩者，必圊脓血。（校正注：“圊”同“清”）</p><p>380、下利清谷，不可攻表，汗出，必胀满。</p><p>381、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。</p><p>382、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，病人必微厥。所以然者，其面戴阳，下虚故也。</p><p>383、下利，脉数而渴者，令自愈。设不差，必圊脓血，以有热故也。</p><p>384、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。</p><p>385、伤寒，下利日十余行，脉反实者，死。  </p><p>386、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。  </p><p>387、热利下重者，$f{白头翁汤治}之。</p><p>388、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。</p><p>389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。</p><p>390、下利，谵语者，有燥矢也，宜$f{大承气汤}。</p><p>391、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。  </p><p>392、呕家，有痈脓者，不可治呕，脓尽自愈。</p><p>393、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。</p><p>394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。</p><p>395、呕而发热者，$f{小柴胡汤}主之。  </p><p>396、伤寒，大吐大下之，极虚，以其人外气怫郁，发其汗，复极汗出者，复与之水，因得哕；所以然者，胃中寒冷故也。  </p><p>397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040011}}', '2024-12-02T03:54:43.000Z', '2024-12-02T03:54:43.000Z', '2024-12-02T03:54:43.000Z', '340、厥阴之为病，消渴，气上撞心，心中疼热，饥而不欲食，食则吐蚘，下之，利不止。 341、厥阴中风，脉微浮，为欲愈；不浮，为未愈也。 342、厥阴病，欲解时，从丑至卯上。 343、厥阴病，渴欲饮水者，少少与之，愈。 344、诸四逆厥者，不可下之，虚家亦然。 345、伤寒，先厥，后发热而利者，必自止，见厥复利。 346、伤寒，始发热六日，厥反九日而利；凡厥利者，当不能食，今反能食者，恐为除中。食以素饼，微发热者，知胃气尚在，必愈；恐暴热来出而复去 也。后三日脉之，其热续在者，期之旦日夜半愈。所以然者，本发热六日，厥反九日，复发热三日，并前六日，亦为九日，为厥相应，故期至旦日夜半愈。又三日脉之，而脉数，其热不罢者，此为热气有余，必发痈脓也。 347、伤寒：脉迟，六七日，而反与$f{黄芩汤}彻其热。脉迟为寒，今与黄芩汤，腹中应冷，当不能食，今反能食，此为除中，必死。 348、349、伤寒：先厥后发热，下利必自止。而反汗出，咽中痛者，其喉为痹，发热，无汗，利必自止。若不止，便脓血。便脓血，其喉不痹。 350、伤寒，一二日，至四五日，前厥者，必发热；前热后厥者，必厥深热亦深，厥微者热亦微。厥应下之，而反发汗者，必口伤烂赤。 351、伤寒病，厥五日，热亦五日，设六日当复厥，不厥者自愈。厥终不过五日，以热五日，故知自愈。 352、凡厥者，阴阳气不相顺接，便为厥。厥者，手足逆冷是也。 353、354、伤寒，脉微而厥，至七八日，肤冷，其人躁，无暂安时者，此为藏厥，非若蛔厥也。蛔厥者，其人常自吐蛔。今病者静，而复时烦，此为蛔厥。蛔上入膈，故烦。须臾复止，得食而呕又烦者，蛔闻食臭出，其人当吐蛔也，蛔厥者，$f{乌梅丸}主之，又主久利。 355、伤寒，热少，厥微，指头寒，默默不欲食，烦躁，数日小便利色白者，此热除也；欲得食，其病为愈；若厥多而呕，胸胁烦满者，其后必便血。 356、病者手足厥冷，言我不结胸，小腹满，按之痛者，此冷结在膀胱关元也。 357、伤寒发热四日，厥反三日，复热四日，厥少热多，其病当愈。四日至七日，热不除者，其后必便脓血。 358、伤寒厥四日，热反三日，复厥五日。其病为进；寒多热少，阳气退，故为进也。 359、伤寒六七日，脉微，手足厥冷，烦燥，灸厥阴，厥不还者，死。 360、伤寒发热，下利，厥逆，躁不得卧者，死。 361、伤寒，发热，下利至甚，厥不止者，死。 362、伤寒，六七日下利，又发热，其人汗出不止者，死，有阴无阳故也。 363、伤寒，五六日，不结胸，腹濡，脉虚，复厥者，不可下，此为亡血，下之死。 364、发热而厥，七日，下利者，为难治。 365、伤寒，脉促，手足厥逆者，可灸之。 366、伤寒脉滑而厥者，里有热也，$f{白虎汤}主之。 367、手足厥寒，脉细欲绝者，$f{当归四逆汤}主之。若其人内有久寒者，宜$f{当归四逆加吴茱萸生姜汤}主之。 368、大汗出，热不去，四肢痛而拘急，又下利，厥逆而恶寒者，$f{四逆汤}主之。 369、大汗，若大下利而厥冷者，$f{四逆汤}主之。 370、病人手足厥冷，脉乍紧者，邪结在胸中，心下满而烦，饥不能食者，病在胸中，当须吐之，宜用$f{瓜蒂散}。 371、伤寒，厥而心下悸者，宜先治水，当服$f{茯苓甘草汤}，却治其厥，不尔，水渍入胃，必作利也。 382、伤寒六七日，大下后，寸脉沉而迟，手足厥逆，下部脉不至，咽喉不利，唾脓血，泄利不止者，为难治，$f{麻黄升麻汤}主之。 373、伤寒四五日，腹中痛，若转气下趋少腹者，此欲自利也。 374、伤寒，本自寒下，医复吐、下之，寒格，更逆吐、下，若食入口即吐者，$f{干姜黄连黄芩人参汤}主之。 375、下利，有微热而渴，脉弱者，令自愈。 376、下利，脉缓，有微热，汗出，令自愈；设复紧，为末解。 377、下利，手足厥冷，无脉者，灸之不温，若脉不还，反微喘者，死。 379、下利，寸脉反浮数，尺中自涩者，必圊脓血。（校正注：“圊”同“清”） 380、下利清谷，不可攻表，汗出，必胀满。 381、下利，脉沉弦者，下重也；脉大者，为未止；脉微弱数者，为欲自止，虽发热，不死。 382、下利，脉沉而迟，其人面少赤，身有微热，下利清谷者，病人必微厥。所以然者，其面戴阳，下虚故也。 383、下利，脉数而渴者，令自愈。设不差，必圊脓血，以有热故也。 384、下利后，脉绝，手足厥冷，晬时脉还，手足温者生，脉不还者死。 385、伤寒，下利日十余行，脉反实者，死。 386、下利清谷，里寒外热，汗出而厥者，$f{通脉四逆汤}主之。 387、热利下重者，$f{白头翁汤治}之。 388、下利，腹胀满，身体疼痛者，先温其里，乃攻其表，温里宜$f{四逆汤}，攻表宜$f{桂枝汤}。 389、下利，欲饮水者，以有热故也，$f{白头翁汤}主之。 390、下利，谵语者，有燥矢也，宜$f{大承气汤}。 391、下利后，更烦，按之心下濡者，为虚烦也，宜$f{栀子豉汤}。 392、呕家，有痈脓者，不可治呕，脓尽自愈。 393、呕而脉弱，小便复利，身有微热，见厥者，难治，$f{四逆汤}主之。 394、干呕，吐涎沫，头痛者，$f{吴茱萸汤}主之。 395、呕而发热者，$f{小柴胡汤}主之。 396、伤寒，大吐大下之，极虚，以其人外气怫郁，发其汗，复极汗出者，复与之水，因得哕；所以然者，胃中寒冷故也。 397、伤寒，哕而腹满，视其前后，知何部不利，利之即愈。', '2024-12-02T03:54:43.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pD4dX7H9D4M', 1, '{"title":"辨太阳病脉证并治法上篇","description":"<p>1、太阳之为病，脉浮，头项强痛而恶寒。  </p><p>2、太阳病发热，汗出，恶风，脉缓者，名为中风。</p><p>3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名 曰伤寒。  </p><p>4、伤寒一日，太阳受之，脉静者，为不传也;若脉数急者，为传也。</p><p>5、伤寒二三日，阳明、少阳证不见者，为不传也；颇欲吐，若烦躁者，为传也。</p><p>6、太阳病，发热而渴，不恶寒者，为温病。  </p><p>7、若自汗出，身灼热者，名曰风温。  </p><p>8、风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，息必鼾，言语难出。若发汗者，小便不利；若被下者，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘈疭；若火蒸之，一逆尚引日，再逆促命期。</p><p>9、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七、阴数六故也。 </p><p>10、太阳病，头痛，至七日以上自愈者，以行其经尽故也；若欲作再经者，针足阳明，使经不传则愈。</p><p>11、太阳病欲解时，从巳至未上。  </p><p>12、中风表解而不了了者，十二日愈。 </p><p>13、病人身大热，反欲近衣者，热在皮肤，寒在骨髓也。</p>\n<p>14、身大寒，反不 欲近衣者，寒在皮肤，热在骨髓也。  </p><p>15、太阳中风，阳浮而阴弱，阳浮者热自发，阴弱者汗自出，啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣，干呕者，$f{桂枝汤}主之。</p><p>16、太阳病，头痛，发热，汗出，恶风者，桂枝汤主之。</p><p>17、太阳病，项背强几几，及汗出，恶风者，$f{桂枝加葛根汤}主之。</p><p>18、太阳病，下之后，其气上冲者，可与$f{桂枝汤}，用前法；若不上冲者，不可与之。</p><p>19、太阳病，三日，已发汗，若吐、若下、若温针，仍不解者，此为坏病，桂枝不中与也。视其脉证，知犯何逆，随证治之。</p><p>20、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常需识此，勿令误也。</p><p>21、若酒客病，不可与$f{桂枝汤}；得汤则呕，以酒客不喜甘故也。  </p><p>22、若喘家作，桂枝汤加厚朴、杏子仁。 $f{桂枝加厚朴杏仁汤}</p><p>23、凡吐家，服$f{桂枝汤}，其后必吐脓血也。</p><p>24、太阳病，发汗、遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，$f{桂枝加附子汤}主之。</p><p>25、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。若微恶寒者，桂枝去芍药方中加附子汤主之。 $f{桂枝去芍药加附子汤}</p><p>26、太阳病，得之八九日，如疟状；发热、恶寒、热多、寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可 更发汗，更下，更吐也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。</p><p>27、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风池、风府，却与$f{桂枝汤}则愈。</p><p>28、服$f{桂枝汤}，不汗出，脉洪大者，与$f{桂枝汤}如前法，若形如疟，日再发者，汗出必解，宜$f{桂枝二麻黄一汤}。</p><p>29、服$f{桂枝汤}，大汗出后，大烦渴不解，脉洪大者，$f{白虎加人参汤}主之。</p><p>30、太阳病，发热恶寒，热多寒少，烦躁，脉微弱者。此无阳也，不可发汗，宜$f{桂枝二越婢一汤}主之。 </p><p>31、服$f{桂枝汤}，或下之，仍头项强痛。翕翕发热、无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。</p><p>32、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，反与$f{桂枝汤}以攻其表，此误也，得之便厥，咽中干，烦躁，吐逆，谵语，脚挛急，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚得伸。若胃气不和，谵语者，少与$f{调胃承气汤}。</p><p>33、若重发汗，复加烧针者，$f{四逆汤}主之。</p><p>34、问曰：证象阳旦，按法治之而增剧，厥逆，咽中干，项胫拘急而谵语。师言夜半手足当温。两脚当伸。后如师言，何以知此?  </p>\n<p></p>\n<p>       答曰：寸口脉浮而大，浮则为风，大则为虚，风则生温热，虚则两胫挛，病证象桂枝；因未加附子参其间，增桂令汗出亡阳故也，厥逆，咽中干，烦躁，阳明内结，谵语烦乱，更饮$f{甘草干姜汤}，夜半阳气还，两足当温，胫尚微拘急， 重与$f{芍药甘草汤}，尔乃胫伸，以承气汤微溏，则止其谵语，故病可愈。  </p><p>35、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。</p><p>36、太阳与阳明合病，必自下利，$f{葛根汤}主之。 </p><p>37、太阳与阳明合病，不但下利，而呕者，$f{葛根加半夏汤}主之。 </p><p>38、太阳病桂枝证，医反下之。利遂不止，脉促，喘而汗出者，表未解也，$f{葛根黄芩黄连汤}主之。 </p><p>39、太阳病，头痛，发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。</p><p>40、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。  </p><p>41、太阳病，十日已去，脉浮细而嗜卧者，外已解也。设胸满，胁痛者，与$f{小柴胡汤}，脉但浮者与$f{麻黄汤}。</p><p>42、太阳伤寒，脉浮紧，发热，恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。</p>\n<p>43、若脉微弱，汗出，恶风者，不可服之；服之则厥逆，筋惕肉润，此为逆也。</p><p>44、伤寒，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}主之。</p><p>45、伤寒，表不解，心下有水气，干呕，发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。  </p><p>46、伤寒，心下有水气，咳而微喘，发热不渴，$f{小青龙汤}主之。服汤已，渴者，此寒去欲解也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040004}}', '2024-09-19T16:56:22.000Z', '2024-09-19T16:56:22.000Z', '2024-09-19T16:56:22.000Z', '1、太阳之为病，脉浮，头项强痛而恶寒。 2、太阳病发热，汗出，恶风，脉缓者，名为中风。 3、太阳病，或已发热，或未发热，必恶寒，体痛，呕逆，脉阴阳俱紧者，名 曰伤寒。 4、伤寒一日，太阳受之，脉静者，为不传也;若脉数急者，为传也。 5、伤寒二三日，阳明、少阳证不见者，为不传也；颇欲吐，若烦躁者，为传也。 6、太阳病，发热而渴，不恶寒者，为温病。 7、若自汗出，身灼热者，名曰风温。 8、风温为病，脉阴阳俱浮，自汗出，身重，多眠睡，息必鼾，言语难出。若发汗者，小便不利；若被下者，直视，失溲；若被火者，微发黄色，剧则如惊痫，时瘈疭；若火蒸之，一逆尚引日，再逆促命期。 9、病有发热恶寒者，发于阳也；无热恶寒者，发于阴也。发于阳者七日愈，发于阴者六日愈，以阳数七、阴数六故也。 10、太阳病，头痛，至七日以上自愈者，以行其经尽故也；若欲作再经者，针足阳明，使经不传则愈。 11、太阳病欲解时，从巳至未上。 12、中风表解而不了了者，十二日愈。 13、病人身大热，反欲近衣者，热在皮肤，寒在骨髓也。 14、身大寒，反不 欲近衣者，寒在皮肤，热在骨髓也。 15、太阳中风，阳浮而阴弱，阳浮者热自发，阴弱者汗自出，啬啬恶寒，淅淅恶风，翕翕发热，鼻鸣，干呕者，$f{桂枝汤}主之。 16、太阳病，头痛，发热，汗出，恶风者，桂枝汤主之。 17、太阳病，项背强几几，及汗出，恶风者，$f{桂枝加葛根汤}主之。 18、太阳病，下之后，其气上冲者，可与$f{桂枝汤}，用前法；若不上冲者，不可与之。 19、太阳病，三日，已发汗，若吐、若下、若温针，仍不解者，此为坏病，桂枝不中与也。视其脉证，知犯何逆，随证治之。 20、$f{桂枝汤}本为解肌，若其人脉浮紧，发热，汗不出者，不可与也。常需识此，勿令误也。 21、若酒客病，不可与$f{桂枝汤}；得汤则呕，以酒客不喜甘故也。 22、若喘家作，桂枝汤加厚朴、杏子仁。 $f{桂枝加厚朴杏仁汤} 23、凡吐家，服$f{桂枝汤}，其后必吐脓血也。 24、太阳病，发汗、遂漏不止，其人恶风，小便难，四肢微急，难以屈伸者，$f{桂枝加附子汤}主之。 25、太阳病，下之后，脉促，胸满者，$f{桂枝去芍药汤}主之。若微恶寒者，桂枝去芍药方中加附子汤主之。 $f{桂枝去芍药加附子汤} 26、太阳病，得之八九日，如疟状；发热、恶寒、热多、寒少，其人不呕，清便欲自可，一日二三度发。脉微缓者，为欲愈也；脉微而恶寒者，此阴阳俱虚，不可 更发汗，更下，更吐也。面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜$f{桂枝麻黄各半汤}。 27、太阳病，初服$f{桂枝汤}，反烦不解者，先刺风池、风府，却与$f{桂枝汤}则愈。 28、服$f{桂枝汤}，不汗出，脉洪大者，与$f{桂枝汤}如前法，若形如疟，日再发者，汗出必解，宜$f{桂枝二麻黄一汤}。 29、服$f{桂枝汤}，大汗出后，大烦渴不解，脉洪大者，$f{白虎加人参汤}主之。 30、太阳病，发热恶寒，热多寒少，烦躁，脉微弱者。此无阳也，不可发汗，宜$f{桂枝二越婢一汤}主之。 31、服$f{桂枝汤}，或下之，仍头项强痛。翕翕发热、无汗，心下满，微痛，小便不利者，$f{桂枝去桂加茯苓白术汤}主之。 32、伤寒，脉浮，自汗出，小便数，心烦，微恶寒，反与$f{桂枝汤}以攻其表，此误也，得之便厥，咽中干，烦躁，吐逆，谵语，脚挛急，作$f{甘草干姜汤}与之，以复其阳。若厥愈，足温者，更作$f{芍药甘草汤}与之，其脚得伸。若胃气不和，谵语者，少与$f{调胃承气汤}。 33、若重发汗，复加烧针者，$f{四逆汤}主之。 34、问曰：证象阳旦，按法治之而增剧，厥逆，咽中干，项胫拘急而谵语。师言夜半手足当温。两脚当伸。后如师言，何以知此? 答曰：寸口脉浮而大，浮则为风，大则为虚，风则生温热，虚则两胫挛，病证象桂枝；因未加附子参其间，增桂令汗出亡阳故也，厥逆，咽中干，烦躁，阳明内结，谵语烦乱，更饮$f{甘草干姜汤}，夜半阳气还，两足当温，胫尚微拘急， 重与$f{芍药甘草汤}，尔乃胫伸，以承气汤微溏，则止其谵语，故病可愈。 35、太阳病，项背强几几，无汗，恶风者，$f{葛根汤}主之。 36、太阳与阳明合病，必自下利，$f{葛根汤}主之。 37、太阳与阳明合病，不但下利，而呕者，$f{葛根加半夏汤}主之。 38、太阳病桂枝证，医反下之。利遂不止，脉促，喘而汗出者，表未解也，$f{葛根黄芩黄连汤}主之。 39、太阳病，头痛，发热，身疼，腰痛，骨节疼痛，恶风，无汗而喘者，$f{麻黄汤}主之。 40、太阳与阳明合病，喘而胸满者，不可下，宜$f{麻黄汤}。 41、太阳病，十日已去，脉浮细而嗜卧者，外已解也。设胸满，胁痛者，与$f{小柴胡汤}，脉但浮者与$f{麻黄汤}。 42、太阳伤寒，脉浮紧，发热，恶寒，身疼痛，不汗出而烦躁者，$f{大青龙汤}主之。 43、若脉微弱，汗出，恶风者，不可服之；服之则厥逆，筋惕肉润，此为逆也。 44、伤寒，脉浮缓，身不疼，但重，乍有轻时，无少阴证者，$f{大青龙汤}主之。 45、伤寒，表不解，心下有水气，干呕，发热而咳，或渴，或利，或噎，或小便不利，少腹满，或喘者，$f{小青龙汤}主之。 46、伤寒，心下有水气，咳而微喘，发热不渴，$f{小青龙汤}主之。服汤已，渴者，此寒去欲解也。', '2024-09-19T16:56:22.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4MZUJIjIs6y', 1, '{"title":"辨太阳病脉证并治法下篇","description":"<p>134、太阳病，当恶寒发热，今自汗出，不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，以医吐之所致也，此为小逆。  </p><p>135、太阳病，吐之，但太阳病当恶寒，今反不恶寒，不欲近衣者。此为吐之内烦也。  </p><p>136、病人脉数，数为热，当消谷引食，而反吐者，此以发汗，令阳气微，胃气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。</p><p>137、太阳病，过经十余日，心中温温，欲吐，而胸中痛，大便反溏，腹微满，郁郁微烦，先此时，自欲极吐下者，与$f{调胃承气汤}；若不尔者，不可与；但欲呕，胸中痛，微溏者，此非柴胡证，以呕极吐下，故知也。</p><p>138、太阳病，六七日表证乃在，下之，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。  </p><p>139、太阳病，身黄，脉沉结，少腹鞕，小便不利者，为无血也；小便自利者，其人如狂者，血证谛也，抵$f{当汤主}之。  </p><p>140、伤寒，有热，少腹满，应小便不利，今反利者，为有血也，当下之。不可余药，宜$f{抵当丸}。  </p><p>141、太阳病，以饮水多，小便利者，必心下悸；小便少者，必苦里急也。  </p><p>142、问曰：病有结胸，有藏结，其状何如?</p>\n<p>         答曰：按之痛，寸脉浮，关脉沉，名曰结胸也。</p>\n<p>         何谓藏结? </p>\n<p>         答曰：如「结胸」状,饮食如故,时时下利,寸脉浮,关脉小细沉紧,名曰「藏结」；舌上白苔滑者,难治。</p><p>143、藏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也。  </p><p>144、病发于阳，而反下之，热入，因作结胸。病发于阴，而反下之，因作痞。所以成结胸者，以下之太早故也。</p><p>145、结胸者，项亦强，如柔痉状，下之则和，宜$f{大陷胸丸}。  </p><p>146、结胸证，其脉浮大者，不可下，下之则死。</p><p>147、结胸证悉具，烦躁者，亦死。</p><p>148、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，而微汗出，及恶寒者，表未解也，医反下之，动数变迟，客气动膈，膈内拒痛， 短气躁烦，心中懊憹，胃中空虚，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄也。  </p><p>149、伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石鞕者，${大陷胸汤}主之。</p><p>150、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。但结胸无大热者，此与水结在胸胁也，但头微汗出者，$f{大陷胸汤}主之。  </p><p>151、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日哺所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。</p><p>152、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。  </p><p>153、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，本有久寒也，反下之，若利之，必作结胸；未止者，四日复下之，此作协热利也。</p><p>154、太阳病，下之，其脉浮，不结胸者，此为欲解也；脉促者，必结胸也；脉细数者，必咽痛；脉弦者，必两胁拘急；脉紧者，头痛未止，脉沉紧者，必心下痛；脉沉滑者，协热利；脉数滑者，必下血。  </p><p>155、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，$g{肉上粟起}，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。  </p><p>156、寒实结胸，无热证者，与$f{三物小白散}，陷胸汤不可服。  </p><p>157、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗。发汗则谵语，脉弦，五六日谵语不止，当刺期门。  </p><p>158、妇人中风，发热恶寒，得之八九日，经水迟来，热除而脉迟身凉，胸胁下满。如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泻之。</p><p>159、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。</p><p>160、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上下焦，必自愈。</p><p>161、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。 </p><p>162、伤寒五六日，已发汗而复下之。胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。</p><p>163、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉沉细者，此为阳微结，必有表复有里也，脉沉细，病在里也；头汗出，病在表也，假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也；脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴；可与$f{小柴胡汤}，设不了了者，得屎而解。  </p><p>164、伤寒五六日，呕而发热者，柴胡汤证具，而以他药下之，柴胡证仍在者，复与柴胡汤，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解；若心下满而硬痛者，此为结胸也，$f{大陷胸汤}主之；但满而不痛者，此为痞，柴胡不中与也，宜$f{半夏泻心汤}。 </p><p>165、太阳少阳并病，而反下之，成结胸，心下硬，下利不止，水浆不下，其人心烦。</p><p>166、脉浮而紧，而复下之，病反入里，则作痞，按之则自濡，但气痞耳。  </p><p>167、太阳中风，下利，呕逆，表解者，乃可攻之。其人漐漐汗出，发作有时，头痛，心下痞鞕满，引胁下痛，呕即短气，汗出不恶寒者，此表解里未和 也，$f{十枣汤}主之。 </p><p>168、太阳病，发热恶寒，医发汗，无阳而阴独，因复下之，遂心下痞，表里俱虚，阴阳气并竭，复加烧针，因胸烦，面色青黄，肤润者，难治，今色微黄，手足温者，易愈。  </p><p>169、心下痞，按之濡，其脉关上浮者，$f{大黄黄连泻心汤}主之。  </p><p>170、心下痞，而复恶寒，汗出者，$f{附子泻心汤}主之。  </p><p>171、表以下之，故心下痞，与泻心汤。痞不解，其人口中渴，而烦躁，小便不利者，$f{五苓散}主之。  </p><p>172、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。</p><p>173、伤寒、中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非热结，但以胃中虚，客气上结，故使鞕也，$f{甘草泻心汤}主之。  </p><p>174、伤寒，服汤药，下利不止，心下痞鞕服泻心汤已，复以他药下之，利不止，医以理中与之，利益甚；理中者，理中焦，此利在下焦，$f{赤石脂禹余粮汤}主之，复利不止者，当利其小便。  </p><p>175、伤寒八九日，吐下后，虚烦，心下痞鞕，胁下痛，气上冲咽喉，眩冒，复发汗，脉甚微，经脉动惕者，久而成痿。</p><p>176、伤寒，发汗，若吐，若下，解后心下痞鞕，噫气不除者，$f{旋覆代赭石汤}主之。</p><p>177、下后，不可更行$f{桂枝汤}；若汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}。 </p><p>178、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕， 表里不解者，$f{桂枝人参汤}主之。</p><p>179、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，表解乃可攻痞，解表宜$f{桂枝汤}，攻痞宜$f{大黄黄连泻心汤}。  </p><p>180、伤寒，发热、汗出不解，心下痞鞕，呕吐而下利者，$f{大柴胡汤}主之。 </p><p>181、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上冲咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。  </p><p>182、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此为藏结，死。</p><p>183、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时汗，恶风，大渴而烦，舌上干燥，欲饮水数升者，$f{白虎加人参汤}主之。  </p><p>184、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。</p><p>185、伤寒，脉浮，发热，无汗。其表不解者，不可与白虎汤。渴欲饮水，无表证者，$f{白虎加人参汤}主之。  </p><p>186、太阳少阳并病。心下鞕，头项强而眩者，当刺大椎、肺俞、肝俞，慎勿下之。</p><p>187、太阳与少阳合病，自下利者，与$f{黄芩汤}；若呕者，$f{黄芩加半夏生姜汤}主之。</p><p>188、伤寒，胸中有热，胃下有邪气，腹中痛，欲呕吐者，$f{黄连汤}主之。 </p><p>189、伤寒，八九日，风湿相搏，身体烦疼，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若其大便溏，小便自利者，$f{去桂加白术汤}主之。  </p><p>190、风湿相搏，骨节烦疼，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风不欲去衣被，或身微肿者，$f{甘草附子汤}主之。  </p><p>191、伤寒脉浮滑，此表有寒，里有热，$f{白虎汤}主之。  </p><p>192、伤寒，脉结代，心动悸，$f{炙甘草汤}主之。  </p><p>193、脉，按之来缓，而时一止复来者，名曰结，阴也。又脉来数，而中止更来，及小数中止能自还者，名曰促，阳也。脉来缓，而中止不能自还，因而复动者，名曰代，阴也；得此脉者，必难治。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040006}}', '2024-11-25T06:26:17.000Z', '2024-11-25T06:26:17.000Z', '2024-11-25T06:26:17.000Z', '134、太阳病，当恶寒发热，今自汗出，不恶寒发热，关上脉细数者，以医吐之过也。一二日吐之者，腹中饥，口不能食；三四日吐之者，不喜糜粥，欲食冷食，朝食暮吐，以医吐之所致也，此为小逆。 135、太阳病，吐之，但太阳病当恶寒，今反不恶寒，不欲近衣者。此为吐之内烦也。 136、病人脉数，数为热，当消谷引食，而反吐者，此以发汗，令阳气微，胃气虚，脉乃数也。数为客热，不能消谷，以胃中虚冷，故吐也。 137、太阳病，过经十余日，心中温温，欲吐，而胸中痛，大便反溏，腹微满，郁郁微烦，先此时，自欲极吐下者，与$f{调胃承气汤}；若不尔者，不可与；但欲呕，胸中痛，微溏者，此非柴胡证，以呕极吐下，故知也。 138、太阳病，六七日表证乃在，下之，脉微而沉，反不结胸，其人发狂者，以热在下焦，少腹当鞕满，小便自利者，下血乃愈。所以然者，以太阳随经，瘀热在里故也。$f{抵当汤}主之。 139、太阳病，身黄，脉沉结，少腹鞕，小便不利者，为无血也；小便自利者，其人如狂者，血证谛也，抵$f{当汤主}之。 140、伤寒，有热，少腹满，应小便不利，今反利者，为有血也，当下之。不可余药，宜$f{抵当丸}。 141、太阳病，以饮水多，小便利者，必心下悸；小便少者，必苦里急也。 142、问曰：病有结胸，有藏结，其状何如? 答曰：按之痛，寸脉浮，关脉沉，名曰结胸也。 何谓藏结? 答曰：如「结胸」状,饮食如故,时时下利,寸脉浮,关脉小细沉紧,名曰「藏结」；舌上白苔滑者,难治。 143、藏结，无阳证，不往来寒热，其人反静，舌上苔滑者，不可攻也。 144、病发于阳，而反下之，热入，因作结胸。病发于阴，而反下之，因作痞。所以成结胸者，以下之太早故也。 145、结胸者，项亦强，如柔痉状，下之则和，宜$f{大陷胸丸}。 146、结胸证，其脉浮大者，不可下，下之则死。 147、结胸证悉具，烦躁者，亦死。 148、太阳病，脉浮而动数，浮则为风，数则为热，动则为痛，头痛发热，而微汗出，及恶寒者，表未解也，医反下之，动数变迟，客气动膈，膈内拒痛， 短气躁烦，心中懊憹，胃中空虚，阳气内陷，心下因鞕，则为结胸，$f{大陷胸汤}主之。若不结胸，但头汗出，余处无汗，剂颈而还，小便不利，身必发黄也。 149、伤寒六七日，结胸热实，脉沉而紧，心下痛，按之石鞕者，${大陷胸汤}主之。 150、伤寒十余日，热结在里，复往来寒热者，与$f{大柴胡汤}。但结胸无大热者，此与水结在胸胁也，但头微汗出者，$f{大陷胸汤}主之。 151、太阳病，重发汗，而复下之，不大便五六日，舌上燥而渴，日哺所小有潮热，从心下至少腹鞕满而痛不可近者，$f{大陷胸汤}主之。 152、小结胸病，正在心下，按之则痛，脉浮滑者，$f{小陷胸汤}主之。 153、太阳病，二三日，不能卧，但欲起，心下必结，脉微弱者，本有久寒也，反下之，若利之，必作结胸；未止者，四日复下之，此作协热利也。 154、太阳病，下之，其脉浮，不结胸者，此为欲解也；脉促者，必结胸也；脉细数者，必咽痛；脉弦者，必两胁拘急；脉紧者，头痛未止，脉沉紧者，必心下痛；脉沉滑者，协热利；脉数滑者，必下血。 155、病在阳，应以汗解之，反以冷水潠之，若灌之，其热被劫不得去，弥更益烦，$g{肉上粟起}，意欲饮水，反不渴者，服$f{文蛤散}；若不差者，与$f{五苓散}。 156、寒实结胸，无热证者，与$f{三物小白散}，陷胸汤不可服。 157、太阳与少阳并病，头项强痛，或眩冒，时如结胸，心下痞鞕者，当刺大椎第一间、肺俞、肝俞，慎不可发汗。发汗则谵语，脉弦，五六日谵语不止，当刺期门。 158、妇人中风，发热恶寒，得之八九日，经水迟来，热除而脉迟身凉，胸胁下满。如结胸状，谵语者，此为热入血室也，当刺期门，随其实而泻之。 159、妇人中风，七八日，续得寒热，发作有时，经水适断者，此为热入血室，其血必结，故使如疟状，发作有时，$f{小柴胡汤}主之。 160、妇人伤寒发热，经水适来，昼日明了，暮则谵语，如见鬼状者，此为热入血室，无犯胃气及上下焦，必自愈。 161、伤寒六七日，发热微恶寒，支节烦疼，微呕，心下支结，外证未去者，$f{柴胡桂枝汤}主之。 162、伤寒五六日，已发汗而复下之。胸胁满，微结，小便不利，渴而不呕，但头汗出，往来寒热，心烦者，此为未解也，$f{柴胡桂枝干姜汤}主之。 163、伤寒五六日，头汗出，微恶寒，手足冷，心下满，口不欲食，大便鞕，脉沉细者，此为阳微结，必有表复有里也，脉沉细，病在里也；头汗出，病在表也，假令纯阴结，不得复有外证，悉入在里，此为半在里半在外也；脉虽沉细，不得为少阴病，所以然者，阴不得有汗，今头汗出，故知非少阴；可与$f{小柴胡汤}，设不了了者，得屎而解。 164、伤寒五六日，呕而发热者，柴胡汤证具，而以他药下之，柴胡证仍在者，复与柴胡汤，此虽已下之，不为逆，必蒸蒸而振，却发热汗出而解；若心下满而硬痛者，此为结胸也，$f{大陷胸汤}主之；但满而不痛者，此为痞，柴胡不中与也，宜$f{半夏泻心汤}。 165、太阳少阳并病，而反下之，成结胸，心下硬，下利不止，水浆不下，其人心烦。 166、脉浮而紧，而复下之，病反入里，则作痞，按之则自濡，但气痞耳。 167、太阳中风，下利，呕逆，表解者，乃可攻之。其人漐漐汗出，发作有时，头痛，心下痞鞕满，引胁下痛，呕即短气，汗出不恶寒者，此表解里未和 也，$f{十枣汤}主之。 168、太阳病，发热恶寒，医发汗，无阳而阴独，因复下之，遂心下痞，表里俱虚，阴阳气并竭，复加烧针，因胸烦，面色青黄，肤润者，难治，今色微黄，手足温者，易愈。 169、心下痞，按之濡，其脉关上浮者，$f{大黄黄连泻心汤}主之。 170、心下痞，而复恶寒，汗出者，$f{附子泻心汤}主之。 171、表以下之，故心下痞，与泻心汤。痞不解，其人口中渴，而烦躁，小便不利者，$f{五苓散}主之。 172、伤寒，汗出，解之后，胃中不和，心下痞鞕，干噫食臭，胁下有水气，腹中雷鸣，下利者，$f{生姜泻心汤}主之。 173、伤寒、中风，医反下之，其人下利，日数十行，谷不化，腹中雷鸣，心下痞鞕而满，干呕，心烦不得安，医见心下痞，谓病不尽，复下之，其痞益甚，此非热结，但以胃中虚，客气上结，故使鞕也，$f{甘草泻心汤}主之。 174、伤寒，服汤药，下利不止，心下痞鞕服泻心汤已，复以他药下之，利不止，医以理中与之，利益甚；理中者，理中焦，此利在下焦，$f{赤石脂禹余粮汤}主之，复利不止者，当利其小便。 175、伤寒八九日，吐下后，虚烦，心下痞鞕，胁下痛，气上冲咽喉，眩冒，复发汗，脉甚微，经脉动惕者，久而成痿。 176、伤寒，发汗，若吐，若下，解后心下痞鞕，噫气不除者，$f{旋覆代赭石汤}主之。 177、下后，不可更行$f{桂枝汤}；若汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}。 178、太阳病，外证未除，而数下之，遂协热而利，利下不止，心下痞鞕， 表里不解者，$f{桂枝人参汤}主之。 179、伤寒，大下后，复发汗，心下痞，恶寒者，表未解也，不可攻痞，当先解表，表解乃可攻痞，解表宜$f{桂枝汤}，攻痞宜$f{大黄黄连泻心汤}。 180、伤寒，发热、汗出不解，心下痞鞕，呕吐而下利者，$f{大柴胡汤}主之。 181、病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞鞕，气上冲咽喉，不得息者，此为胸有寒也，当吐之，宜$f{瓜蒂散}。 182、病胁下素有痞，连在脐旁，痛引少腹，入阴筋者，此为藏结，死。 183、伤寒，若吐，若下后，七八日不解，热结在里，表里俱热，时汗，恶风，大渴而烦，舌上干燥，欲饮水数升者，$f{白虎加人参汤}主之。 184、伤寒，无大热，口燥渴，心烦，背微恶寒者，$f{白虎加人参汤}主之。 185、伤寒，脉浮，发热，无汗。其表不解者，不可与白虎汤。渴欲饮水，无表证者，$f{白虎加人参汤}主之。 186、太阳少阳并病。心下鞕，头项强而眩者，当刺大椎、肺俞、肝俞，慎勿下之。 187、太阳与少阳合病，自下利者，与$f{黄芩汤}；若呕者，$f{黄芩加半夏生姜汤}主之。 188、伤寒，胸中有热，胃下有邪气，腹中痛，欲呕吐者，$f{黄连汤}主之。 189、伤寒，八九日，风湿相搏，身体烦疼，不能自转侧，不呕，不渴，脉浮虚而涩者，$f{桂枝附子汤}主之；若其大便溏，小便自利者，$f{去桂加白术汤}主之。 190、风湿相搏，骨节烦疼，掣痛，不得屈伸，近之则痛剧，汗出，短气，小便不利，恶风不欲去衣被，或身微肿者，$f{甘草附子汤}主之。 191、伤寒脉浮滑，此表有寒，里有热，$f{白虎汤}主之。 192、伤寒，脉结代，心动悸，$f{炙甘草汤}主之。 193、脉，按之来缓，而时一止复来者，名曰结，阴也。又脉来数，而中止更来，及小数中止能自还者，名曰促，阳也。脉来缓，而中止不能自还，因而复动者，名曰代，阴也；得此脉者，必难治。', '2024-11-25T06:26:17.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1NZBr3pAx9S', 1, '{"title":"辨太阳病脉证并治法中篇","description":"<p>47、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。  </p><p>48、太阳病，下之微喘者，表未解故也，$f{桂枝加厚朴杏仁汤}主之。</p><p>49、太阳病外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}主之。  </p><p>50、太阳病先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，须当解外则愈，宜$f{桂枝汤}主之。</p><p>51、太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在，此当发其汗。$f{麻黄汤}主之。服药已，微除，其人发烦，目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。</p><p>52、太阳病，脉浮紧，发热，身无汗，自衄者愈。</p><p>53、二阳并病，太阳初得病时，发其汗。汗先出不澈，因转属阳明。续自微汗出，不恶寒，若太阳病证不罢者，不可下，下之为逆。如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之。若发汗不澈，不足言阳气怫郁不得 越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也，更发汗则愈。何以知汗岀不澈，脉涩，故知也。</p><p>54、脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。 </p><p>55、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知其然？以营气不足，血少故也。</p><p>56、脉浮者，病在表，可发汗，宜$f{麻黄汤}。</p><p>57、脉浮数者，可发汗，宜$麻黄汤}。</p><p>58、病常自汗出者，此为营气和。营气和者，外不谐，以卫气不共营气和谐故尔。以营行脉中，卫行脉外，复发其汗，营卫和则愈，宜$f{桂枝汤}。</p><p>59、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}主之。</p><p>60、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。</p><p>61、伤寒，不大便六、七日，头痛有热者，与承气汤。其小便清者，知不在里，仍在表也，当须发汗。若头痛者，必衄，宜$f{桂枝汤}。</p><p>62、伤寒，发汗，解半日许，复烦，脉浮数者，可更发汗，宜$f{桂枝汤}主之。  </p><p>63、凡病若发汗，若吐，若下，若亡津液，阴阳自和者，必自愈。</p><p>64、大下之后，复发汗，小便不利者，亡津液故也。勿治之，得小便利，必自愈。</p><p>65、下之后，复发汗，必振寒，脉微细。所以然者，以内外俱虚故也。</p><p>66、下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕，不渴，无表证，脉沉微，身无大热者，$f{干姜附子汤}主之。  </p><p>67、发汗后，身疼痛，脉沉迟者，桂枝加芍药、生姜各一两，人参三两，$f{新加汤}主之。</p><p>68、发汗后，不可更行$f{桂枝汤}。汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}主之。  </p><p>69、发汗过多，其人叉手自冒心，心下悸欲得按者，$f{桂枝甘草汤}主之。 </p>\n<p>70、发汗后，其人脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。 </p><p>71、发汗后，腹胀满者，$f{厚朴生姜半夏甘草人参汤}主之。  </p><p>72、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。</p><p>73、发汗，病不解，反恶寒者，虚故也。$f{芍药甘草附子汤}主之。  </p><p>74、发汗，若下之，病仍不解，烦躁，四逆者，$f{茯苓四逆汤}主之。</p><p>75、发汗后，恶寒者，虚故也。不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。</p><p>76、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。</p>\n<p>77、若脉浮，小便不利，微热，消渴者，$f{五苓散}主之。</p><p>78、发汗已，脉浮数，烦渴者，$f{五苓散}主之。</p><p>79、伤寒，汗出而渴者，$f{五苓散}主之。不渴而心下悸者，$f{茯苓甘草汤}主之。</p><p>80、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。</p><p>81、未持脉时，病人叉手自冒心，师因教试令咳，而不咳者，此必两耳聋无闻也。所以然者，以重发汗，虚，故如此。  </p><p>82、发汗后，饮水多，必喘，以水灌之，亦喘。</p><p>83、发汗后，水药不得入口为逆。若更发汗，必吐下不止。  </p><p>84、发汗吐下后，虚烦不得眠，若剧者，必反复颠倒，心中懊憹，$f{栀子豉汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。  </p><p>85、发汗，若下之，而烦热，胸中窒者，$f{栀子豉汤}主之。</p><p>86、伤寒，五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。  </p><p>87、伤寒下后，心烦，腹满，卧起不安者，$f{栀子厚朴枳实汤}主之。</p><p>88、伤寒，医以丸药大下之，身热不去，微烦者，$f{栀子干姜豉汤}主之。</p><p>89、凡用$f{栀子豉汤}，病患旧微溏者，不可与服之。  </p><p>90、太阳病，发汗，汗出不解。其人仍发热，心下悸，头眩，身润动，振振欲擗地者，$f{真武汤}主之。</p><p>91、咽喉干燥者，不可发汗。</p><p>92、淋家不可发汗，发汗必便血。  </p><p>93、疮家虽身疼痛，不可发汗，发汗则窒。</p><p>94、衄家不可发汗，汗出额上陷，脉急紧，直视不眴，不得眠。  </p><p>95、亡血家，不可发汗，发汗则寒栗而振。</p><p>96、汗家重发汗,必恍惚心乱,小便已阴疼,与$f{禹余粮丸}。</p><p>97、病人有寒，复发汗，胃中冷，必吐蛔。</p><p>98、本先发汗，反而下之，此为逆也；若先发汗，治不为逆。</p>\n<p>99、本先下之，反而汗之，为逆；若先下之，治不为逆。  </p><p>100、伤寒，医下之，续得下利，清谷不止，身疼痛者，急当救里；后身疼 痛，清便自调者，急当救表，救里宜$f{四逆汤}，救表宜$f{桂枝汤}。</p><p>101、病发热，头痛，身体疼痛，若汗之不差，而脉反沉，当救其里，宜$f{四逆汤}。</p><p>102、太阳病，其人冒，先下之而不愈，因复发汗，以此表里俱虚，因冒症汗出自愈，所以然者，汗出表和故也，得里未和，然后复下之。</p><p>103、太阳病未解，脉阴阳俱微，必先振栗汗出而解。但阳脉微者，先汗出而解；但阴脉微者，下之而解；若欲下之，宜$f{调胃承气汤}。</p><p>104、太阳病，发热汗出者，此为营弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。</p><p>105、伤寒五六日，中风，往来寒热，胸胁苦满，默默不欲食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身存微热，或咳者，$f{小柴胡汤}主之。  </p><p>106、血弱气虚，腠理开，邪气因入，与正气相搏，结于胸下；正邪分争， 往来寒热，休作有时，默默不欲饮食；胸胁相连，其痛必下，邪高痛下，故使呕也，$f{小柴胡汤}主之。  </p><p>107、服柴胡汤已，渴者，属阳明也，以法治之。</p><p>108-109、得病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，而胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤后必下重不渴而饮水 呕者，柴胡汤不中与也，食谷者哕。</p><p>110、伤寒四五日，身热，恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。  </p><p>111、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}。不差者，与$f{小柴胡汤}。</p><p>112、呕家不可用「建中汤」,以甘故也。</p><p>113、伤寒中风，有柴胡证，但见一证便是，不必悉具。</p><p>114、凡柴胡汤病证而下之，若柴胡汤不罢者，复与柴胡汤，必蒸蒸而振，却发热，汗出而解。 </p><p>115、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。  </p><p>116、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。  </p><p>117、伤寒十三日不解，胸胁满而呕，已而微下利，日晡所发潮热，此柴胡证，本不得利，今反利者，知医以药丸下之，非其治也。潮热者，实也，先宜$f{小柴胡汤}以解外，后以$f{柴胡加芒硝汤}主之。  </p><p>118、伤寒，十三日不解，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，脉调和者，知医以丸药下之，非其治也。若自下利者，脉微当厥，今反和者知为内实也，$f{调胃承气汤}主之。</p><p>119、太阳病不解，热结膀胱，其人如狂，血自下，下者愈；其外不解者，尚未可攻，当先解其外，外解已，但少腹急结者，仍可攻之，宜$f{桃核承气汤}。</p><p>120、伤寒八九日，下之，胸满，惊烦，小便不利，谵语，一身尽重，不可转侧者，$f{柴胡加龙骨牡蛎汤}主之。  </p><p>121、伤寒，腹满，谵语，寸口脉浮而紧，此肝乘脾也，名曰纵，刺期门。 </p><p>122、伤寒，发热，啬啬恶寒，大渴欲饮水，其腹必满；自汗出，小便利，其病欲解；此肝乘肺也，名曰横，刺期门。  </p><p>123、太阳病一日，反烧瓦熨其背，大汗出，火热入胃，胃中之水竭，躁烦，必发谵语。十余日振栗，自下利者，此为欲解也。其汗从腰以下不得汗，故欲小便不得，反呕。先欲失溲，足下恶风，大便鞕，小便当数，而反不数及不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。 </p><p>124、太阳病，中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥，但头汗出，剂颈而还。腹满、微喘，口干、咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床；小便利者，其人可治。</p><p>125、伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加蜀漆龙骨牡蛎救逆汤}主之。 </p><p>126、形作伤寒，其脉不弦紧而弱，弱者必渴，被火者，必谵语，弱者发热，脉浮，解之，当汗出而愈。  </p><p>127、太阳病，以火熏之，不得汗，其人必躁，到经不解，必圊(校正注：“圊”通“清”)血，名为火邪。</p><p>128、脉浮，热甚，反灸之，此为实。实以虚治，因火而动，必咽燥，吐血。  </p><p>129、微数之脉，慎不可灸；因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。  </p><p>130、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也，欲自解者，必当先烦，乃自汗而解。何以知之? 脉浮，故知 汗出解也。  </p><p>131、烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。</p><p>132、火逆，烧针汗之，因烦躁者，$f{桂苓甘草龙骨牡蛎汤}主之。  </p><p>133、太阳、伤寒者，加温针，必惊也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040005}}', '2024-11-22T08:38:48.000Z', '2024-11-22T08:38:48.000Z', '2024-11-22T08:38:48.000Z', '47、太阳病，外证未解，脉浮弱者，当以汗解，宜$f{桂枝汤}。 48、太阳病，下之微喘者，表未解故也，$f{桂枝加厚朴杏仁汤}主之。 49、太阳病外证未解，不可下也，下之为逆。欲解外者，宜$f{桂枝汤}主之。 50、太阳病先发汗不解，而复下之，脉浮者不愈。浮为在外，而反下之，故令不愈。今脉浮，故知在外，须当解外则愈，宜$f{桂枝汤}主之。 51、太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在，此当发其汗。$f{麻黄汤}主之。服药已，微除，其人发烦，目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。 52、太阳病，脉浮紧，发热，身无汗，自衄者愈。 53、二阳并病，太阳初得病时，发其汗。汗先出不澈，因转属阳明。续自微汗出，不恶寒，若太阳病证不罢者，不可下，下之为逆。如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之。若发汗不澈，不足言阳气怫郁不得 越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也，更发汗则愈。何以知汗岀不澈，脉涩，故知也。 54、脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。 55、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知其然？以营气不足，血少故也。 56、脉浮者，病在表，可发汗，宜$f{麻黄汤}。 57、脉浮数者，可发汗，宜$麻黄汤}。 58、病常自汗出者，此为营气和。营气和者，外不谐，以卫气不共营气和谐故尔。以营行脉中，卫行脉外，复发其汗，营卫和则愈，宜$f{桂枝汤}。 59、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}主之。 60、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。 61、伤寒，不大便六、七日，头痛有热者，与承气汤。其小便清者，知不在里，仍在表也，当须发汗。若头痛者，必衄，宜$f{桂枝汤}。 62、伤寒，发汗，解半日许，复烦，脉浮数者，可更发汗，宜$f{桂枝汤}主之。 63、凡病若发汗，若吐，若下，若亡津液，阴阳自和者，必自愈。 64、大下之后，复发汗，小便不利者，亡津液故也。勿治之，得小便利，必自愈。 65、下之后，复发汗，必振寒，脉微细。所以然者，以内外俱虚故也。 66、下之后，复发汗，昼日烦躁不得眠，夜而安静，不呕，不渴，无表证，脉沉微，身无大热者，$f{干姜附子汤}主之。 67、发汗后，身疼痛，脉沉迟者，桂枝加芍药、生姜各一两，人参三两，$f{新加汤}主之。 68、发汗后，不可更行$f{桂枝汤}。汗出而喘，无大热者，可与$f{麻黄杏仁甘草石膏汤}主之。 69、发汗过多，其人叉手自冒心，心下悸欲得按者，$f{桂枝甘草汤}主之。 70、发汗后，其人脐下悸者，欲作奔豚，$f{茯苓桂枝甘草大枣汤}主之。 71、发汗后，腹胀满者，$f{厚朴生姜半夏甘草人参汤}主之。 72、伤寒，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，$f{茯苓桂枝白术甘草汤}主之。 73、发汗，病不解，反恶寒者，虚故也。$f{芍药甘草附子汤}主之。 74、发汗，若下之，病仍不解，烦躁，四逆者，$f{茯苓四逆汤}主之。 75、发汗后，恶寒者，虚故也。不恶寒，但热者，实也。当和胃气，与$f{调胃承气汤}。 76、太阳病，发汗后，大汗出，胃中干，烦躁不得眠，欲得饮水者，少少与饮之，令胃气和则愈。 77、若脉浮，小便不利，微热，消渴者，$f{五苓散}主之。 78、发汗已，脉浮数，烦渴者，$f{五苓散}主之。 79、伤寒，汗出而渴者，$f{五苓散}主之。不渴而心下悸者，$f{茯苓甘草汤}主之。 80、中风发热，六七日不解而烦，有表里证，渴欲饮水，水入则吐者，名曰水逆，$f{五苓散}主之。 81、未持脉时，病人叉手自冒心，师因教试令咳，而不咳者，此必两耳聋无闻也。所以然者，以重发汗，虚，故如此。 82、发汗后，饮水多，必喘，以水灌之，亦喘。 83、发汗后，水药不得入口为逆。若更发汗，必吐下不止。 84、发汗吐下后，虚烦不得眠，若剧者，必反复颠倒，心中懊憹，$f{栀子豉汤}主之。若少气者，$f{栀子甘草豉汤}主之。若呕者，$f{栀子生姜豉汤}主之。 85、发汗，若下之，而烦热，胸中窒者，$f{栀子豉汤}主之。 86、伤寒，五六日，大下之后，身热不去，心中结痛者，未欲解也，$f{栀子豉汤}主之。 87、伤寒下后，心烦，腹满，卧起不安者，$f{栀子厚朴枳实汤}主之。 88、伤寒，医以丸药大下之，身热不去，微烦者，$f{栀子干姜豉汤}主之。 89、凡用$f{栀子豉汤}，病患旧微溏者，不可与服之。 90、太阳病，发汗，汗出不解。其人仍发热，心下悸，头眩，身润动，振振欲擗地者，$f{真武汤}主之。 91、咽喉干燥者，不可发汗。 92、淋家不可发汗，发汗必便血。 93、疮家虽身疼痛，不可发汗，发汗则窒。 94、衄家不可发汗，汗出额上陷，脉急紧，直视不眴，不得眠。 95、亡血家，不可发汗，发汗则寒栗而振。 96、汗家重发汗,必恍惚心乱,小便已阴疼,与$f{禹余粮丸}。 97、病人有寒，复发汗，胃中冷，必吐蛔。 98、本先发汗，反而下之，此为逆也；若先发汗，治不为逆。 99、本先下之，反而汗之，为逆；若先下之，治不为逆。 100、伤寒，医下之，续得下利，清谷不止，身疼痛者，急当救里；后身疼 痛，清便自调者，急当救表，救里宜$f{四逆汤}，救表宜$f{桂枝汤}。 101、病发热，头痛，身体疼痛，若汗之不差，而脉反沉，当救其里，宜$f{四逆汤}。 102、太阳病，其人冒，先下之而不愈，因复发汗，以此表里俱虚，因冒症汗出自愈，所以然者，汗出表和故也，得里未和，然后复下之。 103、太阳病未解，脉阴阳俱微，必先振栗汗出而解。但阳脉微者，先汗出而解；但阴脉微者，下之而解；若欲下之，宜$f{调胃承气汤}。 104、太阳病，发热汗出者，此为营弱卫强，故使汗出，欲救邪风者，宜$f{桂枝汤}。 105、伤寒五六日，中风，往来寒热，胸胁苦满，默默不欲食，心烦喜呕，或胸中烦而不呕，或渴，或腹中痛，或胁下痞鞕，或心下悸，小便不利，或不渴，身存微热，或咳者，$f{小柴胡汤}主之。 106、血弱气虚，腠理开，邪气因入，与正气相搏，结于胸下；正邪分争， 往来寒热，休作有时，默默不欲饮食；胸胁相连，其痛必下，邪高痛下，故使呕也，$f{小柴胡汤}主之。 107、服柴胡汤已，渴者，属阳明也，以法治之。 108-109、得病六七日，脉迟浮弱，恶风寒，手足温，医二三下之，不能食，而胁下满痛，面目及身黄，颈项强，小便难者，与柴胡汤后必下重不渴而饮水 呕者，柴胡汤不中与也，食谷者哕。 110、伤寒四五日，身热，恶风，颈项强，胁下满，手足温而渴者，$f{小柴胡汤}主之。 111、伤寒，阳脉涩，阴脉弦，法当腹中急痛，先与$f{小建中汤}。不差者，与$f{小柴胡汤}。 112、呕家不可用「建中汤」,以甘故也。 113、伤寒中风，有柴胡证，但见一证便是，不必悉具。 114、凡柴胡汤病证而下之，若柴胡汤不罢者，复与柴胡汤，必蒸蒸而振，却发热，汗出而解。 115、伤寒二三日，心中悸而烦者，$f{小建中汤}主之。 116、太阳病，过经十余日，反二三下之，后四五日，柴胡证仍在者，先与$f{小柴胡汤}。呕不止，心下急，郁郁微烦者，为未解也，与$f{大柴胡汤}下之则愈。 117、伤寒十三日不解，胸胁满而呕，已而微下利，日晡所发潮热，此柴胡证，本不得利，今反利者，知医以药丸下之，非其治也。潮热者，实也，先宜$f{小柴胡汤}以解外，后以$f{柴胡加芒硝汤}主之。 118、伤寒，十三日不解，过经，谵语者，以有热也，当以汤下之。若小便利者，大便当鞕，而反下利，脉调和者，知医以丸药下之，非其治也。若自下利者，脉微当厥，今反和者知为内实也，$f{调胃承气汤}主之。 119、太阳病不解，热结膀胱，其人如狂，血自下，下者愈；其外不解者，尚未可攻，当先解其外，外解已，但少腹急结者，仍可攻之，宜$f{桃核承气汤}。 120、伤寒八九日，下之，胸满，惊烦，小便不利，谵语，一身尽重，不可转侧者，$f{柴胡加龙骨牡蛎汤}主之。 121、伤寒，腹满，谵语，寸口脉浮而紧，此肝乘脾也，名曰纵，刺期门。 122、伤寒，发热，啬啬恶寒，大渴欲饮水，其腹必满；自汗出，小便利，其病欲解；此肝乘肺也，名曰横，刺期门。 123、太阳病一日，反烧瓦熨其背，大汗出，火热入胃，胃中之水竭，躁烦，必发谵语。十余日振栗，自下利者，此为欲解也。其汗从腰以下不得汗，故欲小便不得，反呕。先欲失溲，足下恶风，大便鞕，小便当数，而反不数及不多，大便已，头卓然而痛，其人足心必热，谷气下流故也。 124、太阳病，中风，以火劫发汗，邪风被火热，血气流溢，失其常度，两阳相熏灼，其身发黄。阳盛则欲衄，阴虚小便难，阴阳俱虚竭，身体则枯燥，但头汗出，剂颈而还。腹满、微喘，口干、咽烂，或不大便，久则谵语，甚者至哕，手足躁扰，捻衣摸床；小便利者，其人可治。 125、伤寒，脉浮，医以火迫劫之，亡阳，必惊狂，起卧不安者，$f{桂枝去芍药加蜀漆龙骨牡蛎救逆汤}主之。 126、形作伤寒，其脉不弦紧而弱，弱者必渴，被火者，必谵语，弱者发热，脉浮，解之，当汗出而愈。 127、太阳病，以火熏之，不得汗，其人必躁，到经不解，必圊(校正注：“圊”通“清”)血，名为火邪。 128、脉浮，热甚，反灸之，此为实。实以虚治，因火而动，必咽燥，吐血。 129、微数之脉，慎不可灸；因火为邪，则为烦逆，追虚逐实，血散脉中，火气虽微，内攻有力，焦骨伤筋，血难复也。 130、脉浮，宜以汗解，用火灸之，邪无从出，因火而盛，病从腰以下必重而痹，名火逆也，欲自解者，必当先烦，乃自汗而解。何以知之? 脉浮，故知 汗出解也。 131、烧针令其汗，针处被寒，核起而赤者，必发奔豚，气从少腹上冲心者，灸其核上各一壮，与$f{桂枝加桂汤}。 132、火逆，烧针汗之，因烦躁者，$f{桂苓甘草龙骨牡蛎汤}主之。 133、太阳、伤寒者，加温针，必惊也。', '2024-11-22T08:38:48.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JIOyKhbNDhA', 1, '{"title":"辨太阴病脉证并治法","description":"<p>287、太阴之为病，腹满而吐，食不下；若下之，必胸下结鞕，自利益甚，时腹自痛。 </p><p>288、太阴中风，四肢烦疼，脉阳微阴涩而长者，为欲愈。 </p><p>289、太阴病，欲解时，从亥至丑时。</p><p>290、 太阴病，脉浮者，可发汗，宜$f{桂枝汤}。</p><p>291、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服四逆辈。</p><p>292、伤寒，脉浮而缓，手足自温者，系在太阴；太阴当身发黄；若小便自利者，不能发黄；至七八日，虽暴烦，下利日十数行，必自止，以脾家实，腐秽当去故也。</p><p>293、本太阳病，医反下之，因而腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。</p><p>294、太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。  </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040009}}', '2024-11-29T08:13:10.000Z', '2024-11-29T08:13:10.000Z', '2024-11-29T08:13:10.000Z', '287、太阴之为病，腹满而吐，食不下；若下之，必胸下结鞕，自利益甚，时腹自痛。 288、太阴中风，四肢烦疼，脉阳微阴涩而长者，为欲愈。 289、太阴病，欲解时，从亥至丑时。 290、 太阴病，脉浮者，可发汗，宜$f{桂枝汤}。 291、自利不渴者，属太阴，以其脏有寒故也，当温之，宜服四逆辈。 292、伤寒，脉浮而缓，手足自温者，系在太阴；太阴当身发黄；若小便自利者，不能发黄；至七八日，虽暴烦，下利日十数行，必自止，以脾家实，腐秽当去故也。 293、本太阳病，医反下之，因而腹满时痛者，属太阴也，$f{桂枝加芍药汤}主之；大实痛者，$f{桂枝加大黄汤}主之。 294、太阴为病，脉弱，其人续自便利，设当行大黄、芍药者，宜减之，以其人胃气弱，易动故也。', '2024-11-29T08:13:10.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FedGu7zRO3c', 1, '{"title":"辨少阳病脉证并治法","description":"<p>277、少阳之为病，口苦，咽干，目眩也。</p><p>278、少阳中风，双耳无所闻，目赤，胸中满而烦者，不可吐、下，吐、下则悸而惊。</p><p>279、伤寒，脉弦细、头痛、发热者，属少阳，不可发汗，发汗则谵语。此属胃，胃和则愈，胃不和则烦而躁。  </p><p>280、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，尚未吐、下，脉弦紧者，与$f{小柴胡汤}。</p><p>281、若已吐、下、发汗、温针，柴胡汤证罢者，此为坏病；知犯何逆，以法救之。</p><p>282、三阳合病，脉浮大，上关上，但欲眠睡，目合则汗。  </p><p>283、伤寒六七日，无大热，其人烦燥者，此为阳去入阴故也。  </p><p>284、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。</p><p>285、伤寒三日，少阳脉小者，欲已也。  </p><p>286、少阳病欲解时，从寅至辰上。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040008}}', '2024-11-29T07:29:07.000Z', '2024-11-29T07:29:07.000Z', '2024-11-29T07:29:07.000Z', '277、少阳之为病，口苦，咽干，目眩也。 278、少阳中风，双耳无所闻，目赤，胸中满而烦者，不可吐、下，吐、下则悸而惊。 279、伤寒，脉弦细、头痛、发热者，属少阳，不可发汗，发汗则谵语。此属胃，胃和则愈，胃不和则烦而躁。 280、本太阳病，不解，转入少阳者，胁下鞕满，干呕不能食，往来寒热，尚未吐、下，脉弦紧者，与$f{小柴胡汤}。 281、若已吐、下、发汗、温针，柴胡汤证罢者，此为坏病；知犯何逆，以法救之。 282、三阳合病，脉浮大，上关上，但欲眠睡，目合则汗。 283、伤寒六七日，无大热，其人烦燥者，此为阳去入阴故也。 284、伤寒三日，三阳为尽，三阴当受邪，其人反能食而不呕，此为三阴不受邪也。 285、伤寒三日，少阳脉小者，欲已也。 286、少阳病欲解时，从寅至辰上。', '2024-11-29T07:29:07.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('P7xmAJf0vZ9', 1, '{"title":"辨少阴病脉证并治法","description":"<p>295、少阴之为病，脉微细，但欲寐也。</p><p>296、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故引水自救；若小便色白者，少阴病形悉具。小便白者，以下焦虚，有寒，不能制水，故令色白也。  </p><p>297、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。  </p><p>298、少阴病，咳而下利，谵语者，被火气劫故也，小便必难，以强责少阴汗也。</p><p>299、少阴病，脉细沉数，病为在里，不可发汗。</p><p>300、少阴病，脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。</p><p>301、少阴病，脉紧，至七八日，自下利，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。</p><p>302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治。 </p><p>303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。  </p><p>304、少阴中风，脉阳微阴浮者，为欲愈。</p><p>305、少阴病，欲解时，从子至寅上。</p><p>306、少阴病，吐，利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。</p><p>307、少阴病，八九日，一身手足尽热者，若热在膀胱，必便脓血也。  </p><p>308、少阴病，但厥，无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。 </p><p>309、少阴病，恶寒，身蜷而利，手足逆冷者，不治。  </p><p>310、少阴病，吐，利，躁烦，四逆者，死。</p><p>311、少阴病，下利止，而头眩时时自冒者，死。</p><p>312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死。  </p><p>313、少阴病，六七日，息高者，死。  </p><p>314、少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。</p><p>315、少阴病，始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。  </p><p>316、少阴病，得之二三日，$f{麻黄附子甘草汤}微发其汗，以二三日无里证，故微发其汗也。</p><p>317、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。  </p><p>318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之。  </p><p>319、少阴病，身体痛，手足痛，骨节痛，脉沉者，$f{ 附子汤}主之。 </p><p>320、少阴病，下利便脓血者， $f{桃花汤}主之。</p><p>321、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者， $f{桃花汤}主之。</p><p>322、少阴病，下利便脓血者，可刺。 </p><p>323、少阴病，吐剧。手足厥冷，烦燥欲死者， $f{吴茱萸汤}主之。  </p><p>324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之。  </p><p>325、少阴病，二三日咽痛者，可与$f{甘草汤};不差者，与$f{桔梗汤}。  </p><p>326、少阴病，咽中伤，生疮，不能语言，声不出者，$f{苦酒汤}主之。</p><p>327、少阴病，咽中痛，$f{半夏散及汤}主之。</p><p>328、少阴病，下利，$f{白通汤}主之。  </p><p>329、少阴病，下利，脉微者，与$f{白通汤}。利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之。服汤，脉暴出者死，微续者生。  </p><p>330、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便利，或下利，或呕者，$f{真武汤}主之。</p><p>331、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。 </p><p>332、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。 </p><p>333、少阴病，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。</p><p>334、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。  </p><p>335、少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜$f{大承气汤}。</p><p>336、少阴病，六七日腹胀不大便者，急下之，宜$f{大承气汤}。  </p><p>337、少阴病，脉沉者，急温之，宜$f{四逆汤}。</p><p>338、少阴病，饮食入口则吐，心中温温，欲吐复不能吐，始得之，手足寒，脉弦迟者，此胸中饮实，不可下也，当吐之；若膈上有寒、干呕者，不可吐也，急温之，宜$f{四逆汤}。  </p><p>339、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040010}}', '2024-11-30T03:40:20.000Z', '2024-11-30T03:40:20.000Z', '2024-11-30T03:40:20.000Z', '295、少阴之为病，脉微细，但欲寐也。 296、少阴病，欲吐不吐，心烦，但欲寐，五六日，自利而渴者，属少阴也，虚，故引水自救；若小便色白者，少阴病形悉具。小便白者，以下焦虚，有寒，不能制水，故令色白也。 297、病人脉阴阳俱紧，反汗出者，亡阳也；此属少阴，法当咽痛，而复吐、利。 298、少阴病，咳而下利，谵语者，被火气劫故也，小便必难，以强责少阴汗也。 299、少阴病，脉细沉数，病为在里，不可发汗。 300、少阴病，脉微，不可发汗，亡阳故也；阳已虚，尺脉弱涩者，复不可下之。 301、少阴病，脉紧，至七八日，自下利，胸暴烦，手足反温，脉紧反去者，为欲解也，虽烦，下利，必自愈。 302、少阴病，下利，恶寒而蜷卧，若利自止，手足温者，可治。 303、少阴病，恶寒而蜷，时自烦，欲去衣被者，可治。 304、少阴中风，脉阳微阴浮者，为欲愈。 305、少阴病，欲解时，从子至寅上。 306、少阴病，吐，利，手足不逆冷，反发热者，不死；脉不至者，灸少阴七壮。 307、少阴病，八九日，一身手足尽热者，若热在膀胱，必便脓血也。 308、少阴病，但厥，无汗，而强发之，必动其血，未知从何道出，或从口鼻，或从目出，是名下厥上竭，为难治。 309、少阴病，恶寒，身蜷而利，手足逆冷者，不治。 310、少阴病，吐，利，躁烦，四逆者，死。 311、少阴病，下利止，而头眩时时自冒者，死。 312、少阴病，四逆，恶寒而身蜷，脉不至，不烦而躁者，死。 313、少阴病，六七日，息高者，死。 314、少阴病，脉微细而沉，但欲寐，汗出不烦，自欲吐，至五六日，自利，复烦躁不得卧寐者，死。 315、少阴病，始得之，反发热，脉沉者，$f{麻黄附子细辛汤}主之。 316、少阴病，得之二三日，$f{麻黄附子甘草汤}微发其汗，以二三日无里证，故微发其汗也。 317、少阴病，得之二三日以上，心中烦，不得卧者，$f{黄连阿胶汤}主之。 318、少阴病，得之一二日，口中和，其背微恶寒者，当灸之。 319、少阴病，身体痛，手足痛，骨节痛，脉沉者，$f{ 附子汤}主之。 320、少阴病，下利便脓血者， $f{桃花汤}主之。 321、少阴病，二三日至四五日，腹痛，小便不利，下利不止，便脓血者， $f{桃花汤}主之。 322、少阴病，下利便脓血者，可刺。 323、少阴病，吐剧。手足厥冷，烦燥欲死者， $f{吴茱萸汤}主之。 324、少阴病，下利，咽痛，心烦者， $f{猪肤汤}主之。 325、少阴病，二三日咽痛者，可与$f{甘草汤};不差者，与$f{桔梗汤}。 326、少阴病，咽中伤，生疮，不能语言，声不出者，$f{苦酒汤}主之。 327、少阴病，咽中痛，$f{半夏散及汤}主之。 328、少阴病，下利，$f{白通汤}主之。 329、少阴病，下利，脉微者，与$f{白通汤}。利不止，厥逆无脉，干呕烦者，$f{白通加猪胆汁汤}主之。服汤，脉暴出者死，微续者生。 330、少阴病二三日不已，至四五日，腹痛，小便不利，四肢沉重疼痛，自下利者，此为有水气，其人或咳，或小便利，或下利，或呕者，$f{真武汤}主之。 331、少阴病，下利清谷，里寒外热，手足厥逆，脉微欲绝，身反不恶寒，其人面色赤，或腹痛，或干呕，或咽痛，或利止，脉不出者，$f{通脉四逆汤}主之。 332、少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，$f{四逆散}主之。 333、少阴病，下利六七日，小便不利，咳而呕，渴，心烦不得眠者，$f{猪苓汤}主之。 334、少阴病，得之二三日，口燥咽干者，急下之，宜$f{大承气汤}。 335、少阴病，自利清水，色纯青，心下必痛，口干燥者，急下之，宜$f{大承气汤}。 336、少阴病，六七日腹胀不大便者，急下之，宜$f{大承气汤}。 337、少阴病，脉沉者，急温之，宜$f{四逆汤}。 338、少阴病，饮食入口则吐，心中温温，欲吐复不能吐，始得之，手足寒，脉弦迟者，此胸中饮实，不可下也，当吐之；若膈上有寒、干呕者，不可吐也，急温之，宜$f{四逆汤}。 339、少阴病，下利，脉微涩，呕而汗出，必数更衣，反少者，当温其上，灸之。', '2024-11-30T03:40:20.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6QR4wvKWZFp', 1, '{"title":"辨阳明病脉证并治法","description":"<p>194、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也?答曰：太阳阳明者，发汗脾约是也；正阳阳明者，胃家实是也；少阳阳明者，利小便，胃中燥实，大便难是也。</p><p>195、阳明之为病，胃家实是也。</p><p>196、问曰：何缘转阳明病?答曰：太阳、少阳病，若发汗，若下，若小便利与亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。  </p><p>197、问曰：阳明病，外证云何?答曰：身热，汗自出，不恶寒，反恶热也。 </p><p>198、问曰：病有得之一日，不发热而恶寒者，何也? 答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。</p><p>199、 问曰：恶寒何故自罢?  </p>\n<p> 答曰：阳明居中土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。  </p><p>200、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。  </p><p>201、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。</p><p>202、伤寒三日，阳明脉大。</p><p>203、伤寒脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄；若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。</p><p>204、伤寒转系阳明者，其人濈然微汗出也。</p><p>205、阳明中风，口苦，咽干，腹满，微喘，发热，恶寒，脉浮而紧，若下之，胃中空虚，客气动膈。  </p><p>206、阳明病，若能食，名中风;不能食，名中寒。</p><p>207、阳明病，若中寒，不能食，小便不利，手足濈濈然汗出，此欲作固瘕，必大便初鞕后溏，所以然者，以胃中冷，水谷不别故也。  </p><p>208、阳明病，欲食，大便自调，小便反不利，其人骨节疼，翕翕如有热状，奄然发烦，濈然汗出而解者，此水不胜谷气，与汗共并，脉紧则愈。</p><p>209、阳明病，欲解时，从申至戌上。  </p><p>210、阳明病，不能食，攻其热必哕，所以然者，胃中虚冷故也，以其人本虚，故攻其热必哕。</p><p>211、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸， 虽下之，腹满如故，所以然者，脉迟故也。  </p><p>212、阳明病，法当多汗，反无汗，其身如虫行皮中状者，此以久虚故也。 </p><p>213、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。</p><p>214、阳明病，但头眩，不恶寒，故能食；若咳，其人必咽痛，若不咳者，咽不痛。  </p><p>215、阳明病，无汗，小便不利，心中懊憹者，身必发黄。  </p><p>216、阳明病，被火，额上微汗出，小便不利者，必发黄。  </p><p>217、阳明病，脉浮紧者，必潮热，发作有时；但浮者，必自汗出。</p><p>218、阳明病，口燥，但欲漱水，不欲咽者，此必衄。  </p><p>219、阳明病，本自汗出，医更重发汗，病已瘥，尚微烦不了了者，此大便必鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，故知大便不久出。今为小便数少，以津液当还入胃中，故知不久必大便 也。</p><p>220、伤寒呕多，虽有阳明证，不可攻之。  </p><p>221、阳明病，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。  </p><p>222、阳明病，发热，面含赤色，不可攻之。攻之，小便不利者，必发黄也。  </p><p>223、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。</p><p>224、阳明病，脉迟，虽汗出，不恶寒，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然而汗出者，此大便已鞕也，$f{大承气汤}主之。若汗多，微发热恶寒者，外未解也，其热不潮，未可与$f{大承气汤}。若腹大 满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。  </p><p>225、阳明病，潮热、大便已鞕者，可与$f{大承气汤}；不鞕者，不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}，汤入腹中，转矢气者，此有燥屎，乃可攻之，若不转矢气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕。  </p><p>226、夫实则谵语，虚则郑声，郑声，重语也。  </p><p>227、谵语，直视，喘满者，死；下利者，亦死。</p><p>228、发汗多，若重发汗者，亡其阳；谵语，脉短者，死；脉自和者，生。  </p><p>229、伤寒，若吐，若下后，不解，不大便五六日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死。微者，但发热，谵语者，$f{大承气汤}主之，若一服利，止后服。</p><p>230、阳明病，其人多汗，以津液外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。若一服谵语止，更莫再服。  </p><p>231、阳明病，谵语，发潮热，脉滑而虚者，$f{小承气汤}主之，因与承气汤一升，汤入腹中转矢气者，更服一升；若不转矢气，勿更与之。明日不大便，脉反微涩者，里虚者，为难治，不可更与承气汤也。</p><p>232、233、阳明病，谵语，有潮热，反不能食者，宜$f{大承气汤}下之，胃中必有燥屎五六枚也；若能食者，但鞕耳，宜$f{小承气汤}。  </p><p>234、阳明病，下血，谵语，此为热入血室，但头出汗者，刺期门，随其实而泻之，濈然汗出而愈。  </p><p>235、汗出，此为风也，谵语者，以有燥矢在胃中；此表虚里实故也，须下之，下之则愈，宜$f{大承气汤}。过经乃可下之，下之若早，语言必乱。</p><p>236、伤寒四五日，脉沉而喘满，沉为在里，反发其汗，津液越出，大便为难，表虚里实，久则谵语。  </p><p>237、三阳合病，腹满，身重，难以转侧，口不仁而面垢，谵语，发汗则谵 语甚；下之，则额上出汗，手足厥冷，遗尿；若自汗出者，$f{白虎汤}主之。</p><p>238、二阳并病，太阳证罢，但发潮热，手足漀漀汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。  </p><p>239、阳明病，脉浮而紧，咽燥口苦，腹满而喘，发热汗出，不恶寒，但恶热，身重；若发汗，则燥，愦愦及谵语，若加烧针，必怵惕烦燥不得眠；若下之，则腹如故，小便难也。  </p><p>240、阳明病，心中懊憹，舌上胎者，宜$f{栀子豉汤}主之。若渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。若脉浮发热，渴欲饮水，小便不利者，${猪苓汤}主之。  </p><p>241、阳明病，汗出多而渴者，不可与$f{猪苓汤}，以汗多胃中燥，$f{猪苓汤}复利其小便故也。</p><p>242、脉浮而迟，表热里寒，下利清谷者，$f{四逆汤}主之。若胃中虚冷，不能食者，饮水则哕。</p><p>243、脉浮，发热，口干，鼻燥，能食者，则衄。  </p><p>244、阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，$f{栀子豉汤}主之。</p><p>245、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，$f{小柴胡汤}主之。 </p><p>246、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然而汗出解也。  </p><p>247、阳明中风，脉弦浮大，而短气，腹满，胁下及心痛，久按之气不通，鼻干不得汗，嗜卧，一身面目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之稍瘥。病过十日，外不解，脉续弦者，与$f{小柴胡汤}。脉但浮，无余证者，与$f{麻黄汤}。若不尿，腹满加哕者，不治。</p><p>248、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$f{土瓜根}及$f{大猪胆汁}皆可为导。</p><p>249、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。  </p><p>250、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。  </p><p>251、阳明病，发热汗出，此为越热，不能发黄也。但头汗出，身无汗，剂颈而还，小便不利，渴饮水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。</p><p>252、阳明证，其人善忘者，必有蓄血，所以然者，本有久瘀之血，故令善忘;矢虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。  </p><p>253、阳明病，下之，心中懊憹而烦，胃中有燥矢者，可攻。腹微满，初头硬，后必溏，不可攻之。若有燥矢者，宜$f{大承气汤}。  </p><p>254、病人不大便五六日，绕脐痛，烦燥，发作有时者，此有燥矢，故使不大便也。 </p><p>255、病人烦热，汗出则解，又如疟状，日晡所发热者，属阳明也；脉实者，宜下之；脉浮虚者，宜发汗。下之与$f{大承气汤}。发汗宜$f{桂枝汤}。 </p><p>256、大下后，六七日不大便，烦不解，腹满者，此有燥矢也，所以然者，又有宿食故也，宜$f{大承气汤}。 </p><p>257、病人小便不利，大便乍难乍易，时有微热，喘冒不得卧者，有燥屎也，宜$f{大承气汤}。</p><p>258、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦。</p><p>259、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不渴，但心下痞者，此以医下故也。如其不下者，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也；渴欲饮水，少少与之，但以法救之。小便不利而渴者，宜$f{五苓散}。</p><p>260、阳脉微而汗出少者，为自和也；汗出多者为太过。阳脉实，因发其汗出多者，亦为太过。太过为阳绝于里，亡津液，大便因鞕也。</p><p>261、脉浮而芤，浮为阳，芤为阴。浮芤相搏，胃气生热，其阴则绝。</p><p>262、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏，大便则难，其脾为约，$f{麻仁丸}主之。  </p><p>263、太阳病三日，发汗不解，蒸蒸发热者，属胃也，$f{调胃承气汤}主之。</p><p>264、伤寒吐后，腹胀满者，与$f{调胃承气汤}和之则愈。  </p><p>265、太阳病，若吐，若下，若发汗，微烦、小便数，大便因鞕者，与$f{小承气汤}。</p><p>266、得病二三日，脉弱，无太阳柴胡证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与微和之，令小安。至五六日，与$f{小承气汤}一升。若不大便，小便少者。虽不能食，但初头鞕，后必溏，未定成鞕，攻之必溏。须小便利，矢定鞕，乃可攻之，宜$f{大承气汤}。  </p><p>267、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。</p><p>268、阳明病，发热汗多者，急下之，宜承气汤。</p><p>269、发汗，不解，腹满痛者，急下之，宜$f{大承气汤}。</p><p>270、腹满不减，减不足言，当下之，宜$f{大承气汤}。  </p><p>271、阳明少阳合病，必下利。其脉不负者，顺也；负者，失也；互相克贼，名为负也；脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。</p><p>272、病人无表里证，脉浮数者，虽发热六七日至七八日，勿下之。假令已下，脉数，不解，不大便者，有瘀血，宜$f{抵当汤}。若脉数，不解，而下不止，必协热而便脓血也。</p><p>273、伤寒，发汗已，身目为黄。所以然者，以寒湿在里不解故也。以为不可下，于寒湿中求之。  </p><p>274、伤寒七八日，身黄如橘子色，小便不利，腹微满者，$f{茵陈蒿汤}主之。 </p><p>275、伤寒瘀热在里，身必发黄，$f{栀子蘗皮汤}主之。 </p><p>276、伤寒身黄发热者，$f{麻黄连轺赤小豆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","section":9040007}}', '2024-11-27T07:18:48.000Z', '2024-11-27T07:18:48.000Z', '2024-11-27T07:18:48.000Z', '194、问曰：病有太阳阳明，有正阳阳明，有少阳阳明，何谓也?答曰：太阳阳明者，发汗脾约是也；正阳阳明者，胃家实是也；少阳阳明者，利小便，胃中燥实，大便难是也。 195、阳明之为病，胃家实是也。 196、问曰：何缘转阳明病?答曰：太阳、少阳病，若发汗，若下，若小便利与亡津液，胃中干燥，因转属阳明，不更衣，内实，大便难者，此名阳明也。 197、问曰：阳明病，外证云何?答曰：身热，汗自出，不恶寒，反恶热也。 198、问曰：病有得之一日，不发热而恶寒者，何也? 答曰：虽得之一日，恶寒将自罢，即自汗出而恶热也。 199、 问曰：恶寒何故自罢? 答曰：阳明居中土也，万物所归，无所复传，始虽恶寒，二日自止，此为阳明病也。 200、本太阳病，初得病时发其汗，汗先出不彻，因转属阳明也。 201、伤寒发热，无汗，呕不能食，而反汗出濈濈然者，是转属阳明也。 202、伤寒三日，阳明脉大。 203、伤寒脉浮而缓，手足自温者，是为系在太阴；太阴者，身当发黄；若小便自利者，不能发黄；至七八日，大便鞕者，为阳明病也。 204、伤寒转系阳明者，其人濈然微汗出也。 205、阳明中风，口苦，咽干，腹满，微喘，发热，恶寒，脉浮而紧，若下之，胃中空虚，客气动膈。 206、阳明病，若能食，名中风;不能食，名中寒。 207、阳明病，若中寒，不能食，小便不利，手足濈濈然汗出，此欲作固瘕，必大便初鞕后溏，所以然者，以胃中冷，水谷不别故也。 208、阳明病，欲食，大便自调，小便反不利，其人骨节疼，翕翕如有热状，奄然发烦，濈然汗出而解者，此水不胜谷气，与汗共并，脉紧则愈。 209、阳明病，欲解时，从申至戌上。 210、阳明病，不能食，攻其热必哕，所以然者，胃中虚冷故也，以其人本虚，故攻其热必哕。 211、阳明病，脉迟，食难用饱，饱则微烦，头眩，必小便难，此欲作谷疸， 虽下之，腹满如故，所以然者，脉迟故也。 212、阳明病，法当多汗，反无汗，其身如虫行皮中状者，此以久虚故也。 213、阳明病，反无汗，而小便利，二三日呕而咳，手足厥者，必苦头痛；若不咳，不呕，手足不厥者，头不痛。 214、阳明病，但头眩，不恶寒，故能食；若咳，其人必咽痛，若不咳者，咽不痛。 215、阳明病，无汗，小便不利，心中懊憹者，身必发黄。 216、阳明病，被火，额上微汗出，小便不利者，必发黄。 217、阳明病，脉浮紧者，必潮热，发作有时；但浮者，必自汗出。 218、阳明病，口燥，但欲漱水，不欲咽者，此必衄。 219、阳明病，本自汗出，医更重发汗，病已瘥，尚微烦不了了者，此大便必鞕故也。以亡津液，胃中干燥，故令大便鞕。当问其小便日几行，若本小便日三四行，今日再行，故知大便不久出。今为小便数少，以津液当还入胃中，故知不久必大便 也。 220、伤寒呕多，虽有阳明证，不可攻之。 221、阳明病，心下鞕满者，不可攻之，攻之，利遂不止者死，利止者愈。 222、阳明病，发热，面含赤色，不可攻之。攻之，小便不利者，必发黄也。 223、阳明病，不吐，不下，心烦者，可与$f{调胃承气汤}。 224、阳明病，脉迟，虽汗出，不恶寒，其身必重，短气，腹满而喘，有潮热者，此外欲解，可攻里也。手足濈然而汗出者，此大便已鞕也，$f{大承气汤}主之。若汗多，微发热恶寒者，外未解也，其热不潮，未可与$f{大承气汤}。若腹大 满不通者，可与$f{小承气汤}，微和胃气，勿令大泄下。 225、阳明病，潮热、大便已鞕者，可与$f{大承气汤}；不鞕者，不可与之。若不大便六七日，恐有燥屎，欲知之法，少与$f{小承气汤}，汤入腹中，转矢气者，此有燥屎，乃可攻之，若不转矢气者，此但初头鞕，后必溏，不可攻之，攻之必胀满，不能食也，欲饮水者，与水则哕。 226、夫实则谵语，虚则郑声，郑声，重语也。 227、谵语，直视，喘满者，死；下利者，亦死。 228、发汗多，若重发汗者，亡其阳；谵语，脉短者，死；脉自和者，生。 229、伤寒，若吐，若下后，不解，不大便五六日，日晡所发潮热，不恶寒，独语如见鬼状；若剧者，发则不识人，循衣摸床，惕而不安，微喘，直视；脉弦者生，涩者死。微者，但发热，谵语者，$f{大承气汤}主之，若一服利，止后服。 230、阳明病，其人多汗，以津液外出，胃中燥，大便必鞕，鞕则谵语，$f{小承气汤}主之。若一服谵语止，更莫再服。 231、阳明病，谵语，发潮热，脉滑而虚者，$f{小承气汤}主之，因与承气汤一升，汤入腹中转矢气者，更服一升；若不转矢气，勿更与之。明日不大便，脉反微涩者，里虚者，为难治，不可更与承气汤也。 232、233、阳明病，谵语，有潮热，反不能食者，宜$f{大承气汤}下之，胃中必有燥屎五六枚也；若能食者，但鞕耳，宜$f{小承气汤}。 234、阳明病，下血，谵语，此为热入血室，但头出汗者，刺期门，随其实而泻之，濈然汗出而愈。 235、汗出，此为风也，谵语者，以有燥矢在胃中；此表虚里实故也，须下之，下之则愈，宜$f{大承气汤}。过经乃可下之，下之若早，语言必乱。 236、伤寒四五日，脉沉而喘满，沉为在里，反发其汗，津液越出，大便为难，表虚里实，久则谵语。 237、三阳合病，腹满，身重，难以转侧，口不仁而面垢，谵语，发汗则谵 语甚；下之，则额上出汗，手足厥冷，遗尿；若自汗出者，$f{白虎汤}主之。 238、二阳并病，太阳证罢，但发潮热，手足漀漀汗出，大便难而谵语者，下之则愈，宜$f{大承气汤}。 239、阳明病，脉浮而紧，咽燥口苦，腹满而喘，发热汗出，不恶寒，但恶热，身重；若发汗，则燥，愦愦及谵语，若加烧针，必怵惕烦燥不得眠；若下之，则腹如故，小便难也。 240、阳明病，心中懊憹，舌上胎者，宜$f{栀子豉汤}主之。若渴欲饮水，口干舌燥者，$f{白虎加人参汤}主之。若脉浮发热，渴欲饮水，小便不利者，${猪苓汤}主之。 241、阳明病，汗出多而渴者，不可与$f{猪苓汤}，以汗多胃中燥，$f{猪苓汤}复利其小便故也。 242、脉浮而迟，表热里寒，下利清谷者，$f{四逆汤}主之。若胃中虚冷，不能食者，饮水则哕。 243、脉浮，发热，口干，鼻燥，能食者，则衄。 244、阳明病，下之，其外有热，手足温，不结胸，心中懊憹，饥不能食，但头汗出者，$f{栀子豉汤}主之。 245、阳明病，发潮热，大便溏，小便自可，胸胁满不去者，$f{小柴胡汤}主之。 246、阳明病，胁下鞕满，不大便而呕，舌上白苔者，可与$f{小柴胡汤}，上焦得通，津液得下，胃气因和，身濈然而汗出解也。 247、阳明中风，脉弦浮大，而短气，腹满，胁下及心痛，久按之气不通，鼻干不得汗，嗜卧，一身面目悉黄，小便难，有潮热，时时哕，耳前后肿，刺之稍瘥。病过十日，外不解，脉续弦者，与$f{小柴胡汤}。脉但浮，无余证者，与$f{麻黄汤}。若不尿，腹满加哕者，不治。 248、阳明病，自汗出，若发汗，小便自利者，此为津液内竭，虽鞕不可攻之，当须自欲大便，宜$f{蜜煎导}而通之，若$f{土瓜根}及$f{大猪胆汁}皆可为导。 249、阳明病，脉迟，汗出多，微恶寒者，表未解也，可发汗，宜$f{桂枝汤}。 250、阳明病，脉浮，无汗而喘者，发汗则愈，宜$f{麻黄汤}。 251、阳明病，发热汗出，此为越热，不能发黄也。但头汗出，身无汗，剂颈而还，小便不利，渴饮水浆者，此为瘀热在里，身必发黄，$f{茵陈蒿汤}主之。 252、阳明证，其人善忘者，必有蓄血，所以然者，本有久瘀之血，故令善忘;矢虽鞕，大便反易，其色必黑，宜$f{抵当汤}下之。 253、阳明病，下之，心中懊憹而烦，胃中有燥矢者，可攻。腹微满，初头硬，后必溏，不可攻之。若有燥矢者，宜$f{大承气汤}。 254、病人不大便五六日，绕脐痛，烦燥，发作有时者，此有燥矢，故使不大便也。 255、病人烦热，汗出则解，又如疟状，日晡所发热者，属阳明也；脉实者，宜下之；脉浮虚者，宜发汗。下之与$f{大承气汤}。发汗宜$f{桂枝汤}。 256、大下后，六七日不大便，烦不解，腹满者，此有燥矢也，所以然者，又有宿食故也，宜$f{大承气汤}。 257、病人小便不利，大便乍难乍易，时有微热，喘冒不得卧者，有燥屎也，宜$f{大承气汤}。 258、食谷欲呕者，属阳明也，$f{吴茱萸汤}主之。得汤反剧者，属上焦。 259、太阳病，寸缓，关浮，尺弱，其人发热汗出，复恶寒，不渴，但心下痞者，此以医下故也。如其不下者，病人不恶寒而渴者，此转属阳明也。小便数者，大便必鞕，不更衣十日，无所苦也；渴欲饮水，少少与之，但以法救之。小便不利而渴者，宜$f{五苓散}。 260、阳脉微而汗出少者，为自和也；汗出多者为太过。阳脉实，因发其汗出多者，亦为太过。太过为阳绝于里，亡津液，大便因鞕也。 261、脉浮而芤，浮为阳，芤为阴。浮芤相搏，胃气生热，其阴则绝。 262、趺阳脉浮而涩，浮则胃气强，涩则小便数，浮涩相搏，大便则难，其脾为约，$f{麻仁丸}主之。 263、太阳病三日，发汗不解，蒸蒸发热者，属胃也，$f{调胃承气汤}主之。 264、伤寒吐后，腹胀满者，与$f{调胃承气汤}和之则愈。 265、太阳病，若吐，若下，若发汗，微烦、小便数，大便因鞕者，与$f{小承气汤}。 266、得病二三日，脉弱，无太阳柴胡证，烦躁，心下鞕，至四五日，虽能食，以$f{小承气汤}少少与微和之，令小安。至五六日，与$f{小承气汤}一升。若不大便，小便少者。虽不能食，但初头鞕，后必溏，未定成鞕，攻之必溏。须小便利，矢定鞕，乃可攻之，宜$f{大承气汤}。 267、伤寒六七日，目中不了了，睛不和，无表里证，大便难，身微热者，此为实也，急下之，宜$f{大承气汤}。 268、阳明病，发热汗多者，急下之，宜承气汤。 269、发汗，不解，腹满痛者，急下之，宜$f{大承气汤}。 270、腹满不减，减不足言，当下之，宜$f{大承气汤}。 271、阳明少阳合病，必下利。其脉不负者，顺也；负者，失也；互相克贼，名为负也；脉滑而数者，有宿食也，当下之，宜$f{大承气汤}。 272、病人无表里证，脉浮数者，虽发热六七日至七八日，勿下之。假令已下，脉数，不解，不大便者，有瘀血，宜$f{抵当汤}。若脉数，不解，而下不止，必协热而便脓血也。 273、伤寒，发汗已，身目为黄。所以然者，以寒湿在里不解故也。以为不可下，于寒湿中求之。 274、伤寒七八日，身黄如橘子色，小便不利，腹微满者，$f{茵陈蒿汤}主之。 275、伤寒瘀热在里，身必发黄，$f{栀子蘗皮汤}主之。 276、伤寒身黄发热者，$f{麻黄连轺赤小豆汤}主之。', '2024-11-27T07:18:48.000Z', 1, NULL, 'XNK0VFX39Xv', 'chapter', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yyx8BP2rd7b', 4, '{"title":"第904000514条・辨太阳病脉证并治法中篇","description":"<p>60、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000514,"note":"       脉浮紧，不发汗，就知道是麻黄汤证，表寒很盛了，因致衄者，如果得到了流鼻血，一般来说，鼻血流出来之后，症状就没有了，热就退掉了，为什么？因为肺开窍在鼻，所以肺的血管直接进入鼻，因为麻黄入肺，肺被寒束到了，肺的热没办法宣泄就往上走，所以就会流鼻血了，这条辨讲的是，如果得衄还是没解的，可再用麻黄汤。所以如果小孩感冒流鼻血，不要急，这是因为小孩阳比较亢，才流得出来。  \n\n       周禹载曰夺汗无血也；病人流鼻血的时候，一发表，鼻血就停掉了，为什么？血本来就在血管里面，一发汗以后，表没被束到，血液循环就会很流畅，血管里面有瓣膜不让血往回流，而且血管都有一定的弹性，血过不去的时候，血管就会破裂，在鼻子上就是流鼻血，在脑里面就是脑中风，所以平常有不和的时候，常常吃桂枝汤，让营卫和就不会出血，所以北 派预防脑中风的，除了灸足三里以外，就是吃桂枝汤了。桂枝、白芍让血管的弹性很好，遇到寒血管会收缩，遇到热血管会扩张，所以补血管的药都是两热药，因为西医没有分寒热的，西医治疗头痛的时候，开止痛药，就是血管舒张剂，舒张血管就是硬把血管撑开来，一撑开来血就流通了，当时纾解了，但是药效十二小时过了以后，痛回来了以后，血管会绷得更紧，头会更痛。  ","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '60、伤寒，脉浮紧，不发汗，因致衄者，$f{麻黄汤}主之。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s6Dm0AT06LB', 4, '{"title":"第904000508条・辨太阳病脉证并治法中篇","description":"<p>54、脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。 </p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000508,"note":"       脉浮数者，浮就是表，一息跳六七下，数代表热，发烧了，法当汗出而愈，看到表热，汗一出就解掉了，若下之，应该发表，结果攻下，这病人身重心悸，因为攻下得太厉害了，造成病人气血两虚，为什么身重？因为所有好的食物营养，本来是血的源头，通通攻掉了，造成血不够了，所以到四肢肌肉关节的营养不足，就会有身重，心脏缺血就会有心悸的现象，这时候病人已经血虚，就不要再发汗了，当自汗出乃解，遇到这种情形，让他慢慢的自己恢复，自己流汗，胃气慢慢恢复就好了，为什么？尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。尺脉的地方，讲男人的精宫，女人的子宫，也就是胞中，胞中是下焦阳聚的地方，也就是精的来源，摸到尺脉很虚很弱，重按就没有了，就是下焦虚掉了，血化成热，到下焦后成为精，就是我们的体力，所以精血是同源的，因此要确定病人里面津液很足的时候，才可以发表。遇到这种情形的时候，让他肠胃功能慢慢恢复，自己会流汗就好了。有的人身体很虚，回来得比较慢，这样等不是办法，过去经方家在里虚很盛的时候，用小建中汤加黄芪，为什么用小建中汤？小建中汤就是桂枝汤加饴糖，这饴糖就是麦芽糖，如果饴糖太麻烦，用普通的方糖也可以，这是专门治疗肠比较冷的状况，有的小孩喜欢吃冰，吃冰后，饭就不吃了，因为吃冰后肠胃都冷掉了，肠胃都不蠕动了，当然不喜欢吃钣，吃了小建中汤以后，看到冰就没兴趣，小建中汤在经方是拿来作补药的，小建中汤加黄芪让它固表，黄芪这药是固表，属于气药，气不足的时候，用来补气的。例：孕妇，怀孕正常的状况是血旺气衰，如果流产的时候，就是气旺血衰，所以怀孕的人不可能开黄芪给她吃的，但是如果要下胎就要把黄芪加重。黄芪本身是走表的，走皮肤表面上，所以皮肤病的药，都要加黄芪。所以遇到这种情形，看他有表证，又不可以发表，因为里虚，所以先去把里扶正，再让他发一点表，所以用小建中汤加黄芪。  \n\n       如果是有脉浮有汗的桂枝汤证，而且尺脉微、舌苔白而厚，我们知道里虚而且中湿很盛，我们可以在发表的药中加些加些茯苓白术，就可以避免这种现象。  \n","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '54、脉浮数者，法当汗出而愈。若下之，身重心悸者，不可发汗，当自汗出乃解。所以然者，尺中脉微，此里虚，须表里实，津液自和，便自汗出而愈。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7YH8xJWPCuC', 4, '{"title":"第904000513条・辨太阳病脉证并治法中篇","description":"<p>59、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000513,"note":"        这就是说平常没有桂枝汤证，如果营卫气血不和的时侯，都可以吃桂枝汤，像这种时发热自汗出的人，常常觉得一阵一阵的热汗流出来，就是卫气不调和，卫气不调和的时候，血管外面的膜会干会破掉，东西缺水，反一下就破了，例如塑胶水管，常常有水就不容易坏，放在太阳下没水，很快就干掉破了，所以容易没事发发热流一点汗的人，就吃桂枝汤，把桂枝汤当作补药来吃，北派的补药不是注重滋补，而是注重调理，调整得很好，吃下去的食物才是真正的营养。  \n\n        桂枝汤名为发汗之剂，实为补气益血之剂。所以对气血很有帮助，非常的好，草枣亦为补养之品，加以啜粥补养津液，所以在早餐之前，先吃个几勺桂枝汤，再吃稀饭，可以让气血调得很好。  ","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '59、病人脏无他病，时发热自汗出而不愈者，此卫气不和也。先其时发汗则愈，宜$f{桂枝汤}主之。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZYRQdWXDkio', 4, '{"title":"第904000512条・辨太阳病脉证并治法中篇","description":"<p>58、病常自汗出者，此为营气和。营气和者，外不谐，以卫气不共营气和谐故尔。以营行脉中，卫行脉外，复发其汗，营卫和则愈，宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000512,"note":"        中医对营卫的观念，营就是血，卫就是气，营在肌肉里面，营的路线，从动脉血管到小血管到孙络，中医讲的孙络就是微血管的部分；气就是我们的动能，所以气虚掉的时候，就没有什么力气，讲话都懒得讲，卫气的路线就从腑，往往这个气从肠胃吸收营养后从淋巴系统一直走，走在皮肤毛孔；所以有流汗和流血两种，在血管里面看到的是血，血管的外面有一层薄膜圈到了，这层网膜就是中医讲的气的走向，网膜的力量很强，常见心脏的动脉血管破掉的时候，网膜会把它包到，在没有完全破裂之前，还有一段时间可以急救，而且在破掉之前会有症状，病人的症状就是心痛彻背背痛彻心，或心口绞痛、刺痛。五六十岁的人常常在副主动脉上面破裂，在心脏的上方有一副主动脉，血出来很多，往往有网膜包到，就是被气包到了，病人不会马上死，可是很危险，病人不能动，一动就喷出来了，中医的方法是让血急速的流回去，加强网膜的力量，让血管愈合，西医的方法就是把这一段割掉，接个血管上去，在接的时候，把动脉导到维生机上面，很快的接完血管再导回来，接个人工血管这样没有网膜了，就没有第二次机会了。往往再发病的时候，血已经喷出来了，所以中医讲的气血同源，讲的就是血管外面的网膜。  \n\n       病人常常自汗出，病人本身平常就在流汗。营行脉中，卫行脉外，复发其汗，营卫和则愈，人的气血要两和，血管的网膜和淋巴系统的气是相通的，如果血管里面的水少了，它会自动供应水，如果血管里面的水太多，水自然会出来，给淋巴系统传到皮肤毛孔，发汗发掉了，互相有协调作用，所以两者的管路是通的，当气和血不协调的时候，桂枝汤最大的功能就是调和营卫，汤剂下去后，本来不协调的变得协调了，本来淋巴系统里面的水分要进入血管里面的，如果气太旺了，水太过了发到皮肤表面，这水原本应进入血的，结果跑出去，就代表营卫不协调，所以平常没事流汗的人，气候又没变化，突然流虚汗，就是代表营卫不协调，这时候没有病无所谓，有症状就可以吃桂枝汤，让它协调。中风证是伤到卫分，只需要用到桂枝；而伤寒是营卫两伤，因此麻黄与桂枝必须并用。  \n\n        新药物学知道麻黄素有刺激中枢神经的效能，是作用于交感神经兴奋药，我们用作发汗药。麻黄素，西医用在急救、兴奋上面，也知道麻黄会发汗，但是西医只用单味的麻黄，用麻黄素发汗和安非他命造成很多的问题，吃单味的麻黄素并不能发汗，如果麻黄素没有桂枝，只是个宣肺的药，不能得到真的汗，因为麻黄素是阳药，能把气管打开来，性轻而且升，一下就跑到脑部去了，头部阳气很盛，当然会睡不着觉，所以张仲景在汤剂用麻黄的时候，一定把麻黄素先煮掉。  \n\n        中药讲气和味，所以《神农本草经》上面一定讲气和味，药有的时候要取药的气，有的时候要取药的味，例：大黄用来泻头面五官的热，大黄是寒凉的药，是消炎的药，如果牙齿痛、头上的病、眼睛红肿，取大黄的性就要用开水烫，所以麻沸汤就是用滚水烫下去，这消炎的药就走上面，就是取它的气。如果把大黄煮两个小时，药味都煮出来了，这是取它的味，这时候大黄是往下走，而不是走到头上，所以大承气汤就一定是取它的味，因为要攻下。所以麻黄煮过以后，就不取它的气，取它的味了，麻黄直接进入肺，用麻黄发表流汗的时候，一定加桂枝在里面，因为没有桂枝，麻黄不会流汗，麻黄进入肺让气管打开来，不论寒证热证都用得到麻黄，所以小青龙大青龙都有麻黄。 \n","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '58、病常自汗出者，此为营气和。营气和者，外不谐，以卫气不共营气和谐故尔。以营行脉中，卫行脉外，复发其汗，营卫和则愈，宜$f{桂枝汤}。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VgvHMIaxiBT', 4, '{"title":"第904000510条・辨太阳病脉证并治法中篇","description":"<p>56、脉浮者，病在表，可发汗，宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000510,"note":"       这条是在尺脉很壮盛的时候会用得到。如果是下针给病人发汗，就下合谷，合谷下针的时候要飞针引气，起针的时候转针，一边起针一边转，下去的时候直直的下，引到第三次的时候，病人就冒汗了。  \n\n     头痛、印堂痛用承气汤；偏头痛就是小柴胡汤；整个头痛、头顶最痛用葛根汤。  ","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '56、脉浮者，病在表，可发汗，宜$f{麻黄汤}。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GvVW1jt2DxE', 4, '{"title":"第904000511条・辨太阳病脉证并治法中篇","description":"<p>57、脉浮数者，可发汗，宜$麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000511,"note":"        发汗，有它必要的条件，如果说病人已经在发汗了，不会开麻黄汤的，因为病人的表已经开了，病人的症状除了脉浮数以外，一定兼有恶寒和无汗，所以麻黄汤和桂枝汤最简单的区分就是一个无汗，一个有汗。麻黄汤证一般发烧温度比较高，无汗，怕冷比较严重。  ","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '57、脉浮数者，可发汗，宜$麻黄汤}。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u3NBJ1iNrRA', 4, '{"title":"第904000509条・辨太阳病脉证并治法中篇","description":"<p>55、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知其然？以营气不足，血少故也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000509,"note":"      脉浮紧就是寒，法当身疼痛，他应该感觉到全身痛，宜以汗解之，要用汗来解他，假令尺中迟者，尺中脉很迟的时候，就是血不足了，血里面有百分之六十的水，血不够代表血里面的津液不足了，这时候不可以发汗，所以在开麻黄汤之前，要确定病人有没有足够的津液来发汗，张仲景提供一个方法，就是摸一摸尺脉，平常开麻黄汤，病人的尺脉都很大，又浮又紧，摸寸脉是阳，也就是胸、肺、皮肤表面、上焦，摸关脉就是肝、胆、脾、胃、中焦，尺脉是阴，就是肾、膀胱、下焦，平常开麻黄汤给病人发汗的时候，一定是寸、关、尺三脉都浮在上面的，才用麻黄汤，这是用脉证来确定病人的身体虚不虚，如果吃了麻黄汤会手脚厥逆，就是病人变成甘草干姜汤证了。一般来说，如果吃了麻黄，不会感觉到心悸的人，都是心脏比较好的。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '55、脉浮紧者，法当身疼痛，宜以汗解之。假令尺中迟者，不可发汗。何以知其然？以营气不足，血少故也。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hIFSHCZDqU6', 4, '{"title":"第904000507条・辨太阳病脉证并治法中篇","description":"<p>53、二阳并病，太阳初得病时，发其汗。汗先出不澈，因转属阳明。续自微汗出，不恶寒，若太阳病证不罢者，不可下，下之为逆。如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之。若发汗不澈，不足言阳气怫郁不得 越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也，更发汗则愈。何以知汗岀不澈，脉涩，故知也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000507,"note":"        二阳并病，就是太阳阳明并病，太阳初得病时，发其汗，太阳病刚得到的时候，发病人的汗，如果发透了就好了，如果发得没有透，汗先出不澈，开处方的时候心软，药剂开得太少，病邪没有去，慢慢的太阳证的时间过了以后，病的热邪转到阳明去了，续自微汗出，不恶寒，阳明证的话，还会流汗，因为肠的津液还会往外走，但是阳明证没有寒都是热证，表证已经没有了，入到里去了，如果这种情形的时候，若太阳病证不罢者，不可下，要先看病人到底在阳明还是在太阳，问病人还有没有怕风？答有，有没有怕冷？答有，还有没有流汗？答有，就是表证还没有去，甚而摸他的脉很浮，有表证的时候，绝对不要攻下，下之为逆。这种状况的时候，给他小发汗，就是桂枝汤加葛根就可以了。用葛根把津液补一补，前面已然发过汗了，后面怕发汗发太多了。设面色缘缘正赤者，阳气怫郁在表，脸色红赤的时候，代表胃的热气往上冲，阳气浮在皮肤表面上，发又发不出来，当解之熏之，熏为古人用一种药草熬水，蒸其水气以取汗之法。就是用煮药草，病人坐在旁边，熏病人，让病人流一点汗，因为怕喝药喝太多，而病人津液已经不够，因为有阳明证表示津液不够了，肠胃的津液再伤  \n到的话，大便一旦堵到了，就变成承气汤证，如果是血里面的水不够的话，就变成白虎汤证，怕吃药吃太多不好控制，所以用药去熏他，用外在的方法使病人流一点汗，这是比较浅的方法。若发汗不澈，不足言阳气怫郁不得越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也。这条辨讲的是，如果病刚好介在阳明和太阳之间，无法分辨，就问病人大便正不正常？如果还很正常，就不用管阳明，先解表再攻里，解表的同时，如果怕太重伤到津液，可以同时采用增加津液的药，吃稀饭或杏仁多加一点，或吃完麻黄汤以后，多吃些水梨，把肺的津液补回去。  \n\n        刚刚讲的就是汗发得不够透澈，所以在太阳证的时候，给病人多一点发汗不会有事，因为桂枝汤里面有甘草、大枣，麻黄汤里面有杏仁，张仲景设计的方子不会伤到津液的，所以麻黄汤里面麻黄开到五钱，杏仁也要开到五钱，如果吃了麻黄汤，因发汗发太过造成贫血，就是杏仁用太少了。所有的症状都是汗出不澈故也，更发汗则愈。为什么知道汗出不澈呢？脉涩，涩脉，摸到的脉是扁的，所以脉迟而细就是涩脉。汗出不澈，从脉可以看得出来，还有病人的陈述也可以看得出来，皮肤痒痒就是汗出不澈，最明显就是皮肤痒，风吹得很难过，这也是汗出不澈，汗发不透的时候，有时候是皮肤痒，有时候是皮肤有很紧的感觉，整个脸色是红润的，眼睛两边红红赤赤的，因为汗是从胃里面的津液来的，要发发不出来，胃气一直往上跑，整个冲在脸上，所以脸就会红红的，可是又流不出汗来。  \n\n        如果要很重的透发，太阳证的时候，就桂枝汤加重一些。如果表束到了，没有汗了，加麻黄汤进去。如果病人全部是热证，脉洪大、燥渴，用白虎汤，病人吃石膏的时候，也是得汗则解，因此不单单只有桂枝汤、麻黄汤、葛根汤才有流汗的现象。","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '53、二阳并病，太阳初得病时，发其汗。汗先出不澈，因转属阳明。续自微汗出，不恶寒，若太阳病证不罢者，不可下，下之为逆。如此可小发汗。设面色缘缘正赤者，阳气怫郁在表，当解之熏之。若发汗不澈，不足言阳气怫郁不得 越，当汗不汗，其人烦躁，不知痛处，乍在腹中，乍在四肢，按之不可得，其人短气，但坐，以汗出不澈故也，更发汗则愈。何以知汗岀不澈，脉涩，故知也。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0ZelcC5kVRP', 4, '{"title":"第904000506条・辨太阳病脉证并治法中篇","description":"<p>52、太阳病，脉浮紧，发热，身无汗，自衄者愈。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000506,"note":"       这因本身的体能比刚刚的更强，刚才的阳气还只是中级强，还需要麻黄汤来把寒发出来，这个不用麻黄汤，常见的是小孩子，而且是男孩子，很皮，跑来跑去，妈妈还在煮麻黄汤，小孩子流鼻血好了，所以不用紧张，血会自己停掉，一般容易发生在十四岁以下的孩童，因为是纯阳之体，所以在针灸课程中讲过，十四岁以下的孩童如果流鼻血，不需要治疗。  \n\n       温度因衄血而降低，故中医谓之红汗。故多血家之有脑充血象征者，不但无害，反而有益。$m{《内经》}$n{有夺血者无汗，夺汗者无血。}就是平常容易流鼻血的都不会有汗的，还有平常流汗很多的人，就不会流鼻血。  ","videoMemo":"","fangList":[],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '52、太阳病，脉浮紧，发热，身无汗，自衄者愈。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LsaZ6ScWOTh', 4, '{"title":"第904000505条・辨太阳病脉证并治法中篇","description":"<p>51、太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在，此当发其汗。$f{麻黄汤}主之。服药已，微除，其人发烦，目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。</p>","content_format":"html","_microfeed":{"bookId":"XNK0VFX39Xv","receiptNo":904000505,"note":"       太阳病，脉浮紧这代表伤寒，无汗发热，身疼痛，这就是太阳病的麻黄汤证，如果八九日后，表证还在，还是冷得要死，必要发病人的汗，开麻黄汤给他吃了以后，微除，稍微除了一点。开麻黄汤给病人有两种情形，一种是医师的过失，一种是病人的过失，什么是医师的过失？前面讲了，方子的剂量很重要，是麻黄汤证，开麻黄汤，病人吃下去发汗了，如果开太轻了，发汗的力量不够，微除，就是一点点除掉了，还有症状在里面，这是一种情形。还有就是医生的剂量开得很足，病人喝得不够，只喝了第一碗，这一种是病人的过失，就是剂量吃得不够，造成病人发烦，目瞑，突然感到情绪暴躁，头有点昏花，剧者必衄，衄乃解。所以然者，阳气重故也。有这种状况是这病人本身体能很强，体能很强的人得到麻黄汤证，喝麻黄汤的剂量不够，但麻黄汤已经带动血的奔腾，已经把免疫系统带出一部分，结果阳气整个往上冲，血往上冲，冲到头部，结果昏弦，严重的血叛离经脉，造成流鼻血，汗和血是同源的，有的时候给病人发汗的药，一发汗烧就退烧了，还有时给病人发汗的药，结果病人流鼻血烧就退掉了，所以小孩子发烧，流鼻血烧就退了，小孩子阳气很重，有时候感冒，流鼻血烧就退了。这时候看到鼻血已经流出来了，表示病人已好了，再开麻黄汤就太过了。  \n\n       临床上有一个案例，两个木工的兄弟，大热天把父亲用棉被包起来，带到诊所来看病，说已经中风一个礼拜，结果我一看，麻黄汤证，照样用麻黄汤，心想仲景必不我欺；为了小心，隔天打电话去求证，结果家人说，不在！原来是不在家里，出门去玩了；问家人说麻黄汤喝了几碗，回答说只喝了一碗，药效就是这么快；而且吃了麻黄汤还是睡的很好，不因为麻黄而有失眠现象。虽然八九日不解，不管病名是中风还是感冒，只要还是麻黄汤证，就用麻黄汤，这就是辨症论治。 ","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '2024-11-22T09:20:35.000Z', '51、太阳病，脉浮紧，无汗发热，身疼痛，八九日不解，表证仍在，此当发其汗。$f{麻黄汤}主之。服药已，微除，其人发烦，目瞑，剧者必衄，衄乃解。所以然者，阳气重故也。', '2024-11-22T09:20:35.000Z', 1, NULL, 'XNK0VFX39Xv', 'section', '1NZBr3pAx9S');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3FzHDKuYT1I', 1, '{"title":"三物小白散","description":"<p>$u{桔梗}$w{三分}    $u{巴豆}$w{一分(去皮心、熬黑、研如脂)}    $u{贝母}$w{三分}</p>\n<p>\t右三味、为散、纳巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。</p>\n<p></p>\n<p>        白饮就是米汤，强人半钱匕，就是半个汤匙，三味药加起来半汤匙，差不多三比一比三，桔梗三、巴豆一、贝母三，羸者减之，瘦的人还要减半。病在膈上必吐，病在膈下必利。如果不利，再吃热稀饭就好了，不要再吃药，如果利不止，吃冷稀饭就好了，或者是黄连也可以、冷豆浆也可以。如果病人感觉身冷鸡皮疙瘩，这时候不要用水去喷他，休息就好了。如果病人吃了巴豆后肚子痛，重用芍药三两，这时候不要用三钱，用三两，单味的芍药去熬汤吃，就能把巴豆的毒解掉。  </p>\n<p></p>\n<p>        《类聚方广义》本条曰：此方不仅治肺痈，就是肺里面化脓疡，且治痈疽，看不到的脓肿、肿块、硬块，胃酸；胃里面化脓长瘤，及胸膈中有顽痰，胸背牵痛者。又咳家胶痰缠扰，咽喉不利，气息有臭者，皆有效。就是结得很盛的时候可以用，但是要确定是寒实，才可以用。卒中风，马脾风，痰潮息迫，牙关紧闭，药汁不入者，取少许吹鼻中，则吐痰涎而咽喉立适。突然中风的时候，痰上来很多，西医在天突的地方开一个洞，牙关紧闭药都进不去，所以药要用喷的，痰从嘴巴、鼻子出来，一下去人就醒过来了，所以三物小白散在用的时候，如果病在胸膈以上一定是吐出来的，如果病在胸膈以下一定是下利的，就是胃以上、食道里面的一定会吐出来，已经下去的全都会排出来。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":256,"yaoCount":3,"drinkNum":1,"yaoList":["贝母","巴豆","桔梗"],"fangList":[],"fangYaoList":[{"yaoId":"aDnno23iRr4","amount":"三分","weight":null,"suffix":"","showName":"贝母","extraProcess":""},{"yaoId":"7nTRDUdzsoW","amount":"一分","weight":null,"suffix":"","showName":"巴豆","extraProcess":""},{"yaoId":"5GP5Zyu6577","amount":"三分","weight":null,"suffix":"","showName":"桔梗","extraProcess":""}]}}', '2024-11-26T03:52:09.000Z', '2024-11-26T03:52:09.000Z', '2024-11-26T03:52:09.000Z', '$u{桔梗}$w{三分} $u{巴豆}$w{一分(去皮心、熬黑、研如脂)} $u{贝母}$w{三分} 右三味、为散、纳巴豆。更于臼中杵之。以白饮和服。强人半钱匕。羸者减之。病在膈上必吐。在膈下必利。不利。进热粥一杯。利过不止。进冷粥一杯。身热皮粟不解。欲引衣自覆。若以水潠之、洗之。益令热却不得出。当汗而不汗则烦。假令汗出已。腹中痛。与$u{芍药}$w{三两}。如上法。 白饮就是米汤，强人半钱匕，就是半个汤匙，三味药加起来半汤匙，差不多三比一比三，桔梗三、巴豆一、贝母三，羸者减之，瘦的人还要减半。病在膈上必吐，病在膈下必利。如果不利，再吃热稀饭就好了，不要再吃药，如果利不止，吃冷稀饭就好了，或者是黄连也可以、冷豆浆也可以。如果病人感觉身冷鸡皮疙瘩，这时候不要用水去喷他，休息就好了。如果病人吃了巴豆后肚子痛，重用芍药三两，这时候不要用三钱，用三两，单味的芍药去熬汤吃，就能把巴豆的毒解掉。 《类聚方广义》本条曰：此方不仅治肺痈，就是肺里面化脓疡，且治痈疽，看不到的脓肿、肿块、硬块，胃酸；胃里面化脓长瘤，及胸膈中有顽痰，胸背牵痛者。又咳家胶痰缠扰，咽喉不利，气息有臭者，皆有效。就是结得很盛的时候可以用，但是要确定是寒实，才可以用。卒中风，马脾风，痰潮息迫，牙关紧闭，药汁不入者，取少许吹鼻中，则吐痰涎而咽喉立适。突然中风的时候，痰上来很多，西医在天突的地方开一个洞，牙关紧闭药都进不去，所以药要用喷的，痰从嘴巴、鼻子出来，一下去人就醒过来了，所以三物小白散在用的时候，如果病在胸膈以上一定是吐出来的，如果病在胸膈以下一定是下利的，就是胃以上、食道里面的一定会吐出来，已经下去的全都会排出来。', '2024-11-26T03:52:09.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('21pqO22ioPE', 1, '{"title":"乌梅丸","description":"<p>$u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{蜀椒}$w{四两、炒去汁}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两}</p>\n<p>\t$s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。</p>\n<p></p>\n<p>       乌梅先泡醋泡一个晚上，再用米去蒸，蒸熟后把米跟乌梅捣在一起，和蜜，细辛辣是很辣的，干姜也会辣，蜀椒是专门杀菌的，就是巴椒，蜀椒开口无毒闭口有毒、蜀椒、细辛、干姜都是辛辣的，黄连、黄柏是苦的攻下，炮附、桂枝、干姜是热的，让肠胃热起来，把肠胃的环境改变了，虫才不会生在里面，病人有虫在里面，一定是肠胃虚寒的，所以这时候一定吃人参，把肠胃的虚寒补回来，张仲景在肠胃虚寒的时候一定加人参，本身就已是吸收不好，而食物进去胃里面应该吸收化生成血，结果被虫吃掉了，所以用当归把血再补回去。  </p>\n<p></p>\n<p>吃乌梅丸的时候，禁生冷、滑物、臭食等，因为肠胃已经不好了，再吃这些会又再造虫出来，先食饮，服十丸，就是饭前吃乌梅丸，如果饭后吃乌梅丸，人吃到的是乌梅丸，虫吃到的是饭，所以先后顺序对了，虫下来后，肠胃的环境改变了，肠胃变热了，虫就不能呆在里面了。  </p>\n<p></p>\n<p>        乌梅也主久利，这久利指的是寒利。有时候寒到利有带脓血的时候，脓就是炎，这时候用黄连，黄柏、干姜、细辛、炮附就是在寒利的时候用的。中焦过湿无法化除时、也可用此丸剂，其丸苦温，故能去结实之湿。有些病人一紧张就下利，例如遇到考试的时候就下利，也是乌梅丸证。  </p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":336,"yaoCount":10,"drinkNum":30,"yaoList":["黄柏","人参","桂枝","蜀椒","附子","当归","黄连","干姜","细辛","乌梅"],"fangList":[],"fangYaoList":[{"yaoId":"J7mL6gla0C0","amount":"六两","weight":null,"suffix":"","showName":"黄柏","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"六两","weight":null,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"vVJUANA6k8h","amount":"六两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"切"},{"yaoId":"nP2w4ZP4Yic","amount":"四两、炒去汁","weight":null,"suffix":"","showName":"蜀椒","extraProcess":""},{"yaoId":"GIXSHBaFv0L","amount":"六两","weight":null,"suffix":"","showName":"附子","extraProcess":"炮去皮破八片"},{"yaoId":"MCBshcFNHhk","amount":"四两","weight":null,"suffix":"","showName":"当归","extraProcess":""},{"yaoId":"JMfcgoRTH0J","amount":"一斤","weight":null,"suffix":"","showName":"黄连","extraProcess":""},{"yaoId":"Ro0664U6sTQ","amount":"十两","weight":null,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"FRaBwjHoVui","amount":"六两","weight":null,"suffix":"","showName":"细辛","extraProcess":"切"},{"yaoId":"Ghsn25eutF9","amount":"三百个","weight":null,"suffix":"","showName":"乌梅","extraProcess":""}]}}', '2024-12-02T06:45:43.000Z', '2024-12-02T06:45:43.000Z', '2024-12-02T06:45:43.000Z', '$u{乌梅}$w{三百个}，$u{细辛}$w{六两}，$u{干姜}$w{十两}，$u{黄连}$w{一斤}，$u{当归}$w{四两}，$u{附子}$w{六两，炮}，$u{蜀椒}$w{四两、炒去汁}，$u{桂枝}$w{六两}，$u{人参}$w{六两}，$u{黄柏}$w{六两} $s{右十味}，异捣筛，合治之，以$u{苦酒}渍乌梅一宿，去核，蒸之五升米下，饭熟，捣成泥，和药令相得，内臼中，与$u{蜜}杵二千下，丸如梧子大。先食，饮服十丸，三服，稍加至二十丸。禁生冷滑臭等食。 乌梅先泡醋泡一个晚上，再用米去蒸，蒸熟后把米跟乌梅捣在一起，和蜜，细辛辣是很辣的，干姜也会辣，蜀椒是专门杀菌的，就是巴椒，蜀椒开口无毒闭口有毒、蜀椒、细辛、干姜都是辛辣的，黄连、黄柏是苦的攻下，炮附、桂枝、干姜是热的，让肠胃热起来，把肠胃的环境改变了，虫才不会生在里面，病人有虫在里面，一定是肠胃虚寒的，所以这时候一定吃人参，把肠胃的虚寒补回来，张仲景在肠胃虚寒的时候一定加人参，本身就已是吸收不好，而食物进去胃里面应该吸收化生成血，结果被虫吃掉了，所以用当归把血再补回去。 吃乌梅丸的时候，禁生冷、滑物、臭食等，因为肠胃已经不好了，再吃这些会又再造虫出来，先食饮，服十丸，就是饭前吃乌梅丸，如果饭后吃乌梅丸，人吃到的是乌梅丸，虫吃到的是饭，所以先后顺序对了，虫下来后，肠胃的环境改变了，肠胃变热了，虫就不能呆在里面了。 乌梅也主久利，这久利指的是寒利。有时候寒到利有带脓血的时候，脓就是炎，这时候用黄连，黄柏、干姜、细辛、炮附就是在寒利的时候用的。中焦过湿无法化除时、也可用此丸剂，其丸苦温，故能去结实之湿。有些病人一紧张就下利，例如遇到考试的时候就下利，也是乌梅丸证。', '2024-12-02T06:45:43.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ra5oMGiOc1T', 1, '{"title":"五苓散","description":"<p>$u{猪苓}$w{十八铢、去皮}    $u{泽泻}$w{一两六铢}    $u{白术}$w{十八铢}    $u{茯苓}$w{十八铢}    $u{桂枝}$w{半两、去皮}</p>\n<p>\t上五味。捣为末。以白饮和服方寸匕。日三服。多饮煖水。汗出愈。如法将息。</p>\n<p></p>\n<p>       为末就是打成粉，一次吃一平汤匙，白饮就是很稀的米汤，一天吃三次，吃完后多喝温热水，汗出愈，还有小便会很多。常见病人开中焦肠胃的手术后，病人就会有湿的现象，所以，手术完后病人会有小便不利的现象，这就是五苓散证。  </p>\n<p></p>\n<p>        小孩脑积水也是靠五苓散来利水，西医讲的视网膜有停水，水在上焦，湿疹，都必须用五苓散来利掉的。晕车的时候，横膈膜的积水，用五苓散也很好用，与苓桂朮甘汤主要的不同，是五苓散没有炙甘草，而且一个用散剂，一个是用汤剂。  </p>\n<p></p>\n<p>       《伤寒百问经络图》曰：五苓散又治瘴气温疟，不服水土，黄疸或泻；又治中酒恶心，或呕吐痰水，水入便吐，心下痞闷者；所以过去五苓散用在瘟疟，水土不服就是因为脾脏太湿了，所以身体运化系统受到影响。如果吃当地产的东西，就不会水土不服。  </p>\n<p></p>\n<p>      《三因方》曰：己未年，京师大疫，汗之死，下之死，服五苓散遂愈。此无它，温疫也。  </p>\n<p></p>\n<p>又：五苓散治伏暑饮热，暑气流入经络，壅溢发衄，或胃气虚，血渗入胃，停饮不散， 吐出一二升许。  </p>\n<p></p>\n<p>     《直指》曰：五苓散治湿证小便不利，经曰：治湿之法，不利小便，则非其治。所以湿在中焦以下小便解，中焦以上用吐的，吐了还没有口渴，就表示还有湿在里面，吐了口渴就表示不再用吐法了。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":233,"yaoCount":5,"drinkNum":3,"yaoList":["桂枝","茯苓","白术","泽泻","猪苓"],"fangList":[],"fangYaoList":[{"yaoId":"vVJUANA6k8h","amount":"半两","weight":null,"suffix":"","showName":"桂枝","extraProcess":"去皮"},{"yaoId":"0p1dUWRsS6D","amount":"十八铢","weight":null,"suffix":"","showName":"茯苓","extraProcess":"切"},{"yaoId":"jT011T7yIVO","amount":"十八铢","weight":null,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"k2cI79Wat6h","amount":"一两六铢","weight":null,"suffix":"","showName":"泽泻","extraProcess":"切"},{"yaoId":"ZJN7O318dPD","amount":"十八铢","weight":null,"suffix":"","showName":"猪苓","extraProcess":"去皮"}]}}', '2024-11-23T03:10:58.000Z', '2024-11-23T03:10:58.000Z', '2024-11-23T03:10:58.000Z', '$u{猪苓}$w{十八铢、去皮} $u{泽泻}$w{一两六铢} $u{白术}$w{十八铢} $u{茯苓}$w{十八铢} $u{桂枝}$w{半两、去皮} 上五味。捣为末。以白饮和服方寸匕。日三服。多饮煖水。汗出愈。如法将息。 为末就是打成粉，一次吃一平汤匙，白饮就是很稀的米汤，一天吃三次，吃完后多喝温热水，汗出愈，还有小便会很多。常见病人开中焦肠胃的手术后，病人就会有湿的现象，所以，手术完后病人会有小便不利的现象，这就是五苓散证。 小孩脑积水也是靠五苓散来利水，西医讲的视网膜有停水，水在上焦，湿疹，都必须用五苓散来利掉的。晕车的时候，横膈膜的积水，用五苓散也很好用，与苓桂朮甘汤主要的不同，是五苓散没有炙甘草，而且一个用散剂，一个是用汤剂。 《伤寒百问经络图》曰：五苓散又治瘴气温疟，不服水土，黄疸或泻；又治中酒恶心，或呕吐痰水，水入便吐，心下痞闷者；所以过去五苓散用在瘟疟，水土不服就是因为脾脏太湿了，所以身体运化系统受到影响。如果吃当地产的东西，就不会水土不服。 《三因方》曰：己未年，京师大疫，汗之死，下之死，服五苓散遂愈。此无它，温疫也。 又：五苓散治伏暑饮热，暑气流入经络，壅溢发衄，或胃气虚，血渗入胃，停饮不散， 吐出一二升许。 《直指》曰：五苓散治湿证小便不利，经曰：治湿之法，不利小便，则非其治。所以湿在中焦以下小便解，中焦以上用吐的，吐了还没有口渴，就表示还有湿在里面，吐了口渴就表示不再用吐法了。', '2024-11-23T03:10:58.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7Q8Oowlh5Ki', 1, '{"title":"十枣汤","description":"<p>$u{芫花}$w{(熬)}    $u{甘遂}    $u{大戟}    $u{大枣}$w{十枚(先煮)}</p>\n<p>\t上三味等分、各别捣为散、以水一升半、先煮大枣肥大者十枚、取八合、去滓、纳药末、$a{强人服一钱匕、羸人服半钱、}温服之、$a{平旦服。}若下少病不除者。明日更服。$a{加半钱、}得快下利后、糜粥自养。</p>\n<p></p>\n<p>       能把胸腔下方、横膈膜、肺的下方的水利出来，完全靠甘遂，所以大陷胸汤和大陷胸丸都是对结胸，如果结胸从胃的痞鞕一路往下走，因为比较下面就是大陷胸汤把它攻掉，如同样的结胸在这里但是病往上走，顶到喉咙，脖子都不能弯下来，如果用大陷胸汤就跑太快了，结胸会没有去掉，这时候要改用大陷胸丸，因为丸剂本身是药缓力重，吃大陷胸丸可以因势利导，把它导下来，所以结胸有两种症状，一个从心下往上升的用大陷胸丸，一个从心下往下走的用大陷胸汤，都是以胸膈为主，所以半夏、甘遂一定会用到，甘遂利水利痰的力量非常强。  </p>\n<p></p>\n<p>      如果水渗到脏腑中间的三焦油网的时候，一定要靠大戟才能打通。甘遂利水利痰，去肺中的积水与子宫中的积水，但甘遂还有涤痰的效果，所以大陷胸汤用甘遂。  </p>\n<p></p>\n<p>       肺泡里面都是水的时候用芫花，芫花去除胸腹的积水，所以会用到芫花的病人一定到了但坐不得卧的阶段，就是肺积水不能躺，一躺下去就要喘就再坐起来，吃完十枣汤，三小时就好了。  </p>\n<p></p>\n<p>         这三味药磨粉等量的用，各l／3 钱，一次只给病人一剂，因为这三味药都是碱性的药，胃里面有胃酸，如果光吃这三味药到胃里面，胃就会难过了，所以要靠红枣，过去拿十个红枣去熬，现在大枣比较小，用二三十个浓一点无所谓，红枣汤能中和碱性，且让药发散的力 量很强。  </p>\n<p></p>\n<p>         强人服一钱匕，胖的人用一汤匙，就是喝汤的汤匙一平匙，羸人服半钱，瘦的人用半匙，$m{平旦服}，这就是吃十枣汤的技巧了，一定要早上六点钟吃，五点到七点都可以，因为肺寅大卯胃辰宫，大肠开卯时，肺和大肠相表里，水在上焦的时候，用十枣汤攻下去的时候，病人会上吐下泻，如果有痰，上面吐出来的是痰，如果没有痰，只有水，这水是泻出来的，全部从大便排。病人吃十枣汤后约半小时，开始跑厕所，连续约三小时，中间大概上六七次水才排完，这三味药都是毒药，但是三小时后通通排掉了，若下少者，病不除者，明日更服，加半钱，如果大便三四次，应该下六七次才够，病没有除的，第二天再吃，再加半匙，得快下利后，标准是六次，糜粥自养，这时候喝稀饭，用红枣下去熬稀饭，不能吃油腻食物或肉类，否则会有余热；因为吐了很多，用红枣把胃的津液补足，临床上看到肝病的腹水、脾脏病腹水的时候，也是一样用十枣汤；不可以每天用十枣汤，吃完十枣汤后要调理病人的肠胃，北派的观念只要病人的肠胃功能非常好，吸收的功能非常好病人就不会死。肝病腹水的时候，肚子里面有很多水停在三焦油网脏腑中间，所以大戟加重；如果积水在肺的上方，三剂等量，如果肺积水甘遂多一点；攻出来的水，其实就是人体内的高蛋白的东西，这营养应该给脏腑，结果被水堵到了，这营养一段时间后会坏掉，所以必须把它排掉。  </p>\n<p></p>\n<p>        看到十枣汤的病人，确定没有表证的时候要速攻，不要等到胃气已经没有才攻，十枣汤喝下去结果病人死了，以为是吃到毒药死的。所以要小心麻黄汤证没好变成小青龙汤证，小青龙汤证没好变成十枣汤证。  </p>\n<p></p>\n<p>      《勿误药室方函口诀》本方条曰：据前田长奄之经验，一人之手肿，余处不肿，元气饮食如故，用此方，经水泻而速愈，亦别开生面法也。其实只有手肿用不到十枣汤的，此说过于牵强。  </p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":260,"yaoCount":4,"drinkNum":2,"yaoList":["大戟","甘遂","芫花","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"DOm33cnbr2V","amount":"1／3 钱","weight":null,"suffix":"","showName":"大戟","extraProcess":""},{"yaoId":"1rOkrjGOCab","amount":"1／3 钱","weight":null,"suffix":"","showName":"甘遂","extraProcess":""},{"yaoId":"gZLQX87OyZG","amount":"1／3 钱","weight":null,"suffix":"","showName":"芫花","extraProcess":""},{"yaoId":"VcvhqvKkSct","amount":"肥大者十枚","weight":null,"suffix":"","showName":"大枣","extraProcess":""}]}}', '2024-11-26T07:45:30.000Z', '2024-11-26T07:45:30.000Z', '2024-11-26T07:45:30.000Z', '$u{芫花}$w{(熬)} $u{甘遂} $u{大戟} $u{大枣}$w{十枚(先煮)} 上三味等分、各别捣为散、以水一升半、先煮大枣肥大者十枚、取八合、去滓、纳药末、$a{强人服一钱匕、羸人服半钱、}温服之、$a{平旦服。}若下少病不除者。明日更服。$a{加半钱、}得快下利后、糜粥自养。 能把胸腔下方、横膈膜、肺的下方的水利出来，完全靠甘遂，所以大陷胸汤和大陷胸丸都是对结胸，如果结胸从胃的痞鞕一路往下走，因为比较下面就是大陷胸汤把它攻掉，如同样的结胸在这里但是病往上走，顶到喉咙，脖子都不能弯下来，如果用大陷胸汤就跑太快了，结胸会没有去掉，这时候要改用大陷胸丸，因为丸剂本身是药缓力重，吃大陷胸丸可以因势利导，把它导下来，所以结胸有两种症状，一个从心下往上升的用大陷胸丸，一个从心下往下走的用大陷胸汤，都是以胸膈为主，所以半夏、甘遂一定会用到，甘遂利水利痰的力量非常强。 如果水渗到脏腑中间的三焦油网的时候，一定要靠大戟才能打通。甘遂利水利痰，去肺中的积水与子宫中的积水，但甘遂还有涤痰的效果，所以大陷胸汤用甘遂。 肺泡里面都是水的时候用芫花，芫花去除胸腹的积水，所以会用到芫花的病人一定到了但坐不得卧的阶段，就是肺积水不能躺，一躺下去就要喘就再坐起来，吃完十枣汤，三小时就好了。 这三味药磨粉等量的用，各l／3 钱，一次只给病人一剂，因为这三味药都是碱性的药，胃里面有胃酸，如果光吃这三味药到胃里面，胃就会难过了，所以要靠红枣，过去拿十个红枣去熬，现在大枣比较小，用二三十个浓一点无所谓，红枣汤能中和碱性，且让药发散的力 量很强。 强人服一钱匕，胖的人用一汤匙，就是喝汤的汤匙一平匙，羸人服半钱，瘦的人用半匙，$m{平旦服}，这就是吃十枣汤的技巧了，一定要早上六点钟吃，五点到七点都可以，因为肺寅大卯胃辰宫，大肠开卯时，肺和大肠相表里，水在上焦的时候，用十枣汤攻下去的时候，病人会上吐下泻，如果有痰，上面吐出来的是痰，如果没有痰，只有水，这水是泻出来的，全部从大便排。病人吃十枣汤后约半小时，开始跑厕所，连续约三小时，中间大概上六七次水才排完，这三味药都是毒药，但是三小时后通通排掉了，若下少者，病不除者，明日更服，加半钱，如果大便三四次，应该下六七次才够，病没有除的，第二天再吃，再加半匙，得快下利后，标准是六次，糜粥自养，这时候喝稀饭，用红枣下去熬稀饭，不能吃油腻食物或肉类，否则会有余热；因为吐了很多，用红枣把胃的津液补足，临床上看到肝病的腹水、脾脏病腹水的时候，也是一样用十枣汤；不可以每天用十枣汤，吃完十枣汤后要调理病人的肠胃，北派的观念只要病人的肠胃功能非常好，吸收的功能非常好病人就不会死。肝病腹水的时候，肚子里面有很多水停在三焦油网脏腑中间，所以大戟加重；如果积水在肺的上方，三剂等量，如果肺积水甘遂多一点；攻出来的水，其实就是人体内的高蛋白的东西，这营养应该给脏腑，结果被水堵到了，这营养一段时间后会坏掉，所以必须把它排掉。 看到十枣汤的病人，确定没有表证的时候要速攻，不要等到胃气已经没有才攻，十枣汤喝下去结果病人死了，以为是吃到毒药死的。所以要小心麻黄汤证没好变成小青龙汤证，小青龙汤证没好变成十枣汤证。 《勿误药室方函口诀》本方条曰：据前田长奄之经验，一人之手肿，余处不肿，元气饮食如故，用此方，经水泻而速愈，亦别开生面法也。其实只有手肿用不到十枣汤的，此说过于牵强。', '2024-11-26T07:45:30.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y1pFPp7a57f', 1, '{"title":"半夏散及汤","description":"<p>$u{半夏}$w{(洗)}    $u{桂枝}$w{去皮}    $u{甘草}$w{炙}   以上各等分  </p>\n<p> 以上三味，各别捣筛已，合治之，白饮和，服方寸匕，日三服，若不能散服者，以水一升，煎七沸，内散两方寸匕，更煎三沸，下火令小冷，少少咽之。  </p>\n<p></p>\n<p>      这就是少阴证的喉痛，少阴证的时候本身又有中风，本来少阴证得到了一段时间，津液本来就不足了，因为里面阴虚很盛，没有办法有正常的津液给喉咙，这时候用桂枝来去风，用甘草、半夏，这就是有少阴证的同时得到有表证的时候用的，就是带有伤寒感冒的时候用的，这三味等分，白饮就是米汤，不能服散用汤剂也可以。  </p>\n<p></p>\n<p>      《勿误药室方函口诀》本方条曰：此方宜于冬时中寒，咽喉疼痛者，虽有发热、恶寒、可治。然此证冬时为多。又后世所谓火喉癣证，上焦有虚热，而喉头烂，痛苦不堪，饮食不能下咽，用甘桔汤及其它诸治喉痛药无寸效者，用之一旦而有效；临证上，严重到吞不下去了用苦酒汤，如果本身是少阴证还兼有伤寒的表证，所以摸脉很重要，少阴证的人脉很虚弱，就是这人里虚了，里虚就是肠胃功能没有吸收，病人很虚弱，这时候得到的喉咙痛，一定是虚火，不是实火，实火用黄连、黄芩等消炎的药，虚火就不能用。</p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":300,"yaoCount":3,"drinkNum":1,"yaoList":["甘草","桂枝","半夏"],"fangList":[],"fangYaoList":[{"yaoId":null,"amount":"等量","weight":null,"suffix":"","showName":"甘草","extraProcess":""},{"yaoId":"vVJUANA6k8h","amount":"等量","weight":null,"suffix":"","showName":"桂枝","extraProcess":""},{"yaoId":"JZ9gTmGblYB","amount":"等量","weight":null,"suffix":"","showName":"半夏","extraProcess":""}]}}', '2024-11-30T08:57:42.000Z', '2024-11-30T08:57:42.000Z', '2024-11-30T08:57:42.000Z', '$u{半夏}$w{(洗)} $u{桂枝}$w{去皮} $u{甘草}$w{炙} 以上各等分 以上三味，各别捣筛已，合治之，白饮和，服方寸匕，日三服，若不能散服者，以水一升，煎七沸，内散两方寸匕，更煎三沸，下火令小冷，少少咽之。 这就是少阴证的喉痛，少阴证的时候本身又有中风，本来少阴证得到了一段时间，津液本来就不足了，因为里面阴虚很盛，没有办法有正常的津液给喉咙，这时候用桂枝来去风，用甘草、半夏，这就是有少阴证的同时得到有表证的时候用的，就是带有伤寒感冒的时候用的，这三味等分，白饮就是米汤，不能服散用汤剂也可以。 《勿误药室方函口诀》本方条曰：此方宜于冬时中寒，咽喉疼痛者，虽有发热、恶寒、可治。然此证冬时为多。又后世所谓火喉癣证，上焦有虚热，而喉头烂，痛苦不堪，饮食不能下咽，用甘桔汤及其它诸治喉痛药无寸效者，用之一旦而有效；临证上，严重到吞不下去了用苦酒汤，如果本身是少阴证还兼有伤寒的表证，所以摸脉很重要，少阴证的人脉很虚弱，就是这人里虚了，里虚就是肠胃功能没有吸收，病人很虚弱，这时候得到的喉咙痛，一定是虚火，不是实火，实火用黄连、黄芩等消炎的药，虚火就不能用。', '2024-11-30T08:57:42.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y4zqZGi5E7A', 1, '{"title":"半夏泻心汤","description":"<p>$u{半夏}$w{半升(洗)}    $u{黄芩}    $u{干姜}    $u{人参}    $u{甘草}$w{炙各三两}    $u{黄连}$w{一两}    $u{大枣}$w{十二枚、擘}</p>\n<p>        右七味,以水一斗,煮取六升,去滓,再煮取三升,温服一升,日三服。</p>\n<p></p>\n<p>    这半夏泻心汤为什么用干姜?因为胃旁边有水，造成胃寒掉了，所以用干姜，如果胃中有水的话用生姜，干姜是温中的药；</p>\n<p>张仲景需要用到肠胃的津液的时候，一定会开到人参、干姜、甘草、大枣、生姜，所以肠胃的津液要补足，就一定会用到甘草、大枣、人参。</p>\n<p>    有寒证的时候、需要$m{强心的时候我们用炙甘草}，要$n{解毒的时候用生甘草}，生甘草还有蓄水的功能，也就是用了人参补津液之后，以生甘草把津液留在肠胃中。人参在经方家的观念是治疗心下痞，胃里面不舒服、胃痛的，人参是最好的药，不是拿来当茶喝，不需要如此用；因为胃里面坏死的食物，产生了沼气往上走，黄芩、黄连把坏死的食物分解掉，这胃病的肇因是水没有去掉，所以用半夏把水利掉。</p>\n<p></p>\n<p>        临床上看的时候，有一点感冒自己不知道。知道的时候叫伤寒，不知道的叫中风，然后病人吃坏肚子的上吐下泻，拉出来的都是水，肚子咕咕的肠鸣，就是半夏泻心汤证，用半夏止呕利水，黄连、黄芩去把肠子食物分解掉。黄连解血分中热毒，黄芩解肝胆三焦的热毒，因为上吐下泄所以胃的津液都伤到了，所以把人参、干姜、甘草、大枣混在里面用，张仲景的方剂就是这意思，所有的痞都是肠胃科的问题。这个方剂用汤剂或散剂都可以。  </p>\n<p></p>\n<p>      舌苔代表胃的津液，如果舌苔黄，代表有热，如果舌苔黄但不是非常干燥，就是用黄芩黄连；如果是舌苔黄而且非常干燥，就是用石膏。  </p>\n<p></p>\n<p></p>\n<p>《金鉴》曰：结胸兼阳明里实者，大陷胸汤证也；结胸证病人一定没有下利的，所以有结胸的现象兼有大便堵到的现象，一定是大陷胸汤证；兼阳明不成实者，小陷胸汤证也；结胸证，但是大便还是通的就是小陷胸汤证，都是结胸的症状，就是胃里面很难过，绷得很紧，筋挛的现象。痞鞕兼少阳里实证者，是大柴胡汤证，胃里面很难过，硬硬的，然后大便稍微不通，没有结胸那么厉害，就是大柴胡汤证，兼少阳里不成实者，半夏泻心汤也，里不成实者，就是下利拉很多水出来，这时候靠半夏泻心汤。这种虚症的现象常常在食物中毒、误食  </p>\n<p>不干净的东西的时候，开半夏泻心汤给病人吃，半夏泻心汤的时候病人一定有呕吐、下利兼有肠鸣，所以有呕吐就是半夏泻心汤。  </p>\n<p></p>\n<p>《芳翁医谈》曰：休息痢，世皆以为难治，盖亦秽物不尽，宜服笃落丸，（笃落丸为大黄一味之丸方。）光吃大黄一味药，会拉的很难过，笃落丸就是笃定会落下来，这样吃不好。又：下利如休息痢，无脓血，惟水泻，时或自止，止则腹胀，泻如爽然，然日羸惫，面色萎 黄，恶心吞酸，有时腹自痛，当与半夏泻心汤，没有拉血，拉出来都是水，停止没拉，肚于就胀起来，拉完后肚子就舒服了，面色就越来越疲惫，又恶心又吐酸，东西吃不下去。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":259,"yaoCount":7,"drinkNum":3,"yaoList":["大枣","黄连","人参","干姜","黄芩","半夏","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"VcvhqvKkSct","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"JMfcgoRTH0J","amount":"一两","weight":null,"suffix":"","showName":"黄连","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"Ro0664U6sTQ","amount":"三两","weight":null,"suffix":"","showName":"干姜","extraProcess":"切"},{"yaoId":"To31b37bc6Z","amount":"三两","weight":null,"suffix":"","showName":"黄芩","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"半升","weight":null,"suffix":"","showName":"半夏","extraProcess":"洗"},{"yaoId":null,"amount":"三两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"}]}}', '2024-11-26T06:51:32.000Z', '2024-11-26T06:51:32.000Z', '2024-11-26T06:51:32.000Z', '$u{半夏}$w{半升(洗)} $u{黄芩} $u{干姜} $u{人参} $u{甘草}$w{炙各三两} $u{黄连}$w{一两} $u{大枣}$w{十二枚、擘} 右七味,以水一斗,煮取六升,去滓,再煮取三升,温服一升,日三服。 这半夏泻心汤为什么用干姜?因为胃旁边有水，造成胃寒掉了，所以用干姜，如果胃中有水的话用生姜，干姜是温中的药； 张仲景需要用到肠胃的津液的时候，一定会开到人参、干姜、甘草、大枣、生姜，所以肠胃的津液要补足，就一定会用到甘草、大枣、人参。 有寒证的时候、需要$m{强心的时候我们用炙甘草}，要$n{解毒的时候用生甘草}，生甘草还有蓄水的功能，也就是用了人参补津液之后，以生甘草把津液留在肠胃中。人参在经方家的观念是治疗心下痞，胃里面不舒服、胃痛的，人参是最好的药，不是拿来当茶喝，不需要如此用；因为胃里面坏死的食物，产生了沼气往上走，黄芩、黄连把坏死的食物分解掉，这胃病的肇因是水没有去掉，所以用半夏把水利掉。 临床上看的时候，有一点感冒自己不知道。知道的时候叫伤寒，不知道的叫中风，然后病人吃坏肚子的上吐下泻，拉出来的都是水，肚子咕咕的肠鸣，就是半夏泻心汤证，用半夏止呕利水，黄连、黄芩去把肠子食物分解掉。黄连解血分中热毒，黄芩解肝胆三焦的热毒，因为上吐下泄所以胃的津液都伤到了，所以把人参、干姜、甘草、大枣混在里面用，张仲景的方剂就是这意思，所有的痞都是肠胃科的问题。这个方剂用汤剂或散剂都可以。 舌苔代表胃的津液，如果舌苔黄，代表有热，如果舌苔黄但不是非常干燥，就是用黄芩黄连；如果是舌苔黄而且非常干燥，就是用石膏。 《金鉴》曰：结胸兼阳明里实者，大陷胸汤证也；结胸证病人一定没有下利的，所以有结胸的现象兼有大便堵到的现象，一定是大陷胸汤证；兼阳明不成实者，小陷胸汤证也；结胸证，但是大便还是通的就是小陷胸汤证，都是结胸的症状，就是胃里面很难过，绷得很紧，筋挛的现象。痞鞕兼少阳里实证者，是大柴胡汤证，胃里面很难过，硬硬的，然后大便稍微不通，没有结胸那么厉害，就是大柴胡汤证，兼少阳里不成实者，半夏泻心汤也，里不成实者，就是下利拉很多水出来，这时候靠半夏泻心汤。这种虚症的现象常常在食物中毒、误食 不干净的东西的时候，开半夏泻心汤给病人吃，半夏泻心汤的时候病人一定有呕吐、下利兼有肠鸣，所以有呕吐就是半夏泻心汤。 《芳翁医谈》曰：休息痢，世皆以为难治，盖亦秽物不尽，宜服笃落丸，（笃落丸为大黄一味之丸方。）光吃大黄一味药，会拉的很难过，笃落丸就是笃定会落下来，这样吃不好。又：下利如休息痢，无脓血，惟水泻，时或自止，止则腹胀，泻如爽然，然日羸惫，面色萎 黄，恶心吞酸，有时腹自痛，当与半夏泻心汤，没有拉血，拉出来都是水，停止没拉，肚于就胀起来，拉完后肚子就舒服了，面色就越来越疲惫，又恶心又吐酸，东西吃不下去。', '2024-11-26T06:51:32.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5y7X6qDwWce', 1, '{"title":"厚朴生姜半夏甘草人参汤","description":"<p>$u{厚朴}$w{半斤(炙、去皮)}    $u{生姜}$w{半斤、切}    $u{半夏}$w{半升(洗)}    $u{甘草}$w{二两}    $u{人参}$w{一两}</p>\n<p>\t上五味、以水一斗、煮取三升、去滓、温服一升、日三服。</p>\n<p>       厚朴用三四钱，就不得了了，生姜开三片就好了，生半夏胖子开三钱，普通开二钱，害他的话，半夏拿掉；人参一钱；平常炙甘草不开多，一二钱就够了，后面的炙甘草汤开到五钱一两都有，那是需要，这里不用开太重，因为炙甘草很甜，会增腻。  </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":229,"yaoCount":5,"drinkNum":3,"yaoList":["人参","半夏","甘草","生姜","厚朴"],"fangList":[],"fangYaoList":[{"yaoId":"VHE7Y68l232","amount":"一两","weight":null,"suffix":"","showName":"人参","extraProcess":"切"},{"yaoId":"JZ9gTmGblYB","amount":"二两","weight":null,"suffix":"","showName":"半夏","extraProcess":"炙"},{"yaoId":null,"amount":"半升","weight":null,"suffix":"","showName":"甘草","extraProcess":"洗"},{"yaoId":"7S7n1dzieYK","amount":"半斤","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"S7mhkBtEhPL","amount":"半斤","weight":null,"suffix":"","showName":"厚朴","extraProcess":"炙去皮"}]}}', '2024-11-23T01:58:11.000Z', '2024-11-23T01:58:11.000Z', '2024-11-23T01:58:11.000Z', '$u{厚朴}$w{半斤(炙、去皮)} $u{生姜}$w{半斤、切} $u{半夏}$w{半升(洗)} $u{甘草}$w{二两} $u{人参}$w{一两} 上五味、以水一斗、煮取三升、去滓、温服一升、日三服。 厚朴用三四钱，就不得了了，生姜开三片就好了，生半夏胖子开三钱，普通开二钱，害他的话，半夏拿掉；人参一钱；平常炙甘草不开多，一二钱就够了，后面的炙甘草汤开到五钱一两都有，那是需要，这里不用开太重，因为炙甘草很甜，会增腻。', '2024-11-23T01:58:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8W50L9BqngI', 1, '{"title":"去桂加白术汤","description":"<p>$u{附子}$w{三枚、炮、去皮、破}    $u{白术}$w{四两}    $u{生姜}$w{三两、切}    $u{大枣}$w{十二枚、擘}    $u{甘草}$w{二两、炙}</p>\n<p></p>\n<p>    右五味，以水六升，煮取二升，去滓，分温三服。初服其人身如痹，半日许，复服之，三服尽，其人如冒状，勿怪；此以附子、术并走皮内，逐水气未得除，故使之尔，法当加桂枝四两，$n{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。}</p>\n<p></p>\n<p>     桂枝附子汤和去桂枝加白朮汤同样有生姜、炙甘草、大枣，其余的桂枝附子汤有桂枝和附子，去桂枝加白朮汤有白朮和附子，桂枝附子汤是用在病人有伤寒表证兼有湿证的时候用，所以他浑身关节痛，这时候用桂枝去风，靠附子去湿，附子行走速度很快；如果病人没有表证，只是全身关节酸痛，没有浮脉，就没有表证，大便比较稀，小便很正常，就是湿往大肠走了，这就是脾脏太湿了，肠子的黏液很多是从脾来的，湿很盛的时候，就顺着肠壁出来了，和小便没关系，所以不管排尿系统，管肠就好了，这时候用白朮，因为白朮专门去脾湿的，如果这药没有加附子的话，就光把脾脏的湿去掉了，不能去掉关节的湿，因为附子走表，附子把白朮带到四肢关节，把四肢关节的湿去掉。  </p>\n<p></p>\n<p>       初服其人身如痹，刚开始服的时候，全身关节麻痹，因为附子走表，半日许，差不多十二小时以后再吃一碗，其人如冒状，头有昏眩的现象，勿怪；此以附子、朮并走皮内，不用生姜、甘草、大枣，光用附子、白朮就是朮附汤，  </p>\n<p></p>\n<p>        朮附汤发脓急救用的，把身体里面的脓疮发出来的，现在加生姜、甘草、大枣，就是让它从脾脏到肌肉到关节，脾主四肢。顺着脾经走到关节里面把湿去掉，如果逐水气未得除，故使之尔，因为水气还没有办法完全去，所以附子在皮肤上走的时候，慢慢吸收水气，病人会头昏，当加桂枝四两，此本一方两法也，可以加桂枝，加不加都可以，这是一个处方、两个方法；一般性的风湿就可以用这二个方子，有表证的用桂枝附子汤，没表证的用白朮附子汤。第三个方子就是治疗痛风。  </p>\n<p></p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":272,"yaoCount":5,"drinkNum":3,"yaoList":["附子","白术","生姜","甘草","大枣"],"fangList":[],"fangYaoList":[{"yaoId":"GIXSHBaFv0L","amount":"三枚","weight":null,"suffix":"","showName":"附子","extraProcess":"炮去皮破八片"},{"yaoId":"jT011T7yIVO","amount":"四两","weight":null,"suffix":"","showName":"白术","extraProcess":"切"},{"yaoId":"7S7n1dzieYK","amount":"三两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":null,"amount":"二两","weight":null,"suffix":"","showName":"甘草","extraProcess":"炙"},{"yaoId":"VcvhqvKkSct","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"}]}}', '2024-11-27T03:04:29.000Z', '2024-11-27T03:04:29.000Z', '2024-11-27T03:04:29.000Z', '$u{附子}$w{三枚、炮、去皮、破} $u{白术}$w{四两} $u{生姜}$w{三两、切} $u{大枣}$w{十二枚、擘} $u{甘草}$w{二两、炙} 右五味，以水六升，煮取二升，去滓，分温三服。初服其人身如痹，半日许，复服之，三服尽，其人如冒状，勿怪；此以附子、术并走皮内，逐水气未得除，故使之尔，法当加桂枝四两，$n{此本一方二法：以大便硬。小便自利。去桂也。以大不便硬。小便不利。当加桂。附子三枚恐多也。虚弱及产妇宜减之。} 桂枝附子汤和去桂枝加白朮汤同样有生姜、炙甘草、大枣，其余的桂枝附子汤有桂枝和附子，去桂枝加白朮汤有白朮和附子，桂枝附子汤是用在病人有伤寒表证兼有湿证的时候用，所以他浑身关节痛，这时候用桂枝去风，靠附子去湿，附子行走速度很快；如果病人没有表证，只是全身关节酸痛，没有浮脉，就没有表证，大便比较稀，小便很正常，就是湿往大肠走了，这就是脾脏太湿了，肠子的黏液很多是从脾来的，湿很盛的时候，就顺着肠壁出来了，和小便没关系，所以不管排尿系统，管肠就好了，这时候用白朮，因为白朮专门去脾湿的，如果这药没有加附子的话，就光把脾脏的湿去掉了，不能去掉关节的湿，因为附子走表，附子把白朮带到四肢关节，把四肢关节的湿去掉。 初服其人身如痹，刚开始服的时候，全身关节麻痹，因为附子走表，半日许，差不多十二小时以后再吃一碗，其人如冒状，头有昏眩的现象，勿怪；此以附子、朮并走皮内，不用生姜、甘草、大枣，光用附子、白朮就是朮附汤， 朮附汤发脓急救用的，把身体里面的脓疮发出来的，现在加生姜、甘草、大枣，就是让它从脾脏到肌肉到关节，脾主四肢。顺着脾经走到关节里面把湿去掉，如果逐水气未得除，故使之尔，因为水气还没有办法完全去，所以附子在皮肤上走的时候，慢慢吸收水气，病人会头昏，当加桂枝四两，此本一方两法也，可以加桂枝，加不加都可以，这是一个处方、两个方法；一般性的风湿就可以用这二个方子，有表证的用桂枝附子汤，没表证的用白朮附子汤。第三个方子就是治疗痛风。', '2024-11-27T03:04:29.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kKVV55GDeOm', 1, '{"title":"吴茱萸汤","description":"<p>$u{吴茱萸}$w{一升}，$u{人参}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚}</p>\n<p>\t$s{右四味}，以水五升，煮取三升。温服七合，日三服。</p>\n<p></p>\n<p>  吴茱萸用三钱，重证的时候可以用到五钱，人参、生姜、大枣酌量的用。</p>\n<p></p>\n<p>《肘后方》曰：一方（即本方）治人食毕噫醋及醋心（即食后吞酸嘈杂也）。  </p>\n<p></p>\n<p> 张元素曰：吴茱萸汤其用有三：去胸中之逆气满塞，止心腹寒感疼痛，及消宿酒。早上宿醉未醒，可以用吴茱萸汤，吴茱萸汤对酒客病非常的好。</p>\n<p></p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":284,"yaoCount":4,"drinkNum":3,"yaoList":["大枣","生姜","人参","吴茱萸"],"fangList":[],"fangYaoList":[{"yaoId":"VcvhqvKkSct","amount":"十二枚","weight":null,"suffix":"","showName":"大枣","extraProcess":"擘"},{"yaoId":"7S7n1dzieYK","amount":"六两","weight":null,"suffix":"","showName":"生姜","extraProcess":"切"},{"yaoId":"VHE7Y68l232","amount":"三两","weight":null,"suffix":"","showName":"人参","extraProcess":"去节"},{"yaoId":"PLFElISYWYO","amount":"一升","weight":null,"suffix":"","showName":"吴茱萸","extraProcess":""}]}}', '2024-11-29T02:44:11.000Z', '2024-11-29T02:44:11.000Z', '2024-11-29T02:44:11.000Z', '$u{吴茱萸}$w{一升}，$u{人参}$w{三两}，$u{生姜}$w{六两}，$u{大枣}$w{十二枚} $s{右四味}，以水五升，煮取三升。温服七合，日三服。 吴茱萸用三钱，重证的时候可以用到五钱，人参、生姜、大枣酌量的用。 《肘后方》曰：一方（即本方）治人食毕噫醋及醋心（即食后吞酸嘈杂也）。 张元素曰：吴茱萸汤其用有三：去胸中之逆气满塞，止心腹寒感疼痛，及消宿酒。早上宿醉未醒，可以用吴茱萸汤，吴茱萸汤对酒客病非常的好。', '2024-11-29T02:44:11.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D8CgKp97d34', 1, '{"title":"四逆散","description":"<p>$u{甘草}$w{炙}    $u{枳实}$w{(破、水渍、炙干)}    $u{芍药}    $u{柴胡}</p>\n<p>\t右四味，各十分，捣筛，白饮合服方寸匕，日三服。</p>\n<p></p>\n<p>     咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。</p>\n<p>     悸者。加$u{桂枝}$w{五分}。</p>\n<p>     小便不利者。加$u{茯苓}$w{五分}。</p>\n<p>     腹中痛者。加$u{附子}$w{一枚、炮令坼}。</p>\n<p>     泄利下重者。先以水五升。煮$u{薤白}$w{三升}、去滓、以散三方寸匕、内汤中、煮取一升半、分温再服。</p>\n<p></p>\n<p>       薤白这药，本身能开肺，肺气一开的时候下就通了，因为肺和大肠相表里的，所以有的人便秘吃承气汤没有用，实际上是肺气没有打开来，思能伤脾，忧能伤肺，常担心的人相会改变。眉毛下方会看到白色的，眉底的肉会变成白色的，所以肺病的人可以看到白色，眉毛和肺有关系，眉毛只剩几根的空壳子，外表穿的很华丽，相书里面看眉毛很稀落的人，代表这人里面一无所有，所以掉眉毛和掉头发不一样，头发主肾，所以如果能让忧虑去掉，让肺开开来，就能让眉毛长回来，眉毛很长的代表长寿，所以要保持平常心。  </p>\n<p></p>\n<p>      如果是肌肉里面血堵到了，被打伤，肌肉里面淤血的时候用桂枝汤加桃仁，如果是打到内部、肠胃的地方、三焦网络的内伤，就用四逆散来作加减。 </p>\n<p> </p>","content_format":"html","_microfeed":{"bookId":"tcmfang0001","sourceBookId":"XNK0VFX39Xv","no":335,"yaoCount":4,"drinkNum":3,"yaoList":["柴胡","芍药","枳实","甘草"],"fangList":[],"fangYaoList":[{"yaoId":"B2o1hdSD6X1","amount":"十分","weight":null,"suffix":"","showName":"柴胡","extraProcess":"切"},{"yaoId":"axI8tfBmKAx","amount":"十分","weight":null,"suffix":"","showName":"芍药","extraProcess":"切"},{"yaoId":"fd3riAoOlLa","amount":"十分","weight":null,"suffix":"","showName":"枳实","extraProcess":""},{"yaoId":null,"amount":"十分","weight":null,"suffix":"","showName":"甘草","extraProcess":"切"}]}}', '2024-12-02T03:29:57.000Z', '2024-12-02T03:29:57.000Z', '2024-12-02T03:29:57.000Z', '$u{甘草}$w{炙} $u{枳实}$w{(破、水渍、炙干)} $u{芍药} $u{柴胡} 右四味，各十分，捣筛，白饮合服方寸匕，日三服。 咳者。加$u{五味子}、$u{干姜}$w{各五分}。并主下利。 悸者。加$u{桂枝}$w{五分}。 小便不利者。加$u{茯苓}$w{五分}。 腹中痛者。加$u{附子}$w{一枚、炮令坼}。 泄利下重者。先以水五升。煮$u{薤白}$w{三升}、去滓、以散三方寸匕、内汤中、煮取一升半、分温再服。 薤白这药，本身能开肺，肺气一开的时候下就通了，因为肺和大肠相表里的，所以有的人便秘吃承气汤没有用，实际上是肺气没有打开来，思能伤脾，忧能伤肺，常担心的人相会改变。眉毛下方会看到白色的，眉底的肉会变成白色的，所以肺病的人可以看到白色，眉毛和肺有关系，眉毛只剩几根的空壳子，外表穿的很华丽，相书里面看眉毛很稀落的人，代表这人里面一无所有，所以掉眉毛和掉头发不一样，头发主肾，所以如果能让忧虑去掉，让肺开开来，就能让眉毛长回来，眉毛很长的代表长寿，所以要保持平常心。 如果是肌肉里面血堵到了，被打伤，肌肉里面淤血的时候用桂枝汤加桃仁，如果是打到内部、肠胃的地方、三焦网络的内伤，就用四逆散来作加减。', '2024-12-02T03:29:57.000Z', 1, NULL, 'tcmfang0001', 'fang', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vVJUANA6k8h', 1, '{"title":"甘草","description":"<p>1、$u{甘草}</p>\r\n<p>$q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。</p>\r\n<p>$q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":0,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '1、$u{甘草} $q{《神农本草经》}：【甘草】味甘。平。主治五藏六府寒热邪气。坚筋骨。长肌肉。倍力。金疮。尰。解毒。久服轻身。延年。生河西川谷。 $q{《名医别录》}：【甘草】无毒。主温中。下气。烦满。短气。伤藏。咳嗽。止渴。通经脉。利血气。解百药毒。为九土之精。安和七十二种石。一千二百种草。一名蜜甘。一名美草。一名蜜草。一名蕗。生河西积沙山及上郡。二月八月除日采根。暴干。十日成。（术干漆苦参为之使。远志。反大戟芫花甘遂海藻。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7S7n1dzieYK', 1, '{"title":"桂枝","description":"<p>2、$u{桂枝}</p>\n<p>$q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。</p>\n<p></p>\n<p>$q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。</p>\n<p></p>\n<p>$q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。</p>\n<p></p>\n<p>$q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":1,"yaoNames":"","aliases":[{"bieming":"桂","name":"桂枝"},{"bieming":"桂心","name":"桂枝"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2、$u{桂枝} $q{《神农本草经》}：【牡桂】味辛。温。主治上气咳逆。结气。喉痹。吐吸。利关节。补中益气。久服通神。轻身。不老。生南海山谷。 $q{《名医别录》}：【牡桂】无毒。主治心痛。胁风。胁痛。温筋通脉。止烦。出汗。生南海。 $q{《神农本草经》}：【箘桂】味辛。温。主治百疾。养精神。和颜色。为诸药先聘通使。久服轻身。不老。面生光华媚好。常如童子。生交址桂林山谷。 $q{《名医别录》}：【菌桂】无毒。生交趾桂林山谷岩崖间。无骨。正圆如竹。立秋采。 $q{《名医别录》}：【桂】味甘辛。大热。有毒。主温中。利肝肺气。心腹寒热。冷疾。霍乱。转筋。头痛。腰痛。出汗。止烦。止唾咳嗽鼻齆。能堕胎。坚骨节。通血脉。理疏不足。宣导百药。无所畏。久服神仙。不老。生桂阳。二月七八月十月采皮。阴干。（得人参麦门冬甘草大黄黄芩调中益气。得柴胡紫石英干地黄治吐逆。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VcvhqvKkSct', 1, '{"title":"生姜","description":"<p>3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。]</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":2,"yaoNames":"","aliases":[{"bieming":"生姜汁","name":"生姜"},{"bieming":"姜","name":"生姜"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '3、$u{生姜}[本经未录生姜，仅于干姜条言生者尤良。] $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【生姜】味辛。微温。主治伤寒头痛鼻塞。咳逆上气。止呕吐。生犍为及荆州扬州。九月采。又【生姜】微温。辛。归五藏。去淡。下气。止呕吐。除风邪寒热。久服小志少智。伤心气。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JZ9gTmGblYB', 1, '{"title":"大枣","description":"<p>4、$u{大枣}</p>\r\n<p>$q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。</p>\r\n<p>$q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":3,"yaoNames":"","aliases":[{"bieming":"枣","name":"大枣"},{"bieming":"枣膏","name":"大枣"},{"bieming":"枣肉","name":"大枣"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '4、$u{大枣} $q{《神农本草经》}：【大枣】味甘。平。主治心腹邪气。安中。养脾。助十二经。平胃气。通九窍。补少气少津。身中不足。大惊。四肢重。和百药。久服轻身长年。【叶】覆麻黄。能出汗。生河东平泽。 $q{《名医别录》}：【大枣】无毒。补中益气。强力。除烦闷。治心下悬肠澼澼。久服不饥神仙。一名干枣。一名美枣。一名良枣。八月采。暴干。【三岁陈核中仁】燔之。味苦。主治腹痛邪气。【生枣】味甘辛。多食令人多寒热。羸瘦者。不可食。生河东。（杀乌头毒。）又【枣叶】散服使人瘦。久即呕吐。揩热疿疮至良。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('axI8tfBmKAx', 1, '{"title":"半夏","description":"<p>5、$u{半夏}</p>\r\n<p>$q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。</p>\r\n<p>$q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":4,"yaoNames":"地文,水玉,守,示姑","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '5、$u{半夏} $q{《神农本草经》}：【半夏】味辛。平。主治伤寒寒热。心下坚。下气。喉咽肿痛。头眩。胸胀。咳逆。肠鸣。止汗。一名地文。一名水玉。生槐里川谷。 $q{《名医别录》}：【半夏】生微寒熟温。有毒。主消心腹胸中膈痰热满结。咳嗽上气。心下急痛坚痞。时气呕逆。消痈肿。胎堕。治萎黄。悦泽面目。生令人吐。熟令人下。用之汤洗。令滑尽。一名守。一名示姑。生槐里。五月八月采根。暴干。（射干为之使。恶皂荚。畏雄黄生姜干姜秦皮龟甲。反乌头。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ro0664U6sTQ', 1, '{"title":"芍药","description":"<p>6、$u{芍药}</p>\r\n<p>$q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。</p>\r\n<p>$q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":5,"yaoNames":"白木,余容,犁食,解仓,铤","aliases":[{"bieming":"白芍药","name":"芍药"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '6、$u{芍药} $q{《神农本草经》}：【芍药】味苦。平。主治邪气腹痛。除血痹。破坚积。寒热。疝瘕。止痛。利小便。益气。生中岳川谷。 $q{《名医别录》}：【芍药】味酸。微寒。有小毒。主通顺血脉。缓中。散恶血。逐贼血。去水气。利膀胱大小肠。消痈肿。时行寒热。中恶。腹痛。腰痛。一名白木。一名余容。一名犁食。一名解仓。一名铤。生中岳及丘陵。二月八月采根。暴干。（须丸为之使。恶石斛芒消。畏消石鳖甲小蓟。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0p1dUWRsS6D', 1, '{"title":"干姜","description":"<p>7、$u{干姜}</p>\r\n<p>$q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。</p>\r\n<p>$q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":6,"yaoNames":"","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '7、$u{干姜} $q{《神农本草经》}：【干姜】味辛。温。主治胸满。咳逆上气。温中。止血。出汗。逐风湿痹。肠澼下痢。生者尤良。久服去臭气。通神明。生犍为川谷。 $q{《名医别录》}：【干姜】大热。无毒。主治寒冷腹痛。中恶。霍乱。胀满。风邪诸毒。皮肤间结气。止唾血。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VHE7Y68l232', 1, '{"title":"茯苓","description":"<p>8、$u{茯苓}</p>\r\n<p>$q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。</p>\r\n<p>$q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":7,"yaoNames":"伏菟","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '8、$u{茯苓} $q{《神农本草经》}：【茯苓】味甘。平。主胸胁逆气。忧恚。惊邪恐悸。心下结痛。寒热。烦满。咳逆。止口焦舌干。利小便。久服安魂魄养神。不饥。延年。一名伏菟。生太山山谷。 $q{《名医别录》}：【茯苓】无毒。止消渴。好唾。大腹淋沥。膈中痰水。水肿淋结。开胸府。调藏气。伐肾邪。长阴。益气力。保神守中。其有根者。名茯神。', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GIXSHBaFv0L', 1, '{"title":"人参","description":"<p>9、$u{人参}</p>\r\n<p>$q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。</p>\r\n<p>$q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":8,"yaoNames":"人衔,鬼盖,神草,人微,土精,血参","aliases":[]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '9、$u{人参} $q{《神农本草经》}：【人参】味甘。微寒。主补五藏。安精神。定魂魄。止惊悸。除邪气。明目。开心益智。久服轻身延年。一名人衔。一名鬼盖。生上党山谷。 $q{《名医别录》}：【人参】微温。无毒。主治肠胃中冷。心腹鼓痛。胸胁逆满。霍乱吐逆。调中。止消渴通血脉。破坚积。令人不忘。一名神草。一名人微。一名土精。一名血参。如人形者有神。生上党及辽东。二月四月八月上旬采根。竹刀刮。暴干。无令见风。（茯苓为之使。恶溲疏。反藜芦。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jT011T7yIVO', 1, '{"title":"附子","description":"<p>10、$u{附子}</p>\r\n<p>$q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。</p>\r\n<p>$q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）</p>","content_format":"html","_microfeed":{"bookId":"tcmyao00001","bieMing":"","no":9,"yaoNames":"茛","aliases":[{"bieming":"大附子","name":"附子"}]}}', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '2024-09-14T16:56:57.000Z', '10、$u{附子} $q{《神农本草经》}：【附子】味辛。温。主治风寒咳逆。邪气。温中。金创。破癥坚积聚。血瘕。寒湿踒躄。拘挛。膝痛不能行走。生犍为山谷。 $q{《名医别录》}：【附子】味甘。大热。有大毒。主治脚疼冷弱。腰脊风寒。心腹冷痛。霍乱转筋。下痢赤白。坚肌骨。强阴。又堕胎。为百药长。生犍为及广汉。八月采为附子。春采为乌头。（地胆为之使。恶蜈蚣。畏防风甘草黄芪人参乌韭大豆。）', '2024-09-14T16:56:57.000Z', 1, NULL, 'tcmyao00001', 'yao', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DkfqlBLEak4', 1, '{"title":"六气图","description":"<p>  六气图就是十二个时辰循环走向，如果从一天分阴阳，看那个阴阳的太极图，是一个圆的，不是一条线，没有瞬间就天黑的，瞬间就是白天，没有这种事，慢慢慢慢天黑，慢慢慢慢白天，这就是说阴和阳是慢慢慢慢在转换的。</p>\n<p>  十二个时辰里面，分六个气，</p>\n<p>      第一个蕨阴气，亥时-已时，这两个时辰是相对的，蕨阴的意思就是阴的刚开始的时候，它是阳准备结束了，阴开始初进的时候</p>\n<p>      第二个少阴气，子时-午时,是少阴，</p>\n<p>      第三个太阴气，丑-未时，是太阴，</p>\n<p>      第四个少阳气，寅-申时,是少阳，阳开始起来了一点，</p>\n<p>      第五个阳明气，卯-酉时,是阳明，</p>\n<p>      第六个太阳气，辰-戌时,叫做太阳，</p>\n<p>  这个是一天的六气，它的循环六气</p>","content_format":"html","_microfeed":{"bookId":"tcmterm0001","beiMing":"","type":"易理","no":0,"mingCiList":"六气图","sourceImagePath":"Upload/Images/2024-11-14/hid4oOJCpnXmR0k6wFhPqEIRu3zzdcDj.png"}}', '2024-09-15T00:56:57.000Z', '2024-09-15T00:56:57.000Z', '2024-09-15T00:56:57.000Z', '六气图就是十二个时辰循环走向，如果从一天分阴阳，看那个阴阳的太极图，是一个圆的，不是一条线，没有瞬间就天黑的，瞬间就是白天，没有这种事，慢慢慢慢天黑，慢慢慢慢白天，这就是说阴和阳是慢慢慢慢在转换的。 十二个时辰里面，分六个气， 第一个蕨阴气，亥时-已时，这两个时辰是相对的，蕨阴的意思就是阴的刚开始的时候，它是阳准备结束了，阴开始初进的时候 第二个少阴气，子时-午时,是少阴， 第三个太阴气，丑-未时，是太阴， 第四个少阳气，寅-申时,是少阳，阳开始起来了一点， 第五个阳明气，卯-酉时,是阳明， 第六个太阳气，辰-戌时,叫做太阳， 这个是一天的六气，它的循环六气', '2024-09-15T00:56:57.000Z', 1, NULL, 'tcmterm0001', 'term', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Lhfd7ApQxCh', 1, '{"title":"八纲辨症","description":"<p>中医所谓的八纲辨症，阴,阳,表,里,虚,实,寒,热。</p>","content_format":"html","_microfeed":{"bookId":"tcmterm0001","beiMing":"","type":"医理","no":1,"mingCiList":"中医八纲辨症","sourceImagePath":""}}', '2024-11-19T05:37:29.000Z', '2024-11-19T05:37:29.000Z', '2024-11-19T05:37:29.000Z', '中医所谓的八纲辨症，阴,阳,表,里,虚,实,寒,热。', '2024-11-19T05:37:29.000Z', 1, NULL, 'tcmterm0001', 'term', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5AyRQUwA4EW', 1, '{"title":"太阳","description":"<p>对于太阳,可以代表经络中的太阳经,也可以代表全体阴阳状态的太阳。</p>\n<p>八纲辨症中表里的“表”,在这里指的就是太阳。</p>\n<p>病如果是外来的，初犯的时候一定是在表，病在外面，表就是在外面。张仲景把这个表就叫做太阳。</p>\n<p>太阳为寒水所以常人皮肤表面是冰凉的手脚是温热的,体表有这太阳的寒水,可以保卫我们不受外界寒热的影响,调节体温。这寒水不是停滞的,是不断的代谢更的。</p>","content_format":"html","_microfeed":{"bookId":"tcmterm0001","beiMing":"","type":"医理","no":2,"mingCiList":"","sourceImagePath":""}}', '2024-11-19T06:11:44.000Z', '2024-11-19T06:11:44.000Z', '2024-11-19T06:11:44.000Z', '对于太阳,可以代表经络中的太阳经,也可以代表全体阴阳状态的太阳。 八纲辨症中表里的“表”,在这里指的就是太阳。 病如果是外来的，初犯的时候一定是在表，病在外面，表就是在外面。张仲景把这个表就叫做太阳。 太阳为寒水所以常人皮肤表面是冰凉的手脚是温热的,体表有这太阳的寒水,可以保卫我们不受外界寒热的影响,调节体温。这寒水不是停滞的,是不断的代谢更的。', '2024-11-19T06:11:44.000Z', 1, NULL, 'tcmterm0001', 'term', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ptIyz151sbW', 1, '{"title":"真寒假热","description":"<p>面色：两颧色红，界限分明，红部虽鲜艳，而不红部则白中带青。  </p>\n<p></p>\n<p>口鼻气：呼出气不温，且不急促，气亦不臭。 舌形：舌虽干而质淡，或红而质润。  </p>\n<p></p>\n<p>脉象：脉虽浮数，按之则无力。  </p>\n<p></p>\n<p>按胸腹：胸腹部按之不蒸手，初按似热，久按不如平人，不觉甚热。</p>","content_format":"html","_microfeed":{"bookId":"tcmterm0001","beiMing":"","type":"医理","no":3,"mingCiList":"","sourceImagePath":""}}', '2024-11-19T09:12:51.000Z', '2024-11-19T09:12:51.000Z', '2024-11-19T09:12:51.000Z', '面色：两颧色红，界限分明，红部虽鲜艳，而不红部则白中带青。 口鼻气：呼出气不温，且不急促，气亦不臭。 舌形：舌虽干而质淡，或红而质润。 脉象：脉虽浮数，按之则无力。 按胸腹：胸腹部按之不蒸手，初按似热，久按不如平人，不觉甚热。', '2024-11-19T09:12:51.000Z', 1, NULL, 'tcmterm0001', 'term', NULL);
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nj9rMl8hcxE', 1, '{"title":"真热假寒","description":"<p>面色：面色表虽冷，面色虽滞，两目则炯炯有神。 口鼻气：呼出气必温，且急促，或有不臭。 舌形：舌虽干而质燥，苔虽薄而根必厚，或黄而疏松，或润而齿枯。  </p>\n<p></p>\n<p>脉象：脉虽沉细，必兼数急。  </p>\n<p></p>\n<p>按胸腹：四肢虽寒，胸腹必热，久按且蒸蒸有热气感。  </p>\n<p></p>\n<p>以后我们会常看到上寒下热，而不用真寒假热、或真热假寒，看到上热下寒，就是告诉你去热和去寒的药必须同用。  </p>\n<p></p>\n<p>医圣张仲景在伤寒论中不谈阴虚内热，他用的是阴盛、阴亡、阳盛、阳亡，所谓的阴盛就是阴实，阳盛就是阳实。温病派的医生看到每个人都是阴虚，都想到用补药，但是张仲景治病的时候不用补药。他治病的时候小补的时候用炙甘草，中补用大枣、白芍，大补的时候加人参，补阴的药顶多就是这样，反而阳药用的很多。所以治病的时候不用补药。那什么时候吃补药？身体健康的时候才吃补药。这与温病派的观念完全不同。  </p>","content_format":"html","_microfeed":{"bookId":"tcmterm0001","beiMing":"","type":"医理","no":4,"mingCiList":"","sourceImagePath":""}}', '2024-11-19T09:14:33.000Z', '2024-11-19T09:14:33.000Z', '2024-11-19T09:14:33.000Z', '面色：面色表虽冷，面色虽滞，两目则炯炯有神。 口鼻气：呼出气必温，且急促，或有不臭。 舌形：舌虽干而质燥，苔虽薄而根必厚，或黄而疏松，或润而齿枯。 脉象：脉虽沉细，必兼数急。 按胸腹：四肢虽寒，胸腹必热，久按且蒸蒸有热气感。 以后我们会常看到上寒下热，而不用真寒假热、或真热假寒，看到上热下寒，就是告诉你去热和去寒的药必须同用。 医圣张仲景在伤寒论中不谈阴虚内热，他用的是阴盛、阴亡、阳盛、阳亡，所谓的阴盛就是阴实，阳盛就是阳实。温病派的医生看到每个人都是阴虚，都想到用补药，但是张仲景治病的时候不用补药。他治病的时候小补的时候用炙甘草，中补用大枣、白芍，大补的时候加人参，补阴的药顶多就是这样，反而阳药用的很多。所以治病的时候不用补药。那什么时候吃补药？身体健康的时候才吃补药。这与温病派的观念完全不同。', '2024-11-19T09:14:33.000Z', 1, NULL, 'tcmterm0001', 'term', NULL);
